window.__D("text/likkutei-sichot/c115",{"p":[[1300171355,"ג. וועט מען דאָס פאַרשטיין לויטן ביאור הידוע פון דער משנה<sup data-n=\"9\">9</sup>:\n„עולם הבא\" מיינט — עולם התחי' 9*, נשמות בגופים. און דאָס איז דער חידוש המשנה „כל ישראל יש להם חלק לעולם הבא\": דער<sup data-n=\"10\">10</sup> שכר פון גן עדן — עולם הנשמות — איז ניט גלייך ביי „כל ישראל\" (ביז אז עס זיינען דאָ אַזוינע וואָס זיינען בכלל ניט זוכה צו ג\"ע<sup data-n=\"11\">11</sup>; משא\"כ עולם הבא — עולם התחי', ווען נשמות וועלן זיין בגופים — איז (בעיקרו) „בשוה לכל ישראל\"<sup data-n=\"12\">12</sup>, „כל ישראל יש להם חלק לעולם הבא\"<sup data-n=\"13\">13</sup>.\nדער טעם דערויף איז 13*: דער שכר פון גן עדן — נשמות בלי גופים — איז (בעיקר) אויף לימוד התורה<sup data-n=\"14\">14</sup>, וואָס איז פאַרבונדן בעיקר מיט דער נשמה (מיט איר כח השכל): תחיית המתים איז דער שכר פאַר קיום המצות, וואָס ווערט געטאָן מיט און דורכן גוף דוקא (וואָס דערפאַר באַקומט די נשמה דעם שכר פאַר דעם ווען זי איז צוזאַמען מיט דעם גוף) 14*).\nאון וויבאַלד אז ביי השגת התורה זיינען פאַראַן (און דאַרפן זיין<sup data-n=\"15\">15</sup> חילוקים צווישן איין איד מיט אַ צווייטן ביז — מן הקצה אל הקצה<sup data-n=\"16\">16</sup>, דערפאַר זיינען ניט „כל ישראל\" גלייך אין דעם שכר אויף דער עבודה — גן עדן:\nמשא\"כ עיקר קיום המצות איז אַן ענין פון עשי', וואָס יעדערער קען דאָס טאָן, און יעדער איד טוט עס טאַקע און איז מקיים מצות, ביז (כמאמר רז\"ל<sup data-n=\"17\">17</sup> אז אפילו פושעי ישראל „מלאין מצות כרמון\" — און היות אז די עבודה פון מצות איז דאָ ביי אַלע אידן<sup data-n=\"16\">16</sup>, דערי־ בער איז „כל ישראל יש להם חלק לעולם הבא\".\nד. מען דאַרף אָבער פאַרשטיין: ווי־ באַלד אז דער עיקר תשלום השכר איז בזמן (לאחרי) תחיית המתים, איז דער־ פון מובן, אז דער שכר פון תחה\"מ איז העכער פון דעם שכר אין ג\"ע — היינט ווי שטימט עס דערמיט, וואָס ג\"ע איז דער שכר אויף אַ העכערן אופן עבודה (השגת התורה) וואָס איז ניט שייך אויף",[["9","9","עיי\"כ הל' תשובה להרמב\"ם פ\"ג (ה\"ו ואילך) ופ\"ד. חיבור התשובה להמאירי. ועוד. 9*) רע\"ב (ועוד) סנהדרין שם. מדרש שמואל כאן. וראה הנסמן בתשובות וביאורים סי' ח' הערה 1. וראה לקמן הערה 26."],["10","10","ראה בהבא לקמן: תו\"א יתרו עג, ב (וראה לקו\"ת שלח מו, ד). ד\"ה כי ישאלך עטר\"ת וה\"ש\"ת פ\"א. המשך תער\"ב ח\"ב ע' איקיב ואילך. וראה בארוכה תשובות וביאורים שם."],["11","11","ראה חגיגה (טו, ב) דלולי תפלת ר\"מ לא הי' אחר נכנס לג\"ע. וראה חגיגה (שם, א) „נטל חלקו וחלק חברו (הרשע) בג\"ע\"."],["12","12","ל' הלקרי\"ת שם. וראה המשך תער\"ב שם, דאף שגם בתחה\"מ יש חילוקי מדרי' מ\"מ יש חילוק בזה בין ג\"ע לתחה\"מ, עיי\"ש."],["13","13","ויש אלה שלמעלה מדרגא זו — בן עוה\"ב ומזומן לחיי עוה\"ב (ראה שער מאמרי רז\"ל לסנהדרין שם). וי\"ל דבכלל מאתים מנה. 13*) בד\"ה כי ישאלך הנ\"ל (וראה תו\"א שם) מבאר הטעם, כי בג\"ע מאיר מבחי' ממכ\"ע שיש בה התחלקות, ובתחה\"מ — מבחי' סוכ\"ע שלמעלה מהתחלקות ולכן מאיר לכל ישראל בשוה. אבל מובן, שסיבת החילוק בין השכר דג\"ע ותחה\"מ היא מצד החילוק בהעבודות המביאות ב' סוגי שכר הנ\"ל, כדלקמן בפנים (ולכאורה כ\"ה הפי' במ\"ש בתו\"א שם: ובבחי' זו אפי' פושעי ישראל מלאים מצות כרמון. וראה אמ\"ב שער הק\"ש פכ\"ה). *) אגרות קודש כ\"ק אדמו\"ר שליט\"א ח\"א ע' קמב. המו\"ל."],["14","14","להעיר אשר בג\"ע ישנו לימוד התורה (תניא פמ\"א (נח, סע\"א) מגמ' וזוהר. וראה מקומות שבהערה הבאה) ואין שם קיום מצות. 14*) ראה אגה\"ק סי\"ז. ובארוכה — סהמ\"צ להצ\"צ מצות ציצית פ\"א. ד\"ה כי ישאלך הנ\"ל. ובכ\"מ."],["15","15","שהרי לשלימות הקומה צ\"ל ראש כר ורגל."],["16","16","ראה סד\"ה בשעה שהקדימו תער\"ב. ועוד."],["17","17","חגיגה בסופה."]]],[1300171356,"אַ גלייכן אופן ביי יעדער איד, און דער שכר פון תחה\"מ איז אויף עשיית המצות, אַ פיל „פּשוט'ערע\" עבודה, און וואָס איז דערפאַר דאָ ביי אַלע אידן?\nאיז דער ביאור אין דעם:\nאע\"פ אז בחיצוניות, איז דער טעם וואָס אַלע אידן גלייכן זיך אויס אין עניני עשי', איז עס דערפאַר ווייל עשי' איז נידעריקער פון אַלע כוחות, עס איז אַן ענין וואָס איז ניט מכריח רגש הלב און ניט קיין הבנה והשגה שבמוח — איז אָבער דער טעם פנימי דערפון, מצד דער מעלה וואָס איז דאָ אין עשי' — ובלשון המשנה במס' אבות<sup data-n=\"18\">18</sup> המעשה עיקר:\nדי פנימיות הכוונה העליונה איז, אז אידן זאָלן מאַכן אַ דירה לו ית' בתחתונים, אין עוה\"ז התחתון שאין תחתון למטה ממנו<sup data-n=\"19\">19</sup>, וכמאמר<sup data-n=\"20\">20</sup>: סוף מעשה במחשבה תחלה. און די כוונה ווערט דורכגעפירט בעיקר דורך דער עבודה פון מעשה המצות, וואָס דורך זיי ווערט אויפגעטאָן דער בירור וזיכוך פון גוף ועניני העולם, ווי ערקלערט אין תניא<sup data-n=\"21\">21</sup> בארוכה.\nאון ווייל אַלע אידן זיינען — בלשון הכתוב (הראי' שבמשנתנו) — „נצר מטעי מעשה ידי\" של הקב\"ה — דער־ הערט יעדער איד די כוונה און פירט איר דורך בפועל. אין „גילויים\" זיינען דאָ חילוקים צווישן אידן מיט אַ צווייטן (ביז עס קען זיין אַזאַ וואָס איז ניט קיין כלי צו זיי), אָבער בשייכות צו דער כוונת העצמות „לעשות לו ית' דירה בתחתונים\" — וואָס דאָס ווערט\nדערהערט אין דער עצמיות פון אַ אידן — זיינען אַלע אידן גלייך<sup data-n=\"22\">22</sup>.\nה. און דאָס איז אויך דער טעם פאַר־ וואָס דער תשלום השכר אין עולם הבא איז צו נשמות בגופים דוקא:\nמצד דעם וואָס די כוונה פון אויבערשטן איז אז ער זאָל האָבן אַ דירה בתחתונים, שפּיגלט זיך דאָס אָפּ אויך אין אידן<sup data-n=\"23\">23</sup> — וואָס זיי זיינען כביכול איין זאַך מיט עצמות — און די בחירת הקב\"ה אין זיי איז (ניט נאָר בחירת נשמתם, נאָר אויך) פון זייער גוף<sup data-n=\"24\">24</sup>;\n[וואָס דערפאַר איז אויך דער גוף פון אַ אידן אַ מציאות נצחית וועלכע ווערט ניט נפסד, וכידוע<sup data-n=\"25\">25</sup> אז דער „עצם לוז\" ווערט ניט נפסד, און פון דעם „עצם לוז\" וועט נבנה ווערן דער גאַנצער גוף בתחיית המתים].\nאון דעריבער, בשעת עס וועט זיך ענדיקן די עבודה פון בירור וזיכוך העולם און די וועלט וועט ווערן אַ דירה לו ית', וועט אויך ביי אידן זיין בגלוי ווי ס'איז די בחירת הקב\"ה (אויך) אין זייער גוף, וואָס דערפאַר זיינען די חיים נצחיים פון עולם הבא (אויך) אין גוף.\nו. עפ\"ז וועט ווערן פאַרשטאַנדיק פאַרוואָס מען איז מקדים די משנה (כל ישראל) צום לימוד פון מס' אבות:",[["18","18","פ\"א מי\"ז."],["19","19","תניא פל\"ו."],["20","20","פיוט לכה דודי. וראה תו\"א ר\"פ ויגש. ועוד."],["21","21","פל\"ז."],["22","22","להעיר מהמבואר (תו\"א יד, ב. ד\"ה חכמות בחוץ תרצ\"ד (סה\"מ קונט' ח\"ב) פ\"ב) שהמאור הוא בהתגלות ולכן ש\"ש שגור בפי כל."],["23","23","להעיר ממכתב כ\"ק מו\"ח אדמו\"ר (נדפס ב„התמים\" ח\"א ע' ל') דכשם שבעולמות התכלית הוא עוה\"ז התחתון כמו\"כ בהאדם התכלית הוא בעיקר כח המעשה, ע\"ש."],["24","24","תניא פמ\"ט. ובארוכה — ס' השיחות תורת שלום ע' 120 ואילך."],["25","25","ב\"ר פכ\"ח, ג. וש\"נ. זח\"ב כח, ב. ועוד. תוד\"ה והוא (ב\"ק טז, ב)."]]],[1300171357,"כדי צו אַרויסברענגען ווי דער קיום און לימוד פון מס' אבות — וואָס ברענגט צו בירור וזיכוך פון חומריות הגוף — איז נוגע צו יעדן אידן, איז מען מקדים אז „כל ישראל יש להם חלק לעולם הבא\" (עולם התחי', נשמות בגופים), דערפאַר וואָס (אויך) דער גוף פון „כל ישראל\" איז „מעשה ידי\" של הקב\"ה<sup data-n=\"26\">26</sup>; ואדרבה, דוקא אין „מעשה ידי\" איז דאָ דער „להתפאר\", וואָרום דוקא „סוף מעשה\" איז „במחשבה תחלה\".\nאון דערפאַר קען זיך קיין שום איד ניט להבטל ממנה<sup data-n=\"27\">27</sup>, אויף ניט מקיים זיין מילי דאבות — און אין ביידע קצוות:\nס'איז ניטאָ קיין גוף וואָס קען ניט נתברר ווערן, וואָרום דער גוף פון\nיעדער איד איז מעשה ידי של הקב\"ה, איז ניט שייך אז ער זאָל קענען נתברר ווערן<sup data-n=\"28\">28</sup>. און נאָכמער: זייענדיק מעשה ידיו של הקב\"ה איז זיכער אז בל ידח ממנו נידח<sup data-n=\"29\">29</sup>, און ער וועט סו\"ס זיכער נתברר ווערן;\nאון לאידך: די עבודה איז ניט צו „נידעריק\" פאַר וועלכן־ס'איז אידן. ואדרבה, די אמת'ע „מילי דחסידותא\" זיינען אין דער עבודה פון בירור וזיכוך הגוף<sup data-n=\"30\">30</sup>, ווייל דוקא אין „מעשה ידי\" איז דאָ דער „להתפאר\", וכנ\"ל אז „סוף מעשה במחשבה תחלה\".\n(ממאמרי ושיחת ש\"פ אחרי תשל\"ג)",[["26","26","ע\"פ המבואר בפנים — ש„מעשה ידי\" קאי על הגוף — מתורץ מה שהתנא מביא גם סיום הכתוב (וכקושיית המפרשים) — כי דוקא מזה מוכח שאיירי בעולם התחי' שהוא נשמות בגופים (משא\"כ הלשון „ארץ\" אפשר לפרש על ג\"ע — ראה לקו\"ת ואתחנן ט, א. ועוד). ועפ\"ז מובן מה שהרמב\"ם לא גריס סיום הכתוב במשנה (ראה פיה\"מ הוצאת קאפח סנהדרין שם. רמב\"ם הל' תשובה פ\"ג ה\"ה. וראה שינויי נוסחאות למשניות סנה' שם), כי לדעתו עולם הבא קאי על (ג\"ע) עולם הנשמות (ראה פיה\"מ חלק שם. וראה הל' תשובה פ\"ח)."],["27","27","אבות ספ\"ב."],["28","28","חוץ מאלו שאין להם חלק לעוה\"ב (סנה' שם) שגופם כלה (ראה תשובות וביאורים שם אות ד', וש\"נ). וראה לקו\"ש חי\"ח ע' 409 הערה 71 ובשוה\"ג שם. ואכ\"מ."],["29","29","ראה עד\"ז תורת שלום ע' 135. וראה שם ע' 11."],["30","30","ראה גם לקמן ע' 417. ולהעיר ממכתב כ\"ק אדמו\"ר מהורש\"ב נ\"ע (נדפס בקונטרס ומעין ע' 17. היום יום בתחלתו): להמשיך בחי' עומק ופנימיות תורת ה' .. לגרש מאתנו כל מדה רעה ומגונה מהמדות הטבעיות כו' (נת' בשיחת ש\"פ וישב תשכ\"א). *) נדפס בקונטרס בפ\"ע (קה\"ת, תש\"נ). המו\"ל. *) אגרות קודש שם ע' קמח ואילך. המו\"ל."]]],[1300171358,"<h3>פרק ראשון</h3>\nא. „שמאי אומר עשה תורתך קבע, אמור מעט ועשה הרבה, והוי מקבל את כל האדם בסבר פנים יפות“1.\nדער פירוש הפשוט פון די דריי בבות פון די משנה איז (ווי מפרשים זאָגן<sup data-n=\"2\">2</sup>: „עשה תורתך קבע“ — „שיהי' עיקר עסקך ביום ובלילה בתורה, וכשתהי' יגע מן הלמוד תעשה מלאכה ולא שיהי' עיקר עסקך במלאכה“, וכמארז\"ל3 „עשו תורתן קבע ומלאכתן עראי“; „אמור מעט ועשה הרבה“ — צוזאָגן ווייניק „ועשה הרבה“ מער ווי מ'האָט צוגע־זאָגט „כמו שמצינו באברהם שאמר תחלה4 ואקחה פת לחם ובסוף5 ויקח בן בקר רך וטוב“; „והוי מקבל את כל האדם בסבר פנים יפות — „כשאתה מכניס אורחים לביתך לא תתן להם ופניך כבושות בקרקע“.\nלפ\"ז איז תמוה: אין מס' אבות רעדט זיך (נאָר) מילי דחסידותא, ווי רז\"ל6 זאָגן „האי מאן דבעי למהוי חסידא וכו' לקיים מילי דאבות“ — ד.ה. אַז דאָס זיינען הנהגות וואָס אַ איד איז אין זיי ניט מחויב מצד הדין וההלכה, נאָר ער דאַרף זיי טאָן מצד מידת חסידות — לפנים7 משורת הדין8; אָבער די דריי ענינים הנ\"ל זיינען לכאורה ניט אין סוג פון „מילי דחסידותא“ — זייער חיוב איז מובן פון זיך אַליין, אָדער מ'קען זיי פאַרשטיין און אָפלערנען פון אַנדערע ציווים אין תורה און הלכה9:\nא) „עשה תורתך קבע“ — דעם זעלבן לשון געפינט מען שוין אין חיובי רז\"ל און ס'איז אַראָפגעבראַכט להלכה10: עשה תורתך קבע11 ומלאכתך עראי (היינט אין וואָס באַשטייט דער חידוש דאָ אַלס מידת חסידות<sup data-n=\"12\">12</sup>; אויך געפינט",[["1","1","משנה טו (וכ\"ה בסדור אדה\"ז). בפיה\"מ להרמב\"ם (הוצאת קאפח) היא משנה יד."],["2","2","רע\"ב. וראה גם פרש\"י, רמב\"ם, רבינו יונה ומאירי. וראה לקמן ס\"ג והערה 28."],["3","3","ברכות לה, ב."],["4","4","וירא יח, ה."],["5","5","שם, ז."],["6","6","ב\"ק ל, א."],["7","7","בב\"ק שם לפנ\"ז (דעת ר\"י) „לקיים מילי דנזיקין“. וגם בזה י\"ל דכוונתו שמקיים מילי דנזיקין באופן דלפנים משורת הדין (ועד\"ז י\"ל לה„אמרי לה מילי דברכות“ שם — ע\"ד ברכות כ, ב) — ראה הקדמת המהר\"ל מפראג לספרו דרך חיים ד\"ה ומפני וד\"ה וסדר."],["8","8","ראה רמב\"ם הל' דיעות פ\"א ה\"ה. המשך תער\"ב ח\"ב פשע\"ז (ע' תשעג). וידועה ראיית אדה\"ז ממרז\"ל (נדה יז, א ותוס' שם) שורפן חסיד אע\"פ שמזיק לו — לקו\"ד ח\"א סח, א."],["9","9","ועד\"ז יש להקשות בכמה פירושים שבמדרש שמואל (ס' שהובא בדא\"ח בכ\"מ)."],["10","10","רמב\"ם הל' ת\"ת פ\"ג ה\"ז. טושו\"ע (ואדה\"ז) או\"ח ר\"ס קנו. הל' ת\"ת לאדה\"ז פ\"ג ס\"ב. ובמקומות הנ\"ל מובן שהפי' ב„תורתך קבע“ הוא כפשוטו — בזמן, שרוב ועיקר זמנו יעסוק בתורה, ורק מיעוט זמן במלאכה. וראה לקמן הערה 14."],["11","11","וגם: הרי למדין זה מפסוק מפורש ודברת בם (ואתחנן ו, ז ובספרי. יומא יט, ב. שו\"ע אדה\"ז הל' ת\"ת שם ס\"ב. וראה קו\"א שם סק\"א קרוב לסופו, שהרמב\"ם ס\"ל דדרשה גמורה היא ולא אסמכתא)."],["12","12","מלשון הטור (שם סקנ\"ו) מוכח, דהנהגה זו דתורתו קבע ומלאכתו עראי, היא מדת חסידות („כמו שמצינו בחסידים הראשונים“) — ראה קו\"א הנ\"ל בסופו. אבל באם כן הוצרך שמאי להוסיף (גם כאן) ומלאכתך עראי (כדלקמן ס\"ב קושיא הב'), כיון שבזה הוא עיקר ההדגשה. ולהעיר שבטור שם מקדים „מלאכתן עראי“ לפני „תורתן קבע“. וראה לקמן הערה 14."]]],[1300171359,"מען כמה וכמה פסוקים ומארז\"ל, וואו ס'ווערט אָנגעזאָגט וועגן דעם חיוב תמידי פון לימוד ועסק התורה [און ווי ס'שטייט אין אָנהויב פון דעם פרק13 גופא: „על שלשה דברים העולם עומד, על התורה וכו'“, און וויבאַלד תורה איז פון די „עמודים“ אויף וועלכע ס'האַלט זיך דער קיום העולם, איז דערפון אויך מובן אַז עס דאַרף זיין „תורתך קבע“]14.\nב) „אמור מעט“ — ס'איז אַ ציווי אין תורה15 „לא יחל דברו“, וואָס דער ציווי איז מחייב די הנהגה פון „אמור מעט“, אַז מ'זאָל זיין געהיט אין רייד און ניט צוזאָגן סיידן מ'איז אינגאַנצן זיכער אַז מ'וועט עס קענען ממלא זיין16, כדי מ'זאָל ניט נכשל ווערן אינעם איסור17 פון „לא יחל דברו“18. אויך אין דעם אויספיר פון דעם פאַל „ועשה הרבה“, איז לכאורה ניטאָ קיין חידוש מיוחד מצד מדת חסידות19: אויב אַ איד האָט ביכולת צו טאָן אַ סך מצות ומע\"ט דאַרף ער דאָס טאָן20?\nג) און אַזוי אויך דער סיום פון דעם מאמר: „והוי מקבל את כל האדם בסבר פנים יפות“ — לכאורה איז דאָס אַ הנהגה וואָס פאָדערט זיך מצד ועשית הטוב והישר, איינפאַכן נימוס און דרך ארץ, נאָכמער — מצד דעם ציווי21 ואהבת לרעך כמוך (מה דעלך סני לחברך לא תעביד<sup data-n=\"22\">22</sup>, און ניט דוקא מצד מדת חסידות23?\nב. אויך דאַרף מען פאַרשטיין (נאָך אייניקע דיוקים) אין דער משנה:\nא) וויבאַלד אַלע דריי פאַלן זיינען געזאָגט געוואָרן צוזאַמען אין איין מאמר (וואָרום שמאי האָט דאָך זיכער",[["13","13","משנה ב'."],["14","14","וכן להפי' „עשה תורתך קבע“, שיקבע עתים לתורה (מחז\"ו בפי' הא' (וראה נ\"א ברש\"י כאן), מילי דאבות (פי' הב')), הרי פשיטא שזהו חיוב, דאל\"כ יתבטל מהתורה לגמרי (מחז\"ו שם). ועוד: ה\"ז חיוב מצות והגית בו יומם ולילה (רמב\"ם שם פ\"א ה\"ח. הל' ת\"ת לאדה\"ז שם ס\"ד. וראה טושו\"ע (ואדה\"ז) סקנ\"ה). לכאורה י\"ל (וראה מילי דאבות (פי' הא'), מגן אבות (להרשב\"ץ), נחלת אבות (בשם המפרשים)) שהוראת שמאי „עשה תורתך קבע“ הוא למי „שלא הגיע למדה זו שיוכל ללמוד טעמי ההלכות כו' אף אם יעשה תורתו קבע מחמת קוצר דעתו ונקרא בור כו' אינו חייב כו' לעשות מלאכתו עראי כדי להרבות בלימוד כו' אא\"כ עושה במדת חסידות ואהבת התורה, אבל מן הדין יוצא יד\"ח בקביעות עתים לת\"ת“ (הלכות ת\"ת לאדה\"ז שם ס\"ד. וראה קו\"א שם סק\"א קרוב לסופו). וזהו מילתא דחסידותא שבדברי שמאי, אבל א) דוחק לומר שהוראת שמאי הוא רק לזה „שנקרא בור כו'“, ב) ועיקר: אז הו\"ל להדגיש ולסיים (העיקר) „ומלאכתך עראי“, ע\"ד מ\"ש לקמן פ\"ד מ\"י „הוי ממעט בעסק ועסוק בתורה“, ג) הוראה זו נאמרה באבות פ\"ד שם (ראה לקו\"ש ח\"ז ע' 176-7 והערה 12)."],["15","15","מטות ל, ג."],["16","16","ולהעיר שנצטווינו (קדושים יט, לו) הין צדק יהי' לכם „שיהא הן שלך צדק ולאו שלך צדק“ (ב\"מ מט, א. פרש\"י שם. וראה שו\"ע אדה\"ז או\"ח סי' קנו ס\"ב ובהמצוין שם)."],["17","17","ראה נדרים כב, א. עז, ב. שו\"ע יו\"ד רסר\"ג."],["18","18","וראה ג\"כ קהלת (ה, א) „ע\"כ יהיו דבריך מעטים“ ובמפרשים שם."],["19","19","אף שיש לפרש שהחידוש הוא רק ב„אמור מעט“, שתמיד תהי' אמירתו מעט לגבי עשיותיו."],["20","20","יתרה מזו: צריך כל אדם כו' לשקול ולבחון בעצמו אם הוא עובד ה' בערך ובחי' מלחמה עצומה כו' בבחי' ועשה טוב כו' הרבה יותר מחפצו ורצונו לפי טבעו ורגילותו כו' (עיין תניא פ\"ל)."],["21","21","קדושים יט, יח. ובפרט שלקבל בספ\"י הוא פחות מלקבל בשמחה (פיה\"מ פ\"ג, מי\"ב)."],["22","22","ופשוט שאין לומר שזהו חידושו של הלל דוקא (כ\"א — „זו היא כל התורה כולה ואידך פירושה הוא“), ואדרבא זהו פחות מ„ואהבת לרעך כמוך“ (ראה שבת לא, א ובחדא\"ג שם)."],["23","23","ויתירה מזו, הרי (לפי' הרע\"ב וכו') זה בכלל מצות הכנסת אורחים גופא, כי (בל' הרע\"ב עצמו מאבות דר\"נ פי\"ג בסופו) כל הנותן ופניו כבושות בקרקע אפי' נתן כל מתנות שבעולם כו' כאילו לא נתן כלום. ועד\"ז בצדקה דכאשר נותנו בסבר פנים רעות ופניו כבושות בקרקע כו' אבד זכותו והפסידה (רמב\"ם הל' מתנות עניים פ\"י ה\"ד)."]]],[1300171360,"געזאָגט נאָך פיל מאמרים בהנהגות האדם, און נאָר די דריי זיינען דאָ גע־בראַכט געוואָרן אינאיינעם) איז משמע, אַז זיי האָבן צווישן זיך אַ קישור און אַ צוזאַמענהאַנג אין תוכן24?\nב) פאַרוואָס ווערט דאָ (ביים מאמר „עשה תורתך קבע“) ניט אַראָפגע־בראַכט דער אויספיר25 „ומלאכתך עראי“, ווי דאָס איז אין אַנדערע מרז\"ל26 (ווי דערמאָנט פריער)?\nג) ווי גערעדט מערערע מאָל27, האָט אויך דער (נאָמען פון) בעל המאמר אַ שייכות און גיט צו הבנה והדגשה צום ענין וואָס רעדט זיך אין מאמר — מיט וואָס ווערן די דריי ענינים הנ\"ל מער מוסבר דערמיט וואָס „שמאי“ איז דער וואָס האָט זיי געזאָגט?\nג. כאן המקום להעיר: כאָטש דער מקור פון פירוש הנ\"ל (סעיף א') איז אין אבות דר' נתן28, פונדעסטוועגן איז דאָ אַן אָרט אויך אויף אַ צווייטן אַנדערש־דיקן פירוש; און ווי מ'געפינט אין מס' אבות בכו\"כ משניות, אַז עס זיינען דאָ גאָר אַ סך פירושים פון גדולי ישראל (ווי רש\"י, רמב\"ם, מחזור וויטרי און נאָך ביז — אחרוני אחרונים), וועלכע האָבן מפרש געווען אַנדערש (און אפילו היפך'דיק) פון די פירושים אין אבות דר\"נ29, און האָבן אויך מעודד געווען תלמידיהם להתעמק ולחדש כיו\"ב — כמובן, בתנאי עיקרי ומוחלט עס זאָל זיין מתאים לכללי ודרכי לימוד התורה, מתוך זהירות רבה ואמתית בכבוד גדולי התורה (ופשיטא ניט „שרייען“ — „קבלו דעתי“), זהירות הכי גדולה אויף ניט מגלה זיין פנים בתורה שלא כהלכה ופסק הדין א.ז.וו.\nדערפון איז מובן, אַז דאָס איז ווי די פילצאָליגע (אויך היפכ'דיקע) פירושים אויף תורה שבכתב, וועלכע זיינען אַלע נכלל עכ\"פ אין פיטטיא דאורייתא טבין29* (און באַ אמת'ע גדולי ישראל — אין די שבעים פנים לתורה<sup data-n=\"30\">30</sup>; און בפרט אַז ס'איז דאָ דער חיוב „לאפשא בה“31 — וואָס מער צוגעבן, מחדש זיין אין תורה [און במיוחד ווען לויט דעם פריערדיקן פירוש זיינען פאַראַן באַ עם שוועריקייטן אין דעם ענין — דאַרף",[["24","24","ראה רע\"ב כאן (ועוד): ג' אזהרות הזהיר שמאי כנגד כו'. ובנחלת אבות בסופו מבאר טעם הסמיכות „כי מי שיעשה תורתו עיקר בכל מעשיו יאמר מעט ויעשה הרבה לפי שכן צותה תורה כו' ואם יעשה כן לא יהי' לו מחלוקת כו'“. אבל לפי\"ז אי\"ז ג' הוראות, כ\"א פרטים המסתעפים מאזהרה אחת."],["25","25","אף שי\"ל לפי שהמשנה הוא „דבר קצר“ (הקדמת הרמב\"ם לפיהמ\"ש ד\"ה אחר כן ראה להסתפק (בתחלתו)), מ\"מ הו\"ל לאומרו בלשון שתובן הכוונה (כנ\"ל הערה 12 (או) 14), או לשלול הפי' דלקמן ס\"ד."],["26","26","בבאורי הגר\"א נראה שגורס גם כאן „ומלאכתך עראי“ — אבל בהדפוסים אינו."],["27","27","ראה לקו\"ת שה\"ש ד\"ה ת\"ר כיצד מרקדין (מח, ג) ובכ\"מ עד\"ז. ור' מאיר דריש בשמא ומובא ע\"ז מעשה רב (יומא פג, ב. וראה תשובות וביאורים סי' א'. לקו\"ש ח\"ו ע' 35-6 ובהערות שם)."],["28","28","פי\"ג. וראה שם פכ\"ח, הובא ברבינו יונה, מגן אבות, נחלת אבות כאן בפי' דברי שמאי. *) אגרות קודש כ\"ק אדמו\"ר שליט\"א ח\"א ע' רפט ואילך. המו\"ל."],["29","29","להעיר מתויו\"ט נזיר פ\"ה מ\"ה במה שפי' הרמב\"ם משנה דלא כפי' הגמרא „דהרשות נתונה לפרש כו'“. ומובן שזהו דרך הלימוד, ולא משום דרב גוברי' דהרמב\"ם. וידועה השקו\"ט בזה. 29*) ירוש' ברכות בסופה."],["30","30","זח\"א מז, ב. ח\"ג כ, א (רע\"מ). רטז, א. רכג, א. במדב\"ר פי\"ג טו. ובכ' האריז\"ל (שער הגלגולים הקדמה יז. וכ\"כ בש' רוה\"ק בענין היחודים על קברי צדיקים הקדמה ג (קח, ב). וראה לקו\"ת ברכה צד, א), דמכיון שישנו ששים ריבוי נשמות ישנם ששים ריבוי פירושים, בפשט רמז דרוש וסוד (ראה לקמן בפנים)."],["31","31","זח\"א יב, ב. וראה אגה\"ק סכ\"ו (קמה, א). הלכות ת\"ת לאדה\"ז פ\"ב ס\"ב."]]],[1300171361,"מען אודאי זיך משתדל זיין, אויף וויפל שכלו קען דערגרייכן32, צו מפרש זיין באופן אַז ס'זאָל פאַרענטפערט ווערן די קושיות וכו', היות אַז אָן דעם וועט עם פעלן אין דער הבנה פון דעם ענין — און דאָס איז דאָך אַ הכרח אין לימוד תורה שבעל פה32*].\nד. וי\"ל דעם ביאור אין דעם:\nדי משנה („שמאי אומר כו'“) קומט בהמשך צו דער דערמאָנטער משנה אין אָנהייב פרק „על ג' דברים העולם עומד על התורה ועל העבודה ועל גמילות חסדים“, אַז עס זיינען דאָ דריי זאַכן, וואָס יעדע איינע פון זיי איז אַן „עמוד“ וואָס האַלט אויף דעם עולם. און דערי־בער, ווען אַ מענטש קען זיך ניט פאַר־נעמען בכל לבבו ונפשו ומאודו מיט די אַלע דריי צוזאַמען, דאַרף ער זיך אויס־קלייבן לכל־הפחות איין עמוד — קו פון די דריי33, אין וועלכן ער זאָל אַריינטאָן זיין עיקר34 חיות און התעסקות, און די אַנדערע צוויי — קומען דערנאָך34* (סיידן עס איז אַן ענין שהזמן גרמא וכיו\"ב, כמבואר בשו\"ע וכו').\nאון בשייכות מיט דעם זאָגט שמאי — לויטן דרך פון מילי דחסידותא: „עשה תורתך קבע“, אַז פון די דריי קוים זאָל ער בוחר זיין די הנהגה פון „תורתך קבע“35: אמת טאַקע, אַז ער האָט רשות צו אויסקלייבן וועלכן קו ער וויל36, ער קען זיך פירן ווי „זבולון“37 און זיין פון די „מארי עובדין טבין“ (באופן אַז זיין עיקר עבודה זאָל זיין אין קו פון גמילות חסדים<sup data-n=\"38\">38</sup>, אָבער מצד מידת חסידות דאַרף ער אויסקלייבן דעם קו פון תורה, אַז זי זאָל ביי אים זיין דער „קבע“ און דער עיקר39.\nאון דעריבער איז דאָ ניט מתאים דער אויספיר פון „ומלאכתך עראי“ — ווייל דאָ איז ניט די כוונה צו שולל זיין „מלאכה“, אַז זי זאָל ניט זיין בדרך „קבע“, נאָר צו מדגיש זיין און אויסטיילן דעם „קבע“ פון תורה לגבי די קוים פון „עבודה“ און „גמ\"ח“.",[["32","32","בל' אדה\"ז (הלכות ת\"ת פ\"א סוס\"ד) „כל נפש“. ו„כל מי שיכול להשיג ולידע הרבה ונתעצל ולא השיג וידע אלא מעט צריך לבוא בגלגול כו' וא\"א לה להתתקן ולהשתלם כו' בלתי ידיעה זו“. 32*) ראה הלכות ת\"ת שם ספ\"ב."],["33","33","ראה תו\"א פ' תרומה. ביאוה\"ז וישב (כה, א־ב) ולהצ\"צ (ע' קלד). ולהעיר גם ממחז\"ל תלמוד גדול או מעשה גדול (קדושין מ, ב. תקו\"ז ו, א). וראה ג\"כ אגה\"ק ס\"ה (קט, א)."],["34","34","ע\"ד מרז\"ל במאי זהיר טפי (שבת קיח, סע\"ב. וראה אגה\"ק סוס\"ז). 34*) ואולי יש לקשר זה עם מש\"כ בהקדמת התניא דנשמות ישראל נחלקות דרך כלל לשלשה קוין כו'."],["35","35","בנחלת אבות כאן (ועד\"ז בפרקי משה להר\"מ אלמושנינו): דמאותם השלשה עמודים שזכר שמעון הצדיק עשה הלל עיקר מהתורה כו' ושמאי עשה עיקר מהמעשה שחשבו שהתלמוד הוא בעבור המעשה כו' (ולזה עצמו אמר עשה תורתך קבע כו', להעיר שיהי' העיקר במעשה ולא בלימוד כו'). אבל לכאורה דוחק לפרש שב„עשה תורתך קבע“ כוונת שמאי שהעיקר (קבע) הוא המעשה. ולהעיר שע\"פ הפי' שבפנים (דוקא) מתאים זה עם מה שנתבאר בכ\"מ (אוה\"ת ואתחנן ע' רמא ואילך. ועוד) דהפלוגתא אם תלמוד גדול או מעשה גדול (קדושין מ, ב. וש\"נ) הוא כעין הפלוגתא דב\"ש וב\"ה (חגיגה יב, א), דב\"ש אומרים שמים קדמו לארץ (וב\"ה אומרים ארץ קדמה)."],["36","36","ראה בארוכה הלכות ת\"ת שם פ\"ג ס\"א־ד."],["37","37","פרש\"י ויחי מט, יג. ברכה לג, יח."],["38","38","וראה אגה\"ק סוס\"ט."],["39","39","ולהעיר מהלכות ת\"ת לאדה\"ז שם רס\"ג (מרמב\"ם שם ה\"ז): ולכן מי שנשאו לבו לקיים מצוה זו כראוי כו'. וראה גם קו\"א שם (ובשו\"ע או\"ח ר\"ס קנו). אלא דשם „כמו שאמרו חכמים (לקמן פ\"ו מ\"ד) כך היא דרכה של תורה כו'“, היינו ההדגשה דחיי צער תחי' כו', העדר המלאכה והעסק, משא\"כ הוראת „עשה תורתך קבע“ — ההדגשה על החיוב. ראה לעיל הערה 12."]]],[1300171362,"דערמיט איז מובן, פאַרוואָס ער פירט אויך ניט אויס (נאָכדעם ווי ער זאָגט „תורתך קבע“), אַז „עבודה“ און „גמ\"ח“ זאָלן זיין באופן „עראי“, וואָרום — די הוראה „עשה תורתך קבע“ איז געזאָגט געוואָרן אויך צו מארי עובדין טבין, וואָס זייער רוב התעסקות איז (ניט אין תורה, זיי זיינען יוצא אפילו מיט „פרק אחד שחרית ופרק אחד ערבית“40, נאָר) אין קו פון גמילות חסדים, פונדעסט־וועגן פאָדערט זיך אויך ביי זיי דער ענין פון „תורתך קבע“: דער לימוד התורה אין דעם זמן מועט (בכמות) זאָל זיין קבוע (באיכות), איינגעקאַרבט אין נפש, ביז אַז דאָס זאָל פועל זיין אויפן גאַנצן טאָג41.\nועוד — דער לשון „עראי“ איז ניט מתאים לגבי „עבודה“ און „גמילות חסדים“, ווייל זיי זיינען ענינים עקרים ויסודיים אין עבודת הוי' און זיי מוזן זיין אין אַן אופן פון „קבע“; נאָר צווישן די ג' דברים עצמם דאַרף דער עיקר ה„קבע“ זיין אין קו התורה דוקא.\nה. נאָך דער הוראה, אַז צווישן די דריי קוין איז דער קו התורה דער עיקר — „תורתך קבע“, איז שמאי ממשיך צו מבאר זיין, אין וואָס פאַר אַ אופן ס'דאַרף זיין דער עיקר לימוד בתורה: וויבאַלד רז\"ל42 זאָגן: „גדול תלמוד שהתלמוד מביא לידי מעשה“, וואָלט מען געקענט דערפון אַרויסדרינגען, אַז מ'דאַרף זיך אָפגעבן נאָר מיט לערנען אין אַן אופן פון „אסוקי שמעתא אליבא דהלכתא“42*, ד.ה. ענינים וואָס זיינען נוגע דווקא צו פסק'נען הלכה למעשה און ווערן דוקא אַ פוסק בישראל —\nדערפאַר באַוואָרנט ער באַלד און זאָגט „אמור מעט“: דער עסק התורה אין דעם סוג פון „אמור“43 — זאָגן די מסקנא לפסק הלכה — דאָס דאַרף זיין „מעט“44 דער עיקר און רוב הלימוד דאַרף זיין לימוד התורה לשמה, ביז אפילו ע\"ד „דרוש וקבל שכר“45, „יגדיל תורה ויאדיר“46.\nוויבאַלד אַזוי קען זיך אימעצער טועה זיין, אין דעם צווייטען קצה און מיינען: היות אַז דער „קבע“ און הדגשה אין לימוד התורה דאַרף זיין ניט דוקא צו פסק'נען להלכה ולמעשה ובפועל ממש, איז אפשר דערפון משמע אַז קיום המצות בכלל (מעשה) איז אַ זאַך וואָס פאָדערט ניט (ח\"ו) קיין קביעות, צו מקיים זיין זיי מיט מסירה ונתינה —\nאיז ער דעריבער מוסיף און זאָגט אָן „ועשה הרבה“: אמת טאַקע, אַז אין עסק התורה גופא דאַרף ניט זיין די הדגשה עיקרית אויף ווערן אַ פוסק און פסק'נען דינים להלכה למעשה, אָבער עס מוז זיין די הנהגה פון „ועשה הרבה“, אַז די עשיית המצות זאָל זיין מיט אַ ריבוי גדול סיי אין כמות און סיי אין איכות —",[["40","40","מנחות צט, ב. רמ\"א יו\"ד רסרמ\"ו. הלכות ת\"ת לאדה\"ז שם ס\"ד."],["41","41","ראה אוה\"ת נ\"ך ע' לז. המשך תער\"ב פ\"ד (ע' ז). לקו\"ד ח\"א (ז, א)."],["42","42","קדושין מ, ב. וש\"נ. 42*) יומא כו, א."],["43","43","ע\"ד ל' מחז\"ל (שבת קיד, א. תענית י, ב) איזהו ת\"ח כו' זה ששואלין אותו דבר הלכה כו' ואומר. ולהעיר מנחלת אבות: כי אמור הוא לשון נופל על התלמוד כו'. אבל מזה שנקט הלשון אמור ולא למוד וכיו\"ב, מוכח שאין כוונתו לאפוקי עצם הלימוד אלא ענין אמור שבלימוד, היינו אמירה והוראה לזולת, ולהעיר ממרז\"ל (שבת קלח, ב) דבר ה' זו הלכה."],["44","44","יתירה מזה ארז\"ל (אבות פ\"ו מ\"ו) ואינו שמח בהוראה; ואדרבא צ\"ל ירא הוראה (טושו\"ע חו\"מ ס\"ח ס\"ג וש\"נ)."],["45","45","סוטה מד, א. וש\"נ."],["46","46","ישעי' מב, כא. חולין סו, ב."]]],[1300171363,"וואָס מער מצות און מיט וואָס מער חיות און התלהבות.\nו. וויבאַלד אַז לדעת שמאי דאַרף זיך אַ איד בעיקר אָפגעבן מיט לערנען תורה לשמה, אין אַן אופן פון „אמור מעט“ קען ביי איינעם זיך אָפלייגן — ובהקדם:\nס'איז ידוע47 דער אונטערשייד צווישן די תכונות פון מוחין (שכל) און מדות, אַז מוחין איז זייער ענין צוליב דעם אדם ווי ער איז פאַר זיך, און מדות זיינען צוליב דעם זולת. ד.ה. אַז די התעוררות און ווירקונג פון די מדות קען זיין נאָר בשייכות צו אַ צווייטן (צו וועמען מען האָט דעם רגש פון אהבה, אָדער פאַר־וועמען ער האָט מורא וכו'); ביי מוחין איז עס להיפך: ניט בלויז זיינען מוחין ניט „בשביל הזולת“, נאָר אדרבה, דער „זולת“ איז גאָר גורם בלבול המוחין. וכידוע אַז צוקומען צו השגת השכל כדבעי (ובפרט די השגה פון עצם השכל וואָס איז העכער פון מדות, העכער פון פסקי הלכה) קען דער אדם דוקא דורך התבוננות והעמקה, ווען ער איז בהתבו־דדות, אָפגעזונדערט פאַר זיך.\nקען מען קומען צו דער מסקנא, אַז דער אופן פון „תורתך קבע“ (בדרך „אמור מעט“), וואָס איז אַן אופן פון השגה והבנה, פאָדערט פון אים די הנהגה פון התבודדות דוקא, זיין אָפגע־זונדערט פון דעם „זולת“; און אויב יע צוזאַמען מיט אַנדערע — איז דאָס נאָר מיט אַזאַ חברותא, וואָס וועט אים בריינגען אַ יתרון און תועלת אין זיין לימוד התורה, ווי „דבוק חברים“, „פלפול התלמידים“ (פון די זאַכן וואָס „התורה נקנית“48 בהם) וכיו\"ב, ווי רז\"ל49 זאָגן: „הרבה למדתי מרבותי ומחברי וכו' ומתלמידי יותר מכולן“. אָבער די מענטשן, וואָס זיין התחברות מיט זיי וועט אים ניט צוגעבן אין „תורתך קבע“, דאַרף ער זיי אויסמיידן, מרחיק זיין זיי און ניט האָבן צו טאָן מיט זיי כלל50.\nאויף דעם קומט די באַוואָרעניש אין דריטן פאַל פון שמאיס מאמר: „והוי מקבל את כל האדם בסבר פנים יפות“ — הגם אַז זיין עיקר התעסקות איז אין לימוד התורה און אין אַן אופן פון „קבע“ און „אמור מעט“, דאַרף עס אים ניט אָפ־האַלטן פון אויפנעמען יעדן איינעם, אָן אויסנאַם, מיט אַ סבר פנים יפות. ד.ה. אויך אַזאַ אדם, וואָס זיין בעקענען זיך מיט אים, זיין התחברות מיט אים וועט ניט בריינגען קיין תועלת אין זיינע ענינים (ניט נאָר ניט אין קו פון לימוד התורה, נאָר אויך ניט אין קו פון גמ\"ח וכו'), פונדעסטוועגן דאַרף ער אים ניט סתם „מקבל“ זיין, נאָר „בסבר פנים יפות“ דוקא, אַז דער אדם זאָל זען און מרגיש זיין אַז ער נעמט אים אויף און פאַרנעמט זיך מיט אים מיט צופרידנ־קייט און איבערגעגעבנקייט.\nז. לאחרי כל הנ\"ל שטעלט זיך די שאלה: ווי אַזוי קען מען אויספירן די אַלע הוראות צוזאַמען, וויבאַלד זיי זיינען פאָרט בסתירה איינע צו די אַנדערע, כנ\"ל? (די הנהגה פון „עשה תורתך קבע“ דאַרף זיין עיקרה די השגה ולימוד בתורה אין אַן אופן פון „אמור מעט“ — און צוזאַמען דערמיט זאָל זיין",[["47","47","ראה המשך תרס\"ו ע' קיא ואילך. ד\"ה וישא אהרן תרצ\"ד (סה\"מ קונטרסים ח\"ב ע' 596 ואילך). ובכ\"מ."],["48","48","אבות פ\"ו מ\"ו (כגירסת אדה\"ז בסידורו)."],["49","49","תענית ז, א. מכות י, א."],["50","50","להעיר ממד\"ש כאן ד\"ה והוי מקבל את כל האדם בשמחה."]]],[1300171364,"„ועשה הרבה“: מרבה זיין אין קיום המצות און נאָך מיט אַ ריבוי חיות והתלהבות; און צו דעם אַלעם מאָנט מען דעם ענין פון „והוי מקבל את כל האדם בסבר פנים יפות“, וואָס איז נאָכ־מער בניגוד: בעת אַז דער עיקר הצלחה פון „תורתך קבע“ איז דוקא דורך התבודדות, דאַרף מען זיך אָבער אָפ־געבן ניט נאָר מיט מעשה המצות בריבוי, נאָר אויך מיט דעם זולת. ווי קען מען זיך מתגבר זיין אויף די אַלע סתירות?)51.\nאיז די משנה מקדים און איז מודיע, אַז דער בעל המאמר איז „שמאי“: דורך (דעם תוכן וואָס איז מרומז אין) „שמאי“ וועט ער קענען דורכפירן אַלע דריי הוראות.\nס'איז מבואר אין לקו\"ת52 וועגן (דעם נאָמען) „שמאי“, אַז „ע\"כ נק' שמאי כענין שארז\"ל53 ע\"פ54 ושם דרך כו' כל השם אורחותיו, דהיינו ששוקל דרכיו איך ומהו כו'“ — אַז דער נאָמען „שמאי“ (וואָס איז פון לשון „שם אורחותיו“ — שאַצן און וועגן זיינע דרכים) איז מרמז און לערנט, אַז אַ איד דאַרף אָפשאַצן און אָפוועגן זיינע דרכים, זיין זמן און זיינע כחות וואָס זיינען אים געגעבן געוואָרן.\nאון אַז ער וועט אָפשאַצן און אָפוועגן די כוחות וואָס מ'האָט אים געגעבן מלמעלה, וועט ער אויסגעפינען אַז ער האָט דעם כח און די מעגליכקייט אויסצופירן די עבודה אין אַלע דריי אופנים הנ\"ל (ובפרט אין דעם זמן וואָס איז באַשטימט פאַר דעם לימוד פון פרקי אבות, וואָס דעמאָלט ווערן געגעבן כחות מיוחדים צו מקיים זיין בהצלחה אַלע הוראות פון (מילי דחסידותא וואָס אין) פרקי אבות); און אַז ער וועט גוט אָפשאַצן און אָפמעסטן דעם זמן וואָס ער האָט, וועט ער זען אַז מ'קען די צייט צעטיילן אויף אַזאַ אופן אַז ס'זאָל מספיק זיין צו טאָן אין יעדערן פון די דריי הוראות הנ\"ל51.\nח. בעומק ובפנימיות יותר י\"ל די שייכות פון די דריי הוראות הנ\"ל צום בעל המאמר „שמאי“.\nובהקדים וואָס אין די דריי הוראות געפינט מען אַ צד השווה: אין ערשטן ענין, אַז דער עיקר „קבע“ דאַרף זיין אין תורה און באופן פון „אמור מעט“ — ד.ה. אַזאַ לימוד וואָס איז לשמה ניט צוליב פסק'נען הלכה (כנ\"ל) — דריקט זיך אין דעם אויס אַז זיין לימוד התורה איז ניט צוליב אַ צווייטן ענין, אפילו ניט צוליב קיום המצות, נאָר צוליב תורה55.\nאַזוי אויך די צווייטע הוראה „ועשה הרבה“, אַז אויך בשעת תורתו איז קבע און „אמור מעט“ דאַרף ער מרבה זיין בקיום המצות, וואָס דאָס מיינט אַז זיין קיום המצות איז ניט צוליב (הצלחה ב)לימוד התורה — (באַוואָרענען ווי די הוראה פון מרז\"ל56 „כל האומר אין לו אלא תורה אפילו תורה אין לו“), אַז אויך ביי אַ יושב אוהל דאַרף זיין די עבודה פון גמילות חסדים און כללות קיום המצות, וואָס זיין עשי' (פון מצות) איז דעמאָלט בבחי' „מעט“57 — צוליב",[["51","51","להעיר גם מלקו\"ש חי\"ד ע' 318 ואילך."],["52","52","שה\"ש מח, רע\"ג."],["53","53","מו\"ק ה, סע\"א."],["54","54","תהלים מזמור נ בסופו."],["55","55","ועוד להעיר דגם בההוראה „עשה תורתך קבע“ לגבי „עבודה וגמ\"ח“, מודגשת נקודה הנ\"ל שבפנים, שהרי עיקר הענין דמעשה המצות ובפרט גמ\"ח היא בשביל לברר נפה\"ב וחלקו בעולם, משא\"כ בעסק התורה שע\"י מתייחד עם קוב\"ה (ראה תניא פל\"ז. ועוד)."],["56","56","יבמות קט, ב. וראה לקו\"ת ויקרא ה, א."],["57","57","אגה\"ק ס\"ה."]]],[1300171365,"ההכרח — שהזמן גרמא: אכילת מצה בפסח וכו', אָדער כדי זיין תורה זאָל זיין כדבעי58.\nאון וויבאַלד אַז דאָ ווערט געזאָגט „ועשה הרבה“ איז פאַרשטאַנדיק, אַז זיין מעשה המצות איז נאָר מצד אשר קדשנו במצותיו וצוונו (אפילו ניט אַלס סגולה אַז תורתו (וואָס איז קבע) זאָל זיין „יש לו“ — האָבן אַ קיום).\nועד\"ז אין דער דריטער הוראה „הוי מקבל את כל האדם בסבר פנים יפות“, וואָס רעדט זיך, ווי גערעדט פריער, וועגן איינעם וואָס ער וועט פון אים ניט האָבן קיין תועלת, אפילו ניט אין קיום המצות פון גמ\"ח, ווייל דער אדם דאַרף פון אים ניט האָבן קיין שום טובה (ווי דער לשון „כל האדם“) —\n[וואָרום בשעת דער צווייטער דאַרף אָנקומען צו אַ טובה (אפילו די טובה — אויפהייבן אים (דורך מקבל זיין אים בסבר פנים יפות) פון זיין נמיכות הרוח וכיו\"ב), אפשר אַז ער טוט דאָס צוליב די תועלת וואָס ער האָט פון דעם, ער איז מקיים דורך אים אַ מצוה פון גמ\"ח וכו'],\nנאָר די הוראה איז אויפנעמען יעדן איד בסבר פנים יפות בלויז דערפאַר ווייל אַזוי איז מדת חסידות59.\nאון אין דער נקודה משותפת — אַז סיי לימוד התורה סיי קיום המצות און סיי זיין מקבל זיין יעדן אידן איז יעדער פון זיי אַ מטרה ותכלית פאַר זיך (און ניט צוליב'ן תכלית פון אַ צווייטער זאַך) — זאָגט זיך אַרויס אַז ישראל אורייתא וקוב\"ה כולא חד60, וואָס דעריבער, כשם ווי ס'איז ניט שייך צו זאָגן אַז דער אויבערשטער איז ח\"ו אַן „אמצעי“ צו עפעס אַנדערש, אַזוי איז ניט שייך צו זאָגן דאָס בנוגע תורתו ומצותיו און (בנוגע הנהגות בני) ישראל.\nט. אָט דער ענין — אַז תורה מצות און אידן זיינען כולא חד מיט קוב\"ה — וועט דערהערט ווערן בהתגלות לעתיד לבוא, ווען עס וועט זיין דער גילוי פון דעם אמת פון יעדער זאַך, בזמן הזה אָבער איז דאָס בהעלם אין דער עבודה פון כאו\"א, וואָס דערפאַר זיינען דאָ (און עס דאַרפן זיין) פאַרשידענע סוגים ביי אידן61: מארי תורה — וואָס זייער עסק אין גמ\"ח ומצות איז ב„מיעוט ימיהם“57, אָדער אַזוינע וואָס באַ זיי איז עס צוליב תורה, ווייל „כל האומר אין לו אלא תורה כו'“ כנ\"ל; אָדער מארי עובדין טבין, וואָס עיקר ענינם איז מאַכן פון וועלט אַ דירה לו ית' דורך קיום המצות און דער (חיוב פון) לימוד התורה איז ביי זיי מעט אָדער בכדי זייער קיום המצות זאָל זיין כדבעי (און עד\"ז איז דאָ אָט דער חילוק אין המשך הדורות<sup data-n=\"62\">62</sup>.",[["58","58","ראה לקו\"ת ראה כג, ג."],["59","59","ואף שאומר „כל האדם“ (בה\"א) שכולל גם אוה\"ע* (תוד\"ה ומין — יבמות סא, א) — יש לומר, שמעין זה שייך גם באוה\"ע, שיש לקבל פניו בסבר פנים יפות גם כשלא יגיע עי\"ז שום תועלת לישראל ולתורה, מצד זה שהוא מעשה ה„אומן שעשאו“ הקב\"ה (תענית כ, ב). ולהעיר מברכות יז, א: אמרו עליו על ריב\"ז שלא הקדימו אדם שלום מעולם ואפילו נכרי בשוק, שבפשטות הוא מצד הענין דכבוד הבריות — ראה לקו\"ש חט\"ז ע' 263-4 ובהערות שם. *) להעיר מהנהגת שמאי (שבת לא, א), וראה שושנים לדוד הובא ב„לקוטים“ למשניות כאן. אבל י\"ל דשאני התם שאם הי' מקבלו בספ\"י הי' אפשר להנכרי לפרש שיש מקום לדעתו."],["60","60","ראה זח\"ג עג, א."],["61","61","ראה בהנסמן לעיל הערה 33. ולהעיר מלקו\"ש ח\"ח ס\"ע 189 ואילך."],["62","62","אגה\"ק סוס\"ט."]]],[1300171366,"און דאָס איז די שייכות פון בעל המאמר „שמאי“ צו די דריי הוראות הנ\"ל: ס'איז ידוע וואָס דער אריז\"ל63 זאָגט, אַז לעתיד לבוא וועט זיין די הלכה ווי ב\"ש, ד.ה. די הוראה פון די ג' ענינים הנ\"ל זיינען פאַרבונדן בעיקר מיט דעם גילוי פון דעם אמת פון כל דבר לעת\"ל.\nאָבער וויבאַלד אַז אַלע גילויים דלעתיד זיינען תלוי במעשינו ועבודתנו כל זמן משך הגלות64, און אין זיי איז דאָ אַ מעין פון דעם גילוי דלעתיד, איז מובן אַז במעשה בפועל עכ\"פ דאַרף אויך בזמן הזה זיין דער קיום פון די אַלע דריי הוראות, און במילא וועט ביי אים זיין „שמאי“, ער וועט אָפשאַצן און אָפ־וועגן זיינע כחות, וויסענדיק אַז ער האָט אַ נתינת כח מיוחד אויף קענען זיי אַלע דורכפירן.\nו„במדה שאדם מודד בה מודדין לו“65, דורך דעם וואָס אַ איד איז מקיים דעם גאַנצן ציווי פון דער משנה ביז צום סיום — „והוי מקבל את כל האדם בסבר פנים יפות“ איז ער זוכה אַז מ'ווייזט אים מלמעלה אַ „סבר פנים יפות“66, און „באור פני מלך חיים“67, ביז צו די חיים נצחיים וואָס וועט זיין לעת\"ל בקרוב ממש, אין דעם זמן פון תחה\"מ, וואָס כל ישראל יש להם חלק לעולם הבא.\n(משיחת ש\"פ שמיני תשל\"ה)",[["63","63","מק\"מ לזח\"א יז, ב. לקו\"ת קרח נד, ג."],["64","64","תניא רפל\"ז."],["65","65","משנה סוטה (ח, ב)."],["66","66","ראה לקו\"ת ראה לב, ריש ע\"ב."],["67","67","משלי טז, טו."]]],[1300171367,"<h3>פרק שני</h3>\nא. „רבי¹ שמעון אומר, הוי זהיר בקריאת שמע ובתפלה², וכשאתה מתפלל אל תעש תפלתך קבע אלא רחמים ותחנונים לפני המקום .. ואל תהי רשע בפני עצמך״.\nדארף מען פארשטיין:\nא) דארף מען דען אנקומען צו א ציווי אין מס׳ אבות (מילתא דחסידותא³) אז מ׳מוז זיין זהיר⁴ אין א מצות עשה דאורייתא (אדער אפילו א מ״ע דרבנן⁵), און עכו״כ די צווי מצוות, ק״ש און תפלה, וואס זיינען מצוות עיקריות און כלליות⁶ אין עבודת ה׳ ?\nב) עד״ז אין דער צווייטער בבא — „וכשאתה מתפלל אל תעש תפלתך קבע אלא רחמים ותחנונים לפני המקום״: וואס איז אין דעם דער אויפטו אויף דער משנה מפורשת אין מס׳ ברכות⁷: „העושה תפלתו קבע אין תפלתו תחנונים״ ?\nג) וואס איז די שייכות פון דער דריטער הוראה „ואל תהי רשע בפני עצמך״ (אז מ׳זאל זיך ניט האלטן פאר א רשע⁸, ווייל דאס ברענגט מ׳זאל זיך מתייאש זיין פון תשובה און ניט אפ־האלטן זיך פון צו טאן (נאך) אן עבירה) — צו די צוויי פריערדיקע הוראות וועגן דער זהירות אין ק״ש און תפלה⁹ ?\nב. די נקודת הביאור אין דער משנה:\nדי דריי הוראות אין דער משנה זיינען פארבונדן דערמיט וואס דער בעל המאמר — ר׳ שמעון בן נתנאל¹⁰ — איז ביי אים געווען „תורתו אומנתו״¹¹,",[["1","1","משנה יג."],["2","2","ברש״י ומח״ו לא גרסי „ובתפלה״ (וראה רבינו יונה ותוריו״ט). אבל אדה״ז בסידורו נקט כהגירסא שבפנים. וראה לקמן הערה 15."],["3","3","ב״ק ל, א."],["4","4","ראה מפרשי המשנה."],["5","5","להדיעות דמצות תפלה היא דרבנן (רמב״ן בהשגותיו לסהמ״צ מ״ע ה׳. וכן דעת רוב הפוסקים — מג״א או״ח סי׳ קו סק״ב. וראה לקו״ת בלק ע, סע״ג ואילך). אבל ראה תניא פנ״ג, מכתב אדה״ז להרר״א משקלאוו (נדפס בבית רבי ח״א כ, א (ס׳ אגרות קודש אדה״ז (קה״ת, תש״מ) ע׳ לב ואילך)). ועוד. ואכ״מ."],["6","6","דק״ש ענינה קבלת עול מלכות שמים (ברכות פ״ב מ״ב. שם כ, ריש ע״ב. ובכ״מ). ותפלה היא עבודה שבלב (תענית בתחלתה), ו„רחמי נינהו״ (ברכות שם), ועוד. וראה מפרשי המשנה."],["7","7","פ״ד מ״ד. וראה שו״ע אדה״ז אוי״ח סצ״ח ס״ג ובמ״מ שם."],["8","8","כפי׳ הרמב״ם, ועוד (ראה מדרש שמואל). וראה תניא רפ״א."],["9","9","ובאבות דר״נ ספי״ז לא הובאה בבא זו."],["10","10","מתלמידי ריב״ז שנמנו במשנה ח׳ (לגירסת אדה״ז — מ״ט). וכאמרו (משנה יו״ד) „הם (החמשה תלמידים) אמרו שלשה דברים״. וצע״ג בסה״ד ע׳ רשב״י (אות א׳) שציין למשנה זו (וראה שם אות ב׳ מס׳ היוחסין). וראה מדרש דוד לאבות (לר׳ דוד הנגיד — נכד הרמב״ם), שמפרש דר״ש כאן הוא רשב״י [ולהעיר, שרק במשנה „ר׳ יהושע אומר עין כו״ מפרט ומפרש, ר׳ יהושע ע״ה הי׳ מכלל חמשה התלמידים שנזכרו לעיל״]. וראה לקמן בפנים סעיף ד־ה."],["11","11","ראה בס׳ דרישת מרדכי (אמסטרדם, תקכ״ו) לאבות, דג׳ הוראות המשנה קאי במי שעוסק בתורה בקביעות, שאל תאמר שגם בזמן ק״ש ותפלה יהי׳ עוסק בתורה בשביל שתורתו אומנתו, ואל ימהר בתפלתך כדי ללמוד, ואל תאמר שאתה נעשה רשע שמבטל תורה — כי דוקא רשב״י וחביריו אין מפסיקין לק״ש ולתפלה, אבל אנו מבטלין. וראה גם בס׳ זרוע ימין לאבות (להחידא״א), דהוראות המשנה „הוי זהיר בק״ש ובתפלה״ — „כלפי מי שתורתו אומנתו מדבר״ [אלא ששם מפרש שגם תורתו אומנתו יש לו להפסיק לק״ש — לאפוקי מהירושלמי שהובא לקמן בפנים, וכן להיות זהיר בתפלה — כי גם הם מתפללים אם רוצים. ומציין לספרו ברכי יוסף אוי״ח סי׳ ע׳, עיי״ש]."]]],[1300171368,"בדוגמא ווי ר׳ שמעון בן יוחאי¹² (כדלקמן סעיף ח׳):\nאון דער וואס תורתו אומנתו איז ניט מפסיק אין לימוד התורה צו קריאת שמע — ווי רשב״י זאגט אין ירושלמי¹³: „כגון אנו שעוסקים בתלמוד תורה אפילו לקרית שמע אין אנו מפסיקין״, און עאכו״כ אז ער איז ניט מפסיק לתפלה, ווי דער פסק דין¹² אז תורתו אומנתו „אין מפסיקין לתפלה״:\nאון וויבאלד אז ער אליין האט ניט מפסיק געווען לק״ש ולתפלה, האט ער געדארפט באווארענען זיינע תלמי־דים¹⁴, אז זעענדיק זיין הנהגה זאל ביי זיי צוליב דעם ניט ווערן א חלישות אין די מצות ק״ש ותפלה.\nדערנאך זאגט ער א צווייטע הוראה פאר זיינע חברים¹⁵, וואס (אויך) ביי זיי איז געווען תורתם אומנתם [נאר ניט אין זיין דרגא, און דעריבער דארפן זיי יע מפסיק זיין לק״ש (בדוגמא צו חברי רשב״י, כדלקמן ס״ג)] — „כשאתה מתפלל אל תעש תפלתך קבע אלא רחמים ותחנונים וכו׳״: אמת טאקע אז „אין מפסיקין לתפלה״, אבער „כשאתה מתפלל״ — אין די צייטן ווען זיי זיינען יע מתפלל¹⁶, כידוע אז די וואס ביי זיי\nאיז תורתם אומנתם זיינען אויך מתפלל מזמן לזמן¹⁷ — זאל די תפלה ניט זיין אין אן אופן פון „קבע״ (אז בשעת מעשה טראכט ער „מתי אפרוק מעלי עול זה״¹⁸, און ער וועט זיך קענען אום־קערן צו זיין לימוד התורה¹⁹), נאר זי זאל זיין „רחמים ותחנונים״.\nועד״ז ביי דער דריטער הוראה „ואל תהי רשע בפני עצמך״ — אויך דאס איז פארבונדן מיט מעלת רשב״נ (וואס „תורתו אומנתו״), כדלקמן סעיף יו״ד.\nג. אופן ביאור הנ״ל אין „הוי זהיר בק״ש״ קען מען לכאורה פרעגן: די דיעה פון רשב״י אז „לק״ש אין אנו מפסיקין״ ברענגט מען נאר אין ירושלמי, אבער לדעת הבבלי¹² (און אזוי איז אויך די הלכה¹²) זיינען אויך די וואס „תורתם אומנתם״ — און אפילו „כגון רשב״י וחבריו״ — „מפסיקין לק״ש״ ?\nאיז די הסברה אין דעם: לויטן כלל²⁰ אז מען דארף משווה זיין בבלי וירושלמי כל מה דאפשר (אפילו דורך זאגן א פירוש וואס איז „דחוק²¹ קצת״) איז",[["12","12","שבת יא, א. טושו״ע (ואדה״ז) אוי״ח סו״ס קו. הל׳ ת״ת לאדה״ז פ״ד ס״ד־ה."],["13","13","ברכות פ״א סה״ב. שבת פ״א סה״ב."],["14","14","שאינם באותו הגדר דתורתם אומנתם. וראה שבת (וירושלמי) שם: א״ר יוחנן כגון אנו מפסיקין לק״ש ולתפלה. ולהעיר מרמ״א אוי״ח ס״צ סי״ח, ואדה״ז שם סי״ז."],["15","15","ולהגורסים (ראה לעיל הערה 2) „הוי זהיר בק״ש״ (ולא — „ובתפלה״) — יש לומר, שב׳ בבות הראשונות הן הוראות לחביריו: הא׳ — שיהיו זהירים בק״ש (אף שהוא עצמו אינו מפסיק לק״ש), והב׳ — „וכשאתה מתפלל כו׳״, כבפנים."],["16","16","ראה פי׳ עד״ז במדרש שמואל, ד״כשאתה מתפלל״ קאי על תפלת נדבה."],["17","17","ראה ר״ה בסופה. וברבינו יונה לריא״ף ברכות (ח, א) דרשב״י הי׳ מתפלל משנה לשנה*. וראה ניצוצי אורות (להחיד״א) לזח״ב קפח, א. ועוד."],["18","18","רש״י, רע״ב ועוד כאן. ע״פ ברכות כט, ב."],["19","19","ראה גם דרישת מרדכי — נעתק לעיל הערה 11."],["20","20","יד מלאכי כללי שני התלמודים אות יו״ד. וש״נ."],["21","21","ביד מלאכי „רחוק״. אבל בכס״מ לפנינו (הל׳ גירושין פ״ג הי״ח) הוא כבפנים. *) ראה גם שבת (לג, ב) „בעידן צלויי .. ומצלו״. ואף שבתוד״ה כגון רשב״י (שבת יא, א) מפרש ד„מצלי היינו ק״ש״ — כבר הקשו, שהרי דעת רשב״י היא שגם לק״ש אין מפסיקין (כנ״ל בפנים מהירושלמי). וראה יפה מראה לירושלמי ברכות שם, ברכ״י שם, יצחק ירנן (שאלוניקי, תקמ״ו) לרמב״ם הל׳ ק״ש פ״ב ה״ה — דיש לפרש „בעידן צלויי״ בזמן שרצו להתפלל כו׳, עיי״ש."]]],[1300171369,"מסתבר צו זאגן, אז אויך דא איז ניט קיין פלוגתא צווישן בבלי און ירושלמי, נאר עס איז א חילוק צווישן רשב״י אליין און „חבריו״²²:\nדער טעם פארוואס רשב״י האלט אז מ׳דארף ניט מפסיק זיין לק״ש איז ווייל „זה (ת״ת) שינון וזה (ק״ש) שינון ואין מבטל(ין) שינון מפני שינון״²³, און (ווי דער ירושלמי איז ממשיך לויט איין תירוץ) „רבי שמעון בן יוחי על ידי שהי׳ חדיד²⁴ בדברי תורה לפיכך אינה חביבה (עליו) (ק״ש) יותר מדברי תורה״.\nועפ״ז קען מען זאגן, אז דוקא רשב״י אליין²⁵ האט ניט מפסיק געווען לק״ש (וכדיוק הלשון — „רשב״י על ידי שהי׳ חדיד בד״ת .. אינה חביבה עליו כו׳״)²⁶, משא״כ חברייא דילי׳ האבן יע מפסיק געווען לק״ש.\nועד״ז ביי רשב״י גופא — י״ל, אז עס איז ביי אים געווען א חילוק איידער ער איז געווען אין מערה און דעם זמן נאך\nזיין ארויסגיין²⁷ — אז דאס וואס ער האט ניט מפסיק געווען לק״ש האט זיך אנגעהויבן ערשט נאכן ארויסגיין פון מערה²⁸, ווען עס האט זיך ביי אים אויפגעטאן דער אמת׳ער עילוי אין „שינון״ ו„חידוד״ אין לימוד התורה, ווי די גמרא דערציילט אין שבת²⁹.\nויש לומר, אז ר׳ שמעון בן נתנאל איז געווען בדוגמא צו רשב״י (ווי ער איז געווען לאחרי יציאתו מן המערה) כדלקמן, און דערפאר האט ער ניט מפסיק געווען לק״ש.\nד. אט דער ענין, אז ביי רשב״נ איז געווען „תורתו אומנתו״ ווי רשב״י — און דאס איז די נקודה התיכונה פון די דריי הוראות פון דער משנה — איז מרומז אין דעם, וואס דער מסדר המשנה דערמאנט דא ניט שם אביו פון בעל המאמר — ר׳ שמעון בן נתנאל מיט זיין פולן נאמען (כרגיל) — נאר בלויז ר׳ שמעון סתם, וואס סתם ר׳ שמעון איז גאר ר׳ שמעון בן יוחאי³⁰.\nאון אע״פ אז בפשטות דארף דאס די משנה דא ניט אויסטייטשן בפירוש, וארום די משנה קומט בהמשך צו די פריערדיקע משניות פון דעם פרק, וואו עס ווערן אויסגערעכנט³¹ די „חמשה תלמידים״ פון ר׳ יוחנן בן זכאי און צווישן זיי ר׳ שמעון בן נתנאל, און דער־נאך³² שטייט „הם אמרו שלשה דברים״",[["22","22","שלמטה מדרגתו. וראה ע״ד החסידות — מאמרי אדה״ז אתהלך־לאזניא ע׳ ריא. אוה״ת ויקרא ע׳ רנז. סה״מ תרכ״ז ע׳ עדר."],["23","23","ירושלמי ברכות ושבת שם. הובא בבעל המאור שבת שם. תוד״ה כאן — מו״ק ט, ריש ע״ב (וע״פ המבואר בפנים; דמ״ש בירושלמי הוא רק בנוגע לרשב״י עצמו — מתורצת קושיית הגליון הש״ס שבת ומו״ק שם)."],["24","24","כ״ה בירושלמי שבת שם. ועד״ז בבעל המאור שם. ובירושלמי ברכות: תדיר. וראה שירי קרבן לירושלמי שבת שם, דהגירסא חדוד נר׳ עיקר [ובא בהמשך לתי׳ הירושלמי „זה שינון וזה שינון״, שהוא לשון חידוד, וכמ״ש בקה״ע שם]."],["25","25","ראה גם המשך תער״ב (ע׳ איסו), שמקשר דעת רשב״י דאין מפסיקין לק״ש עם דרגת תורתו אומנתו שלו ש„הי׳ במעלה ומדרי׳ עליונה״. וראה גם אוה״ת ואתחנן ע׳ עס־פ."],["26","26","וגם לתי׳ הב׳ בירושלמי „רשב״י כדעתי׳ כו״ — יש לומר, שהוא רק בתורתו אומנתו בדרגת רשב״י."],["27","27","ועפ״ז יש לפרש לשון הבבלי „כגון רשב״י וחביריו — עד שיצא מן המערה."],["28","28","ראה עד״ז בס׳ יד דוד לתוס׳ מו״ק שם (ושם, שלכן הפסיק לק״ש בהיותו במערה, כמ״ש בתוס׳ (הובא לעיל שוה״ג להערה 17))."],["29","29","שם בסוף העמוד."],["30","30","רש״י שבועות ב, ב ד״ה משמו. רמב״ם בהקדמתו לפיה״מ ד״ה הפרק הששי. ועוד."],["31","31","משנה ח (ולגירסת אדה״ז — מ״ט)."],["32","32","משנה יו״ד."]]],[1300171370,"(אז יעדער פון זיי האט געזאגט דריי זאכן), איז דאך מאליו מובן אז מיט „ר׳ שמעון אומר״ ווערט דא געמיינט ר׳ שמעון בן נתנאל³³ —\nוויבאלד אבער אז יעדער ענין אין תורה איז מדוייק בתכלית [ובפרט אז די הוראות פון ר׳ שמעון בן נתנאל זיינען אין א באזונדער משנה (כמה משניות ווייטער פונעם ארט וואו ס׳איז מפורש שמו ושם אביו), ובמילא גיט עס א מקום לטעות³⁴ פאר דעם וואס לערנט בלויז די משנה³⁵ אז דער בעל המאמר איז רשב״י], איז פארשטאנדיק, אז מצד דעם טעם פנימי אין די הוראות פון רשב״נ איז נוגע (ניט דאס וואס ער איז ר׳ שמעון בן נתנאל, נאר) דאס וואס ער איז ר׳ שמעון (סתם) — איין ענין מיט רשב״י.\nה. די הסברה בזה: דער טעם פנימי וואס סתם ר׳ שמעון איז רשב״י — ווייל דער נאמען „שמעון״ איז פון לשון שמיעה³⁶, וואס אמיתית התוכן פון שמיעה איז הבנה והשגה — און דער ענין פון תורתו אומנתו, וואס דער איד פאראייניציקט זיך מיט תורה ביז זי ווערט זיין גאנצע „אומנות״, קומט דוקא ווען ביי אים איז די השכלה (פאר־שטאנד) אין תורה בשלימותה, וואס דעמאלט ווערט ער פאראייניציקט מיט תורה (בלשון התניא³⁷) מיט א „יחוד נפלא שאין יחוד כמוהו .. להיות לאחדים ומיוחדים ממש מכל צד ופנה״.\nאון דערפון איז אויך פארשטאנדיק בנוגע אלע וואס האבן דעם זעלבן נאמען — וכידוע ³⁷*, אז די שמות פון א אידן, ובפרט פון די תנאים³⁸ כו׳, גיבן ארויס דעם תוכן ונקודה פון זייער עבודה — אז ביי זיי איז דא (בהעלם עכ״פ) א „מעין״ פון סתם³⁹ ר׳ שמעון — רשב״י (תורתו אומנתו).\nאון דערפאר איז די משנה מדייק צו זאגן דא ר׳ שמעון סתם, אז דאס וואס ר׳ שמעון בן נתנאל האט געזאגט די הוראות איז עס מצד דעם וואס ער האט אין זיך די מעלה פון ר׳ שמעון סתם — רשב״י — תורתו אומנתו.\nו. דער גדר פון „תורתו אומנתו״ אין פשטות איז — אז (א) דאס איז אן ענין אין זמן — ער לערנט תורה און אויפ־",[["37","37","פי״ה. ומבואר (המשך תער״ב פרק ערה. לקו״ש ח״ט ע׳ 82 ואילך, וש״נ) דעיקר ענין הפנימיות הוא בשמיעה. ואף שמבואר (אוה״ת ואתחנן ע׳ עד ואילך. ובקיצור בהמשך תער״ב שם), שהענין דתורתו אומנתו הוא בחי׳ ראי׳ שלמעלה משמיעה, „אעברה נא ואראה גו׳״ — אולי יש לומר: ה„שמיעה״ (השכלה) היא בתורה, וה„ראי׳״ — באלקות (שבההשכלה). ולהעיר מהענין ד„רואין את הקולות״. 37*) ראה אור״ת להה״מ ס״פ בראשית. לקו״ת בהר מא, ג. ועוד. לעיל ע׳ 349 הערה 27. וש״נ."],["38","38","ולהעיר משל״ה יג, א ואילך (בהגה״ה) ע״ד הזכרת שמות שית סדרי משנה, מדרשי רז״ל (אבל אינו מזכיר שמות התנאים כו׳ — כי מדבר ע״ד לימוד ספרים הנ״ל, עיי״ש)."],["39","39","ועד״ז מ״ש בתניא (פל״ז — מח, ב) ד„בכל תלמוד ירושלמי היא (מצות צדקה) נק׳ בשם מצוה סתם .. מפני שהיא עיקר המצות מעשיות .. שבכל המצות אין מתלבש בהן רק כח א׳ מנפש החיונית .. אבל בצדקה .. כל כח נפשו החיונית מלובש כו׳״."],["33","33","וכמו שלא העתיק שמות האבות דשאר תלמידי ריב״ז — ממשנה ט׳ (ולגירסת אדה״ז — מ״י) ואילך."],["34","34","ולהעיר מספר היוחסין (הובא בסה״ד ע׳ רשב״י אות ב׳) „אע״פ שר״ש סתם בפ״ב דאבות שאמר הוי זהיר בק״ש הוא ר״ש בן נתנאל דבר הלמד מענינו״. וראה הנסמן לעיל הערה 10."],["35","35","שהרי חלוקת המשניות .היא חלוקה ע״פ תורה (ונוגע לדינא — ראה לקו״ש ח״ד ע׳ 1175 בהערה. וש״נ) — ועכצ״ל שלימוד משנה זו כמו״ש בפ״ע הוא ענין בפ״ע."],["36","36","ויצא כט, לג. וראה לקוטי לוי״צ אגרות (ס״ע שלט) לגבי רשב״י."]]],[1300171371,"הער און איז ניט מפסיק צוליב קיין זאך⁴⁰; (ב) עס איז דא (אויך) בא לימוד נגלה דתורה⁴⁰*, און ווי מען געפינט ביי רשב״י גופא, אז אפילו אין מערה איז עיקר עסקו געווען אין „תורת המשניות״ (און ניט אין „ספר הזהר והתיקונים״)⁴¹.\nשטייט אבער אין זהר⁴², אז מיט „תורתם אומנתם״ מיינט מען די וואס „לא זזת שכינתא מנהון כל יומיהון״ און זיי זיינען „דירה לשכינתא״, וואס דער־פון איז פארשטאנדיק: (א) דער עילוי פון תורתו אומנתו באשטייט אין דער־איכות׳דיקער צוגעבונדנקייט⁴³ צו תו־רה, אז זיין גאנצע מציאות איז דורכגע־נומען מיט תורה, און כל ענינו איז נאר דאס וואס ער איז א „דירה לשכינתא״; (ב) אט די צוגעבונדנקייט איז ניט נאר צו חכמת התורה, נאר (בעיקר) צום נותן התורה — „שכינתא״, וואס אזא לימוד איז פארבונדן דוקא מיט פנימיות התורה, און ווי עס שטייט בפירוש אין תקוני זהר⁴⁴ אז (דוקא) „מארי קבלה .. עבדין לה (צו דער שכינה) דירה״.\nדאס איז אויך דער יסוד פון דעם\nוואס חסידות⁴⁵ איז מבאר דעם ענין פון תורתו אומנתו, אז דער לימוד התורה איז אין אן אופן פון „ואשים דברי בפיך״⁴⁶ — די דברי תורה וואס דער לומד זאגט ארויס פון זיין מויל זיינען זיך מתייחס צום אויבערשטן: ער זאגט־נאך די דברי תורה וואס דער אויבער־שטער כביכול זאגט. וואס אזא אופן הלימוד נעמט מצד דעם ביטול בתכלית צום נותן התורה, ביז אין אן אופן פון „דירה לשכינתא״.\nועפ״ז איז מובן, אז דאס וואס רשב״י איז געווען „תורתו אומנתו״, איז עס פארבונדן מיט דעם וואס ער איז גע־ווען פון די „מארי קבלה״ — ואדרבה: ער איז געווען דער וואס האט משפיע געווען פנימיות התורה צו די אנדערע תנאים⁴⁷ (וואס דערפאר איז ער געווען אין דער דרגא הכי נעלית אין „תורתו אומנתו״ גופא).\nז. דערמיט וועט מען אויך האבן א תוספת ביאור אין דעם וואס רשב״י דוקא האט ניט מפסיק געווען לק״ש:\nכדי אז דער לימוד התורה זאל זיין אין אן אופן פון „ואשים דברי בפיך״, כנ״ל, מוז מען פריער שטיין אין א ביטול בתכלית צו אלקות, און דאס ווערט",[["40","40","ראה מג״א אוי״ח סק״ד סק״ד. שו״ע אדה״ז שם ס״ד. שם ס״צ סי״ז. תניא ספכ״ג. ועוד. 40*) ראה שו״ע אוי״ח והל׳ ת״ת לאדה״ז שנסמנו לעיל הערה 12."],["41","41","אגה״ק סכ״ו (קמג, א). וראה לקו״ת אחרי כח, א: וכל עסק רשב״י הי׳ בנגלה כו׳."],["42","42","ח״ג רלח, ב — שעליהם דוקא נאמר (תצא כב, ו) „לא תקח האם על הבנים״."],["43","43","להעיר מענין המרכבה דהאבות, דלא רק שהיו מרכבה „כל ימיהם״ (תניא פכ״ג. רפל״ד. פל״ט), כ״א גם „שכל אבריהם כולם״ (שם פכ״ג), ו„הם וכל אשר להם״ (שם פל״ט) היו מרכבה."],["44","44","בהקדמה (א, ב) — ד„על מארי קבלה אתמר לא תקח האם על הבנים״. ומ״ש בזהר הנ״ל „אית מארי משנה״ — י״ל הכוונה לאלה שמחברים נסתר ונגלה (ראה לקמן הערה 47. כסא מלך לתקו״ז שם)."],["45","45","תו״א לח, ד. אוה״ת ויקרא ע׳ רנו. סה״מ תרכ״ז ע׳ רעא ואילך. ועוד."],["46","46","ישעי׳ נא, טז."],["47","47","ראה סידור דש, סע״ב. מאמר ל״ג בעומר ושלאחריו בהמשך והחרים תרל״א. וגם „תורתו של רשב״י בנגלה שהיתה תורתו אומנתו פי׳ כלי שלו שהי׳ יודע הפנימיות בכל פשוטי ההלכות ובשעה שהי׳ לומד הי׳ ממשיך עצמות אוא״ס .. ע״י פנימיות התורה״ (המשך תרס״ז ס״ע מה. ועוד), כידוע שרשב״י הי׳ מחבר סתים וגליא (נסמן לקמן הערה 49. ועוד. וראה בארוכה לקו״ש ח״א ע׳ 129 ואילך). וראה לקו״ת מטות פד, סע״ג. ועוד."]]],[1300171372,"אויפגעטאן דורך דער עבודה פון ק״ש, וואס ענינה איז מסירת נפש⁴⁸.\nרשב״י אבער — ובפרט נאכדעם ווי ער איז געווען אין מערה — איז שטענ־דיק געשטאנען בתכלית הביטול צו אלקות⁴⁹, ווי ער האט געזאגט⁵⁰ „אנא סימנא בעלמא״ — ער מצד עצמו איז גאר קיין מציאות ניט און זיין גאנצע מציאות איז נאר וואס ער איז א „סימן״ אויף ג־טלעכקייט; ער איז געווען א „דירה לשכינתא״ בתכלית, וואס דער־פאר שטייט⁵¹ אויף אים „מאן פני האדון הוי׳ דא רשב״י״:\nאון דערפאר האט ער ניט געדארפט האבן די הקדמה פון ק״ש אז זיין לימוד התורה זאל זיין אין אן אופן פון „תורתו אומנתו״⁵².\nח. עס ווערט דערציילט אין גמרא⁵³, אז ר׳ אלעזר בן ערך האט גע־בעטן רשות ביי ר׳ יוחנן בן זכאי איבערצוזאגן פאר אים „דבר אחד שלמדתני״ אין מעשה המרכבה, און נאכדעם ווי „פתח ר״א בן ערך .. ודרש״ איז „ירדה אש מן השמים וכו׳״; און די גמרא איז דארט ממשיך, אז ווען ר׳\nיוסי⁵⁴ הכהן און ר׳ שמעון בן נתנאל⁵⁵ האבן געהערט דעם וועגן — „אף⁵⁶ הם פתחו במעשה המרכבה, אמרו יום א׳ בתקופת תמוז הי׳ ורעשה הארץ ונראתה הקשת בענן ויצאה בת קול ואמרה וכו׳״.\nזעט מען פון דעם, אז ר׳ שמעון בן נתנאל איז געווען פון די „מארי קבלה״, און אין אן אופן אז זיין ריידן אין מעשה המרכבה האט אויפגעטאן אז „רעשה הארץ וכו׳ ויצאה בת קול ואמרה כו׳״ — עס האט ממשיך געווען⁵⁷ די שכינה למטה⁵⁸, און פון דעם איז פארשטאנ־דיק אז ער איז געווען „דירה לשכינתא״.\nצווישן די אויבנדערמאנטע תנאים גופא, איז דא אן עילוי אין רשב״נ (וואס דערפאר איז ער דוקא בדוגמא צו רשב״י, ווערט אנגערופן שמעון, כנ״ל סעיף ג׳):\nר׳ אלעזר בן ערך האט נאר איבער־געזאגט אן ענין וואס ריב״ז האט אים געלערנט („למדתני״⁵⁹) און ניט וואס ער האט מחדש געווען; צווישן ר׳ יוסי הכהן און רשב״נ — וואס זיי האבן דורש גע־ווען אין מעשה המרכבה אין אן אופן פון „פתחו״⁶⁰, בכח עצמם (ובפרט ע״ד",[["48","48","אוה״ת שם (בריש העמוד). סה״מ תרכ״ז שם."],["49","49","ראה אוה״ת (ע׳ רנז) וסה״מ תרכ״ז (ע׳ עדר) שם, דרשב״י „הי׳ תמיד בבחי׳ ביטול .. ואפי׳ (ש)דוקא רשב״י לפי שחיבר סתים וגליא״."],["50","50","זח״א רכה, א."],["51","51","זח״ב לח, א. וראה בהמצויין בניצוצי זהר (מרגליות) שם."],["52","52","ראה המשך תער״ב (שבהערה 25) דרשב״י ס״ל דאין מפסיקין לק״ש „לפי שתורתו אומנתו דרשב״י הי׳ במעלה ומדרי׳ עליונה שגם בהגלה הי׳ מאיר בו האלקות שבההלכה״ — והרי ענין זה הוא מצד עוצם הביטול דרשב״י, כמבואר בהמשך תרס״ז שם."],["53","53","חגיגה יד, ב. ירושלמי שם (פ״ב ה״א)."],["54","54","בירושלמי שם גריס „ר׳ יוסף הכהן״ — אבל בפשטות זהו ר׳ יוסי הכהן תלמיד ריב״ז (וראה ג״כ סה״ד ע׳ ר׳ יוסי הכהן). ואכ״מ."],["55","55","כ״ה בירושלמי שם. ובבבלי — ר׳ יהושע."],["56","56","לשון הירושלמי שם."],["57","57","ראה סידור (עה, ג. המשך תרס״ז שם) בפי׳ „תורתו אומנתו״ — „שע״י לימוד ההלכות הרי ממשיך מאור א״ס ..כמשל כלי האומנות כו׳״."],["58","58","ראה לקמן בפנים ס״ט ובהנסמן שם."],["59","59","בירושלמי ליתא תיבת „שלמדתני״. אבל דוחק לומר דפליגי במציאות. — בחדא״ג שם (בתי׳ הב׳) ש„מדרך ענוה אמר ... שלמדתני״. אבל לכאורה דוחק הוא. וראה עיון יעקב שם."],["60","60","אף שהלשון „פתח״ איתא גם על ר״א בן ערך — הרי מפורש שם „דבר אחד שלמדתני״ (כבפנים). וראה עיון יעקב הנ״ל."]]],[1300171373,"הידוע⁶¹ אין דעם פירוש פון „פתח ר׳ שמעון״ וכיו״ב, אז דאס מיינט, אז ער האט אויפגעעפנט א נייעם ענין וצינור כו׳) — איז דא אן עילוי אין רשב״נ אויף ר׳ יוסי הכהן⁶²:\nכהונה (די צוגעגרייטקייט⁶³ לעמוד לשרת לפני ה׳) — ר׳ יוסי הכהן — בא־קומט מען דאך בירושה — דעריבער איז אויך זיין⁶⁴ „פתח״ במעשה המרכבה ניט גאר אינגאנצן אן ענין פון „פתח״ — בכח עצמו:\nדער שלימות׳דיגער באווייז אז מען איז „דירה לשכינתא״ — אז די גאנצע מציאות פון מענטשן איז מיוחד מיט „שכינתא״ — איז ווען די פתיחה במעשה המרכבה, און אין אן אופן וואס פועלט „רעשה הארץ וכו׳״, קומט אינ־גאנצן פון זיין אייגענעם כח. און דאס געפינט מען דוקא ביי רשב״נ וואס ווערט ניט אנגערופן הכהן (ער איז ניט געווען א כהן⁶⁵), און פונדעסטוועגן האט ער „פותח״ געווען במעשה המרכבה באופן הנ״ל.\nט. דער עילוי פון ר׳ שמעון בן נתנאל׳ס דורש זיין במעשה מרכבה (אויף ר״א בן ערך) איז אויך מודגש אין דעם, וואס דוקא בשעת ער האט פותח געווען במעשה מרכבה — „רעשה הארץ ונראתה הקשת בענן״ (וואס דאס איז געווען א נס, וארום ס׳איז געווען תקופת תמוז, וואס עננים זיינען ניט קיין דבר הרגיל⁶⁶) — ולכאורה פאדערט זיך ביאור⁶⁷:\nדי גמרא⁶⁸ דערציילט אן עילוי אויף ר׳ יהושע בן לוי אז לא נראתה קשת בימיו (וארום דער קשת איז א פעולה און אן אות שלא יחרב העולם, „ואם יש צדיק גמור בדור אין צריך אות״⁶⁹) — היינט וואס איז דער עילוי אז דורך זיין דרש׳נען במעשה המרכבה איז „נראתה הקשת בענן״ ?\nאיז דער ביאור אין דעם:\nבנוגע צו „קשת״ געפינט מען צוויי ענינים: (א) דאס איז אן אות ברית ש„לא",[["61","61","סד״ה כי כאשר תרע״ח."],["62","62","ולהעיר, שבבבלי משמע שרק ר׳ יהושע דרש ולא ר׳ יוסי הכהן. אבל בירושלמי — „אף הם פתחו״."],["63","63","משא״כ בשאר השבטים צ״ל „נדבה רוחו אותו והבינו מדעו וכו׳״ (רמב״ם סוף הל׳ שמיטין ויובל)."],["64","64","ועד״ז דר׳ יהושע (לגירסת הבבלי) — שלוי הי׳ (ערכין יא, ב. ועוד)."],["65","65","בתוספתא ע״ז (פ״ג, ג): מעשה בר״ג הזקן שהשיא את בת בתו לשמעון בן נתנאל הכהן. ומדהביאו בסה״ד (מס׳ היוחסין) בע׳ רשב״נ מוכח שס״ל שזהו רשב״נ תלמיד ריב״ז. אבל בפשטות, שמעון בן נתנאל הכהן שבתוספתא שם הי׳ עם הארץ, שהרי סיפור הנ״ל בא בהמשך להדין ש„נותן לו (לע״ה) גדולה ופוסק עמו כו׳ [וראה חסדי דוד לתוספתא שם (ושם, „ושמא הוא שמעון בן נתנאל תלמידו של ריב״ז דדילמא כהן הוה״)]. וכן משמע קצת מזה שדוקא ר׳ יוסי נקרא „(ר׳ יוסי) הכהן״*, ולא רשב״נ."],["66","66","רש״י חגיגה שם. קה״ע לירושלמי שם."],["67","67","ראה גם חדא״ג חגיגה שם."],["68","68","כתובות עז, ב."],["69","69","רש״י כתובות שם. *) כי אין לומר שכן הי׳ נקרא בפי הבריות עד שזה נעשה שמו — שהרי במשנה יו״ד וי״ב איתא ר׳ יוסי סתם (בלי ההוספה „הכהן״). ומוכח מזה, שהתוספת זו היא כדי להודיע איזה ר׳ יוסי הוא, וא״כ מדוע הסימן דר׳ יוסי הוא הכהן, ושל ר״ש — (שם אביו) „בן נתנאל״? (ולפ״ז, גם ממשנה זו ראי׳ שר׳ אליעזר בן הורקנוס לא הי׳ כהן (ראה הרד״ל במבוא לפדר״א), שהרי גם כאן לא נאמר עליו „הכהן״). אבל אין זו ראי׳ מוכחת, כי י״ל שהי׳ באותו מעמד (אף שלא נכלל במנין התלמידים) עוד אחד ושמו שמעון והי׳ כהן ועוד אחד ששמו יהושע והי׳ לוי — ולכן לא נק׳ ר׳ יהושע כאן „הלוי״ (ראה הערה הקודמת))."]]],[1300171374,"יהי׳ עוד מבול״⁷⁰, (ב) אויף „קשת״ שטייט⁷¹ אז עס איז „דבר שהוא מוקש לי״ (עס איז צוגעגליכן געווארן צום אויבערשטן), און דערפאר איז דער דין⁷² אז איז אסור להסתכל בקשת (ווייל „לא חס על כבוד קונו״⁷³). ועוד ועיקר (ג) מפורש במעשה מרכבה⁷⁴ (דבי׳ עסקינן): כמראה הקשת אשר יהי׳ בענן גו׳ כן מראה גו׳ הוא מראה דמות כבוד ה׳. איז מובן אז,\nדאס איז א גילוי נעלה פון שכינה וואס ברענגט אז עס זאל זיין דער „קשת בענן״⁷⁵.\nדער ערשטער ענין פון „קשת״ איז נאר ווען עס קומט ביומא דעיבא (אין א פארוואלקענטער טאג), וואס די עננים ווייזן אז עס איז א טאג פון דינים קשים⁷⁶,\nאבער די עננים (און קשת) וואס קומען דורך דעם וואס מ׳דרש׳נט במעשה המרכבה — זיינען (ניט אן אות אויף שולל זיין „דינים״⁷⁷, נאר) בלויז א סימן אויף א גילוי נעלה פון שכינה,\nועפ״ז איז נאכמער פארשטאנדיק ווי רשב״נ איז געווען „תורתו אומנתו״ אין אן אופן וואס ער איז געווען „דירה לשכינתא״.\nי״ד. איינער פון די ענינים וואס זיינען מתאר דרגתו הנעלית פון רשב״י איז געווען דאס וואס ער האט גע־זאגט⁷⁸: „יכול אני לפטור את כל העולם כולו מן הדין״; און וויבאלד אז ענינו ומעלתו פון רשב״י האט זיך אויסגע־דריקט אין דעם וואס ביי אים איז גע־ווען תורתו אומנתו, איז פארשטאנדיק, אז דאס וואס ער האט געקענט פטר׳ן את כל העולם כולו מן הדין איז פאר־בונדן מיט דעם ענין פון תורתו אומנתו⁷⁹.",[["70","70","נח ט, ט ואילך."],["71","71","ב״ר פל״ה, ג."],["72","72","חגיגה טז, א. טושו״ע אוי״ח סי׳ רכט ס״א."],["73","73","חגיגה שם. וראה זח״א עא, ב. זח״ב סו, ב. זח״ג פד, סע״א. ועוד."],["74","74","יחזקאל א, כח (כמובא בחדא״ג שם)."],["75","75","ראה זח״א בהקדמה (א, ב) ובהנסמן בניצוצי זהר (שם) ושערי זהר (מרגליות) לחגיגה יד, ב."],["76","76","ראה ברכות לב, ב. ועוד."],["77","77","בקה״ע לירושלמי שם, דמה שנראתה הקשת בענן הוא „לומר שכדאי הן דברים אלו לרחם על הארץ ולכרות עליהם ברית כו׳״ — אבל לפענ״ד צ״ע: 1) איך יפרש הקשת שבמרכבה (ביחזקאל שם), 2) למה לדמותו לקשת דמבול ולא לקשת דמרכבה, דבזה עסקינן. ובכל אופן גם לפירושו יש לומר, ע״פ משנ״ת בלקו״ש ח״ד (ע׳ 1235 ואילך), דמה שלא נראה הקשת בימי ריב״ל הוא להיותו „צדיק גמור בדור״ (רש״י כתובות שם), שהוא מורבב בדור, מתקן מזכך ומטהר אנשי דורו; ועד״ז מה שרשב״י לא נראתה קשת בימיו (ירושלמי ברכות פ״ט ה״ב. ב״ר שם, ב. רש״י נח ט, יב. זח״ג טו, א. לו, א. ועוד) — י״ל שזהו מצד מעלתו שהי׳ בבחי׳ יסוד עולם (זח״א רנה, סע״א. ז״ח ר״פ וירא), שלמעלה אפילו מבחי׳ „בני עלי״ (סוכה מה, ב), ופעולתו ש„כל היכא דהוה מחי ר״א הוי מסי ר״ש״ ואמר „איכא מילתא דבעי לחקוני כו׳״ (שבת לג, סע״ב) [ולהעיר מנצוא לזח״א (רכה, א), דרק במחוז רשב״י לא נראה הקשת]; משא״כ מצד העילוי ד„תורתו אומנתו״ שענינו בפשטות — התעסקות בתורה ולא בהדורי׳, עם (העולם) שמסביבו (וראה סידור עה, ג־ד) — י״ל, שמצד עילוי זה נעשה רק „יכול אני לפטור את כל העולם כולו מן הדין״ (סוכה שם), כדלקמן בפנים סעיף יו״ד**."],["78","78","סוכה שם."],["79","79","ראה גם לקו״ת מטות פז, ד. *) ולהעיר שהוריד גשמים בדורו (זח״ג נט, ב) לא ע״י דיבור (ותפלה) בצרכי הדור, כ״א בתורה ובמילא ירדו גשמים. **) במקומות שנסמנו בהערה 49 איתא, דזה שלא נראתה הקשת בימיו הי׳ מצד העילוי דעסק התורה שלו. ואולי י״ל שזהו מצד מה שפעל ע״י זה על אנשי דורו (כדמשמע בסה״מ תרכ״ז שם — גבי חוקי׳), וראה לעיל ע׳ 309 בפי׳ „די לעולם אני ואתה״ (שבת שם)."]]],[1300171375,"מ׳האט שוין אמאל גערעדט בארו־כה⁸⁰ אין דעם מאמר פון רשב״י „יכול אני לפטור את כל העולם כולו מן הדין״, אז דאס איז ניט דורכדעם וואס ער האט געקענט באווירקן די אנשי דורו און פועל זיין זיי זאלן תשובה טאן⁸¹, נאר אז זיין זכות איז געווען אזוי גרויס, אז ניט קוקנדיק אויף די עוונות פון דעם דור, איז ער „סובל כל עוונותיהם ופוטרן מן הדין״⁸².\nוויבאלד אז ביי רשב״נ איז געווען דער עילוי פון תורתו אומנתו בדוגמא צו רשב״י כנ״ל, איז אויך זיין אויפטאן אין וועלט געווען ע״ד דעם ענין (וואס רשב״י האט געזאגט) „יכול אני לפטור את כל העולם כולו מן הדין״.\nע״פ זה וועט אויך ווערן פארשטאנ־דיק די שייכות פון דער דריטער הוראה אין דער משנה — „ואל תהי רשע בפני עצמך״ — צו די פריערדיקע צווי:\nדוקא מצד דעם וואס רשב״נ איז גע־ווען „תורתו אומנתו״ ווי רשב״י (ווי דאס ווערט אויסגעדריקט אין די ערשטע\nצוויי הוראות אין דער משנה), וואס מצד דעם איז ער מגין אויף זיין דור און איז „סובל כל עונותיהם״ — דארף מען האבן די באווארעניש פון „ואל תהי רשע בפני עצמך״:\nבכלל, איז אזא וואס האלט זיך ווי א רשע (ובמילא וועט ער מצד עצמו ניט זוכן תשובה טאן), איז די הנהגה פון „יאה עניותא ליהודאי״⁸³ — אז מ׳ברענגט אויפן מענטשן פורעניות ויסורים ר״ל וואס צעברעכן זיין מציאות און ברענגען אים צו תשובה:\nמשא״כ אין דורו פון רשב״נ וואס זיין זכות האט מגין געווען און פארהיט פון פורעניות,\nדערפאר האט מען געדארפט במיוחד באווארענען „ואל תהי רשע בפני עצמך״ — אז מ׳זאל וויסן זיין, אז יעדערער קען און דארף און (סו״ס בל ידח ממנו נידח און) ער וועט תשובה טאן: און נאכ־מער: ער דארף ניט אנקומען צו יסורים וכו׳, נאר ער קען תשובה טאן מתוך הרחבה וחיי מנוחה ושלוה.\n(משיחות ש״פ בהעלותך, שלח ובלק תשכ״ח)",[["80","80","לקו״ש ח״ד שם (ובהערה 40, 43). וראה גם לקו״ש ח״כ ע׳ 152."],["81","81","ואז התמי׳ גדולה שהו״ל לעשות כן בפועל, ולא רק „יכולני״."],["82","82","רש״י סוכה שם."],["83","83","חגיגה ט, ב. ובפי׳ הר״ח שם."]]],[1300171376,"<h3>פרק שלישי</h3>\nא. „רבי¹ חנינא² סגן הכהנים אומר הוי מתפלל בשלומה של מלכות שאלמלא מוראה³ איש את רעהו חיים בלעו”.\nדאַרף מען פאַרשטיין:\nא) רז״ל זאָגן⁴ „מאן דבעי למהוי חסידא לקיים כו׳ מילי דאבות”, וואָס דאָס מיינט, אַז די מסכתא אבות באַ־שטייט פון „מילי דחסידותא”, פון אַזעל־כע הנהגות וואָס מ׳איז אין זיי ניט מחוייב מצד הדין, נאָר מ׳דאַרף זיי טאָן מצד „חסידות” — לפנים משורת הדין,\n[על דרך ווי די הוראה אין דער ערשטער משנה פון דעם פרק: „הסתכל בג׳ דברים ואין אתה בא לידי עבירה” — שורת הדין איז מחייב נאָר אַז דער איד זאָל ניט טאָן די עבירה בפועל, און אויף דעם איז מוסיף די משנה אַ הנהגה חסידותית שטייען אין אַ מצב פון יראת החטא (און דאָס איז אויך אַן עצה און אנווייז אַז ער זאָל ניט צוקומען (אפילו נאָענט) דערצו — דורך אַריינטראַכטן זיך אין די דריי זאַכן איז „ואין אתה בא לידי עבירה”],\nאָבער די הוראה „הוי מתפלל בשלו־מה של מלכות” האָט לכאורה ניט קיין שייכות צו אַ הנהגה פון מידת חסידות, אָדער צו אַ זהירות לפנים משורת הדין\nאדרבא באַוואָרענען פון „חיים בלעו” — איז מוכרח ע״פ ציווים הכי חמורים בתורה⁴*.\nב) וואָס איז דער דיוק הלשון „איש את רעהו חיים בלעו”? דער לשון וואָס איז רגיל ופשוט אין אַזאַ פאַל איז „הריגה”, ווי דער לשון הכתוב⁵ „אין יראת אלקים וגו׳ והרגוני”, אָדער „גזילה” (אויב דאָ ווערט (אויך) גע־מיינט רויבעריי און געלט־שאָדן) וכיו״ב — פאַרוואָס ווערט דאָ גענוצט אַ חידוש לשון וענין „חיים בלעו”⁶?\nג) אַלע ענינים אין וועלט זיינען תלוי אין אידן⁷, ווי עס שטייט⁷* „את העולם נתן בלבם”. פון דעם איז פאַרשטאַנדיק, אַז דער ענין פון „אלמלא מוראה איש את רעהו חיים בלעו” איז דאָ אויך ח״ו באַ אידן⁸, ואדרבה — דורך דעם וואָס",[["1","1","משנה ב."],["2","2","כ״ה הגירסא בדפוסי משניות שלפנינו (ובע״ז ד, א). וכ״ה גירסת אדה״ז בסדורו. אבל בשינויי נוסחאות למשניות „חנני׳”. וכ״ה במס׳ ע״ז כת״י (נ.י. תשי״ז), ר״ח ע״ז שם. ובכ״מ. ולהעיר מר״ה יד, ב: א״ר חנינא ואיתימא ר׳ חנניא. ואכ״מ."],["3","3","בע״ז שם „שאלמלא מוראה של מלכות” (ועד״ז בטור חו״מ סי׳ א „מורא מלכות”). וליתא בע״י, כת״י הנ״ל ור״ח שם. ראה דק״ס שם. וראה נחלת אבות לאבות כאן."],["4","4","ב״ק ל, א. וראה לעיל ע׳ 347 הערה 7. 4*) שצריך לשמור לחייו וחיי רעך (שלא יבלעו חיים). וגם הפרט ד„הוי מתפלל כו׳”, הרי מ״ע על היחיד להתפלל על חייו (ראה רמב״ם הל׳ תפלה פ״א ה״ב. חינוך מצוה תלג. שרש מצות התפלה בתחלתה)."],["5","5","וירא כ, יא."],["6","6","בתו״ח לע״ז שם: לפי שהכתוב המשיל את בני האדם לדגי הים והדגים בולעין זה את זה חיים לכך נקט הכי. אבל במאמר ר׳ חנינא עצמו לא נזכר כלל הכתוב „ותעשה אדם כדגי הים” שבע״ז שם, ומובן שנקט הכי כי יש מצב ותוכן כזה גם בבני אדם. וראה מגן אבות (להרשב״ץ) — הובא במד״ש כאן: ולשון הכתוב הוא כו׳. ובמצו״ד לתהלים קכד, ג."],["7","7","כמוכרח ע״פ מרז״ל (רש״י ורמב״ן ר״פ בראשית. ועוד) בראשית — בשביל ישראל שנקראו ראשית. 7*) קהלת ג, יא. לקו״ת במדבר ה, ריש ע״ב."],["8","8","ראה פיה״מ להרמב״ם (תרגום קאפח): כלומר"]]],[1300171377,"אידן פירן אויס די הוראה, ווערט דער ענין אויך אויפגעטאָן אין וועלט (אַז עס זאָל ניט זיין „איש את רעהו חיים בלעו”).\nולכאורה איז תמוה: ווי איז שייך מ׳זאָל וועגן אידן זאָגן, אַז כאָטש ס׳זיינען פאַראַן כו״כ קלאָרע ציווי׳ ה׳ בזה, איז ווען ניט די מורא פון מלכות וואָלט אַ איד „איינגעשלונגען” (און ניט סתם אַ צווייטן, נאָר אפילו) „רעהו”⁹?!? און בפרט, כנ״ל, אַז דאָ רעדט זיך וועגן אַ אידן וואָס (לערנט אבות, וויל) „בעי למהוי חסידא” — דאַרף ער האָבן די באַוואָרעניש פון „הוי מתפלל בשלומה של מלכות” אַז ער זאָל ניט „בולע” זיין „רעהו”?\nב. נאָך דעם געבראַכטן מאמר שטייט אין דער משנה¹⁰: „רבי חנינא¹¹ בן תרדיון אומר שנים שיושבין ואין ביניהם דברי תורה הרי זה מושב לצים כו׳ אבל שנים שיושבין ויש ביניהם דברי תורה וכו׳”.\nשוין מערערע מאָל גערעדט¹², אַז דער פאַנאַנדערטייל פון די משניות איז בדיוק [און דאָס איז נוגע להלכה למעשה¹²*: ווען איינער איז מקדש את האשה „על מנת שאני יודע לשנות” (אַז די קידושין זיינען אויפן תנאי אַז ער קען משניות), דיש לומר אַז עס זיינען גענוג (און נויטיק) צו קענען דריי משניות¹³], וואָס י״א אַז (אויך) צוליב דעם האָט דער אַלטער רבי אַריינגעשטעלט די מסכתא אבות אין זיין סידור¹⁴ — צו וויסן דעם אופן פון חלוקת המשניות.\nאיז ניט מובן: וואָס איז דער המשך און שייכות פון מאמר „שנים שיושבין וכו׳” צום מאמר „הוי מתפלל בשלומה כו׳”, וואָס דערפאַר שטייען ביידע אין איין משנה? — לכאורה זעט זיך ניט קיין קישור צווישן זיי¹⁵.\n[ואדרבא, די סברא איז מחייב, אַז דער מאמר האָט אַ שייכות און דאַרף צו־געשטעלט ווערן צו דער ווייטערדיקער משנה „ר׳ שמעון אומר ג׳ שאכלו . . ולא אמרו עליו דברי תורה”, וואָס אויך דאָרט רעדט זיך וועגן דעם עילוי פון דברי תורה בחבורה (און דער חסרון פון אַ חבורה אָן דברי תורה)].\nג. דער ביאור אין דעם:\nוויבאַלד די מסכתא אבות אַנטהאַלט „מילי דחסידותא”, ווי דערמאָנט אויבן,",[["","","לולא יראת המלכות היינו בולעים זה את זה חיים. ועד״ז הוא במחז״ו: שאילולי לא היתה יראתה של מלכות עלינו כו׳ היינו בולעים אחד את חבירו כו׳. ולהעיר מהגירסא במחז״ו שם, בש״נ למשניות וכת״י ע״ז הנ״ל (הערה 2): „בלענו”."],["9","9","ראה מדרש שמואל בסוף הפיסקא ואפשר. ובפי׳ מר׳ משה אלשאקר."],["10","10","לגירסת אדה״ז בסדורו. וכ״ה במשניות דפוס ראשון (נפולי, רנב), כת״י פארמה (ג), כת״י תמני. וכ״ה בדפוסי משניות וש״ס שלפנינו. ובמשניות שעם פי׳ מדרש שמואל וכו׳ הוא משנה בפ״ע. וכ״ה בכת״י קופמאן, כת״י פארמה (א), כת״י פריז. וראה ספר יש סדר למשנה למשניות (מהר״י (פיק) ברלין) בתחלתו ד״ה אלה החוקים, ועוד."],["11","11","כ״ה בסידור אדה״ז. וגם כאן שינויים, וע״ד הנ״ל הערה 2. ובלחם נקודים (להיעב״ץ): חנני׳. כ״ה ברוב הספרים. ואכ״מ."],["12","12","ראה לקו״ש ח״ד ע׳ 1175. ועוד. 12*) ואולי י״ל שנפק״מ גם לענין „המהלך בדרך ושונה ומפסיק ממשנתו” (משנה ד׳ לקמן (לגי׳ אדה״ז). וראה מדרש שמואל שם מהרב ר׳ משה אלמשנינו)."],["13","13","חלקת מחוקק אה״ע סל״ח סק״מ (וראה ב״ש שם סקנ״א). ועד״ז להסברא שהביא שם ש„די במשנה אחת”."],["14","14","ראה שער הכולל פ״ל ס״ג."],["15","15","ויתירה מזו: בבא האי מדברת בענין שנוגע לכל העולם (ראה רש״י, מח״ז, מאירי, רבינו יונה, רע״ב ועוד), והכי מוכרח לישוב העולם „אלמלא מוראה איש את רעהו חיים בלעו”, ובבא הב׳ — בענין הנוגע רק לישראל (לימוד התורה), ובמדריגה הכי נעלית שבו — „שכינה שרוי׳”."]]],[1300171378,"דאָס הייסט אַז דאָס זיינען הוראות פאַר אַ אידן וואָס איז גאַנץ און אָפּגעהיט אין לימוד התורה און קיום המצוות און אים פעלט נאָר די הנהגה פון מידת חסידות —\nאיז במילא פשוט, אַז ס׳איז ניט דאָ קיין אָרט אים אָנצוזאָגן ער זאָל ניט באַ־גזל׳נען אַ צווייטן אידן, און אַוודאי ניט דער ציווי ער זאָל ניט אָנרירן דעם לעבן פון אַ אידן (איז במילא פשוט פאַרוואָס דאָ שטייט ניט אַ באַוואָרעניש פון „איש את רעהו הרגו” אָדער באַ׳גזל׳ט);\nדער דיוק איז דאָ דווקא „(.. איש את רעהו) חיים בלעו”: ער וויל ניט אָנרירן ח״ו דעם לעבן (און אייגנטום) פון צווייטן אידן, זיין רצון איז „נאָר” — „חיים בלעו”, אַז דער לעבן (די מציאות און די מעשים) פון צווייטן זאָלן זיין „איינגעשלונגען” אין זיין מציאות¹⁵*.\nולפעמים איז אדרבא — די מעלות וואָס ער האָט, אַז ער איז גאַנץ אין לימוד התורה און איז אָפּגעהיט אין מצוות, כנ״ל, און קעגן דעם זעט ער פיל חסרונות ביים צווייטן אידן, בפרט ווען יענער איז אַן איש פשוט אין ידיעת התורה און אַמאָל אויך מיט אַ העדר הזהירות אין קיום המצוות — בריינגען עם צו, און זיינען באַ עם מכריח¹⁶ די מסקנא, אַז יענער דאַרף זיין בטל צו אים. און נאָכמער — עס איז אַ זכות און אַן עילוי פאַר יענעם אַז ער וועט זיין „איינגעשלונגען” אין זיין מציאות.\nד. כדי צו שולל זיין אַזאַ הרגש און הנהגה איז ניט גענוג אַ שכל׳דיקע הסברה, וואָרום, אדרבה, מצד שכל אמתי — וואָרעם דאָ רעדט זיך ניט וועגן אַ שוטה רשע וגס הרוח, ח״ו — איז דאָ אַן אָרט פאַר אַזאַ טענה: סוף כל סוף איז ער דאָך אַ גדול אין תורה און אין קיום המצות וכו׳, אין דער צייט ווען „רעהו” איז גאָר ווייט פון דער מדריגה — און דער חשבון איז אמת און אויס־געהאַלטן לויטן דרך און מאָס פון תורה¹⁷, ובפרט אויב יענער דאַרף אָנ־קומען צו אים לימוד התורה און הוראות אין קיום המצות.\nאון דעריבער, אפילו נאָך דער גאַנ־צער (וויבאַלד נאָר שכל׳דיקער) הסברה און חשבון, אַז ער דאַרף זיך פירן אַנ־דערש, וועט ער נאָך אַלץ ניט קענען אָפּטרעטן פון זיין הנחה, אַז רעהו דאַרף זיין בטל און „בלוע” אין זיין מציאות.\nדי עצה צו פועל זיין ביי זיך שלילת הנ״ל כדבעי, איז צו מקיים זיין די הוראה פון דער משנה „הוי מתפלל בשלומה של מלכות”, וואָס דורך דעם¹⁸ וועט ביי אים דערוועקט ווערן די מורא פון מלך מלכי המלכים הקב״ה¹⁹ — און דער הרגש היראה האָט בכח צו פועל זיין ביי אים, אַז ער זאָל זיך ניט האַלטן גרויס לגבי אַ צווייטן אידן¹⁵*.\nדי הסברה אין דעם: רז״ל²⁰ זאָגן „מלכותא דארעא כעין מלכותא דרקי־עא”, די הסברה דערפון איז, כידוע²¹,",[["","","15*) להעיר מפי׳ המהר״ל (בספרו דרך חיים) כאן."],["16","16","ע״ד מרז״ל בהמונע תלמידו מלשמשו כו׳ (כתובות צז, א)."],["17","17","להעיר ממרז״ל (ספרי (ופרש״י) עקב יא, כב. וראה כתובות קיא, ב. ועוד): ולדבקה בו (ע״י) הדבק בחכמים ובתלמידים."],["18","18","ראה טושו״ע (ושו״ע אדה״ז) בתחלתו."],["19","19","להעיר מפי׳ הריטב״א הובא במדרש שמואל כאן בתחלתו. מדרש דוד (לר׳ דוד הנגיד — נכד הרמב״ם) „אבל תוכו של המאמר כו׳”. זרוע ימין להחיד״א. זרע יצחק למשניות. ועוד."],["20","20","ברכות נח, א. זח״א קצז, רע״א. ח״ג קעו, ב."],["21","21","ראה זח״א שם. ובכ״מ. ובארוכה (בהבא לקמן) ראה בד קודש."]]],[1300171379,"אַז „מלכותא דארעא” קומט אַראָפּ דורך השתלשלות פון „מלכותא דרקיע” — דער מלך דאָ למטה האָט זיין שורש אין זיין „שר” למעלה, און דער שורש פונעם „שר” איז אין אַ העכערער דרגא, און אַזוי העכער און העכער — „גבוה מעל גבוה שומר”²² — ביז צו מלכות פון „מלך מלכי המלכים הקב״ה”.\nדערפון איז פאַרשטאַנדיק, אַז בשעת עס איז דאָ „שלומה של מלכות” בפשטות, אַז „מלכותא דארעא” הערשט מיט אַ שלימות כו׳, איז דער אמת׳ער טעם וסיבה צו דעם, ווייל אין „מלכותא דארעא” זאָגט זיך אַרויס דער שורש, „מלכותא דרקיע” — מלכותו של הקב״ה — מיט אַ גרעסערן תוקף²³.\nאון דערפאַר, ווען אַ איד וואָס האַלט שוין ביי „מילי דחסידותא” (ובמילא זעט ער יעדער ענין ווי ער איז לאמיתתו) איז זיין תפלה אין דעם ענין פון „שלומה של מלכות”, פילט ער אין דעם (ביז — מיט אַ ראי׳ מוחשית²⁴) מלכותו²⁵ של הקב״ה²⁶; ובמילא ווערט ביי אים נתעורר דורך „מלכותא דארעא”, דער הרגש ה„מורא” פאַר מלך מלכי המלכים הקב״ה²⁷ — און די עצם יראה פאַר דעם אויבערשטן פועלט אַז ביי אים ווערט נכנע אויף די התנשאות, זיין גרויס האַלטן זיך לגבי אַ צווייטן אידן — ווייל מלכותו ית׳ איז דאָך „השוה²⁷* ומשוה קטן וגדול”, דער גדול שבגדולים איז לגמרי ניט תופס מקום פונקט ווי דער קטן שבקטנים.\nה. דער יצר הרע איז אָבער אַן „אומן”²⁸ אין זיין אַרבעט צו אַראָפּפירן דעם מענטשן פון דרך הישר — דערי־בער איז ניט גענוג דאָס וואָס ער אַליין, מיט זיינע אייגענע כוחות, וועט זיך מתבונן זיין אין ענין פון „שלומה של מלכות” (אַז „מלכותא דארעא” איז „כעין מלכותא דרקיע כו׳”, כנ״ל): וואָרום ס׳איז עלול אַז נאָך אַ געוויסן זמן זאָל די התבוננות אויפהערן צו ווירקן כדבעי, צוליב די תחבולות היצר, ביז די „מורא” וועט ווערן אָפּגעשוואַכט און — אינ־גאַנצן נתבטל ווערן.\nדערפאַר איז מודגש אין דער הוראה „הוי מתפלל בשלומה של מלכות”: ניט פאַרלאָזן זיך נאָר אויף דער התבוננות",[["22","22","קהלת ה, ז."],["23","23","להעיר מתורת שלום ע׳ 204."],["24","24","להעיר מסה״מ עת״ר ע׳ נא. סה״מ קונט׳ ח״א רכו, ב ואילך. ועוד."],["25","25","להעיר מפי׳ הבחיי (הובא בלקו״ת צו יב, סע״ב ואילך) במ״ש (משלי כד, כא) ירא את ה׳ בני ומלך. וראה פי׳ הצ״צ עה״פ (אוה״ת נ״ך ח״ב ע׳ א״כ), ובתורת שמואל סרי״ס תרכ״ח."],["26","26","ועפ״ז יש לבאר שדוקא ע״י קיום ההוראה „הוי מתפלל בשלומה של מלכות” דבנ״י עד באופן של מילי דחסידותא, מתקיימת המוראה של מלכות השוללת „איש את רעהו חיים בלעו” בהנהגת העולם (כנ״ל ס״א). אצל אוה״ע מצ״ע אין „מוראה של מלכות” כ״א רק היראה מהדין ומשפט והעונש בפועל. ויראה זו אין בכוחה למנוע שלא יהי׳ איש את רעהו חיים בלעו — שכל חייו ומציאותו של השני יהיו „בלועים” ומכוסים במציאותו הוא, באופן שלהשני לא יהי׳ שום ענינים משלו, כי יהי׳ זקוק ונצרך לפרנסתו וכיו״ב להגדול ממנו (שהרי בזה אין דין ומשפט עונש כיון שאינו גונב וגוזל מרעהו): אבל ע״י שאיש הישראלי מתפלל בשלומה של מלכות, שיורגש במלכותא דארעא מלכותא דרקיע, ה״ז פועל גם באוה״ע „מוראה של מלכות” השוללת „איש את רעהו חיים בלעו”."],["27","27","להעיר מהמסופר באדה״ז שכשהי׳ במאסר כשבקרו הקיסר (בבגדים אזרחים) חלק לו כבוד מלכות באמרו בודאי הנך קיסר כו׳ כי מלכותא דארעא כעין מלכותא דרקיע ובהכנסך לכאן הרגשתי בנפשי יראה ופחד כו׳ (בית רבי ח״א פט״ו. וראה בד קודש). 27*) פיוט „וכל מאמינים” (בתפלת ימים נוראים)."],["28","28","ראה שבת קה, ב: כך אומנתו כו׳."]]],[1300171380,"מיט אייגענע כוחות, נאָר ער מוז אָנ־קומען צו מתפלל זיין — צו תפילה טאָן און אויסבעטן אַז דער אויבערשטער זאָל אים העלפן בטובו ובחסדו חינם (וכמאמר רז״ל²⁹: „אלמלא הקב״ה עוזרו אין יכול לו”) בכהנ״ל — ביז אַז דורך דער „מלכותא דארעא” זאָל ער מכיר זיין און דערפילן דעם אויבערשטנ׳ס מלכות³⁰.\nו. דערמיט וועט זיין מובן דער ווייטערדיקער המשך פון דער משנה „שנים שיושבין ואין ביניהן דברי תורה כו׳”: דער ריכטיקער באַווייז אַז דער אדם (וואָס האַלט ביי מילי דחסידותא, נאָכדעם ווי ער האָט געלערנט תורה כדבעי און איז זהיר אין מצוות) האָט באמת מבטל געווען זיין געפיל פון התנשאות און גאוה לגבי דעם זולת — איז אין דעם וואָס אויך זיין לערנען תורה איז אין אַן אופן³¹ פון „שנים שיושבין כו׳”³².\nוהביאור: דער עיקר מציאות פון אַ לומד תורה (וואָס וועגן אים רעדט זיך אין פרקי אבות, כנ״ל) איז דאָס גופא — זיין עסק אין תורה, און אַלע זיינע אַנ־דערע ענינים זיינען ניט מער ווי טפל־דיקע זאַכן. ווי דער פסוק³³ זאָגט: „אל יתהלל חכם בחכמתו גו׳ הגבור בגבורתו גו׳ עשיר בעשרו (וואָס חכמה, גבורה און עשירות זיינען זאַכן וואָס ענדערן זיך אין גאַנג פון זמן) כי אם בזאת יתהלל גו׳ השכל וידוע אותי”, תורה איז אַ זאַך וואָס איז שטענדיג, נצחית — „כי הם חיינו ואורך ימינו”, וע״ד רז״ל³⁴ „מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה כו׳ בנערותו כו׳ בזקנותו כו׳”.\nאון וויבאַלד אַז תורה איז דער אמת׳ער מהות פון דעם עוסק בתורה, איז מובן, אַז דער ביטול פון זיין מהות ומציאות ווערט געמאָסטן לויטן הרגש הביטול וואָס ער האָט ביים לערנען תורה.\nאון דאָס איז דער דיוק „שנים שיושבין כו׳”: כל זמן אַז דער לומד איז (מרגיש אַז ער איז) איינער וואָס יושב ועוסק בתורה, ער איז דער חכם ועוסק ומחדש חידושים אין תורה, איז זיין לערנען ניט באופן פון „שנים שיושבין” — ניט ווי צוויי וואָס לערנען זיצנדיק באַגלייך, אין אַ גלייכער „ישיבה”: וויבאַלד ער האַלט זיך פאַר אַ „ראש ישיבה” און דעם",[["29","29","סוכה נב, ריש ע״ב. קדושין ל, ב."],["30","30","ע״פ הנ״ל תובן השייכות לבעל המאמר רבי חנינא סגן הכהנים שי״א * שהי׳ מעשרה הרוגי מלכות, שהמלכות הרג אותם בשליחותו של הקב״ה [וראה ב„מדרש אלה אוזכרה” וב„מעשה עשרה הרוגי מלכות” דברי ר״י בן בבא ועוד: אנו חייבים מיתה למלך גדול ונורא והוא מסר אותנו ביד מלך כו׳]."],["31","31","ומה שמתחיל „שנים שיושבין ואין ביניהם דברי תורה הרי זה מושב לצים”, כי זה בא בהמשך ישיר להשלילה „איש את רעהו חיים בלעו” — ראה מדרש שמואל בתחלתו (הובא בתויו״ט בקיצור) דפירושו „שאפילו עוסקים בתורה הם עוסקים כל אחד לבדו ואינם מתחברים ללמוד בחברה כו׳ וקראם לצים כו׳ כיון שבגאותו וגאונו מתלוצץ כ״א בקרבו מידיעת חבירו כו׳, ע״ש. וראה ד״ה החלצו תרנ״ט פ״י. *) סה״ד ג״א חתפ ד״ה ר״ע נהרג. וראה טושו״ע או״ח סתקפ״פ ס״ב (מבה״ג): בכ״ה בו (סיון) נהרג רשב״ג ורבי ישמעאל ור״ח סגן הכהנים. אבל בהמדרשים (איכ״ר ב, ד. מדרש תהלים ט, יג. ועוד. ובמדרשים שבפנים ההערה), וכן במחזור ליוהכ״פ פיוט „אלה אזכרה” ובקינות „ארזי הלבנון” לא נמנה בהעשרה."],["32","32","וזוהי השייכות לר״ח בן תרדיון שהי׳ מעשרה הרוגי מלכות (לכל הדיעות), והי׳ יושב ועוסק בתורה ומקהיל קהלות ברבים כו׳ ונשרף וספר תורה עמו (ע״ז יח, א. ובהמצויין לעיל הערה 30)."],["33","33","ירמי׳ ט, כב־כג."],["34","34","משנה ובריתא סוף קידושין."]]],[1300171381,"צווייטן — ווי איינער וואָס זיצט ווי אַ תלמיד (און ווער ווייס אין וועלכער שורה³⁵).\nדווקא ווען ער איז בטל מיט אַן אמת, דעמאָלט איז זיין לימוד מיטן רעהו וכו׳ אינעם אופן פון „שנים שיושבין” — כאחד, ניט פילנדיק די מעלה פון איין לומד לגבי דעם צווייטן³⁶;\nאון דעמאָלט ווערט „שכינה שרוי׳”, וואָס שכינה איז דער גילוי פון מלכותו של הקב״ה³⁷,\nוכידוע³⁸: בשעת אַ איד פועלט ביי זיך דעם ביטול (דורך „הוי מתפלל בשלומה של מלכות” כנ״ל) אַז ער איז בבחי׳ „שנים שיושבין”, דעמאָלט איז „שכינה שרוי׳” — עס ווערט נתגלה די בחי׳ פון מלכותו של הקב״ה (מלכותא דרקיע) ווי דאָס איז מצ״ע, ניט נאָר דורך התלבשות אין מלכותא דארעא, וואָס דורך דעם ווערט די שלימות היראה און ביטול צו אלקות ווי דאָס איז מצד הקב״ה³⁹.\nז. ע״פ כל הנ״ל וועט מען אויך פאַרשטיין דעם לשון און דעם סדר אין פסוק⁴⁰ וואָס ברענגט זיך אין דער משנה „אז נדברו יראי ה׳ איש אל רעהו\nויקשב ה׳ וישמע ויכתב ספר זכרון לפניו ליראי ה׳ ולחושבי שמו” —\nדלכאורה: וויבאַלד מען רעדט דאָ וועגן „שנים שיושבין ויש ביניהם דברי תורה”, פאַרוואָס רופט מען זיי אָן „יראי ה׳” (און וואָס איז דאָ נוגע זיי אָנצורופן מיט דעם תואר)? —\nדאָס וואָס „יש ביניהם דברי תורה” פועלט אַז „שכינה שרוי׳ ביניהם” איז דערפאַר ווייל דער „נדברו” איז אין אַן אופן פון „יראי ה׳”: ביי זיי איז (דורך דעם „מתפלל בשלומה של מלכות” וכיו״ב) די יראה פון מלך מלכי המלכים הקב״ה אין אַן אופן גלוי ניכר ונרגש, אַזוי אַז זייער „נדברו” אין תורה⁴¹ איז מצד דעם וואָס זיי זיינען אין דער דרגא פון „יראי ה׳ איש אל רעהו” (דער היפך פון „איש את רעהו חיים בלעו”), דער־פאַר קומען זיי צו זייער לימוד התורה צו דער מדרי׳ פון „חושבי שמו”, כולל אויך — אַז ביי זיי דערהערט זיך אַז „כל התורה” איז — „שמותיו של הקב״ה”⁴².\n(משיחת ש״פ שלח תשל״ה)",[["35","35","ראה ב״ק קיז, א."],["36","36","ראה מדרש שמואל הנ״ל הערה 31."],["37","37","ראה בהנסמן לעיל הערה 19. תניא פנ״ב. ובכ״מ."],["38","38","וראה תניא פ״ו."],["39","39","ראה סדור עם דא״ח הערה לתיקון חצות."],["40","40","מלאכי ג, טז."],["41","41","להעיר מהענין דהבאת שלום (תורה) בין אדם לחבירו (שנים שיושבין) ה״ז הקדמה ומביאה השלום בין איש (ת״ת, שלום) לאשתו (מלכות — ונעשה שלומה של מלכות) — לקו״ת אמור לח, ב. ועוד."],["42","42","רמב״ן בהקדמתו לפי׳ עה״ת, ע״פ זח״ב פז, א. לקו״ת ר״פ מצורע ובכ״מ."]]],[1300171382,"<h3>פרק רביעי</h3>\nא. „בן עזאי אומר הוי רץ למצוה קלה ובורח מן העבירה\" 1. מיט דער הוראה (צווישן די „מילי דחסידותא\" 2 אין מסכת אבות) איז בן עזאי ניט אויסן צו אָנזאָגן אַז מ'זאָל בכלל מקיים זיין (אפילו) אַ מצוה קלה, און זיך אויסהיטן פון עובר זיין אַן עבירה — דאָס איז דאָך אַ דבר הפשוט, אַז יעדער איד דאַרף מקיים זיין אַלע מצוות, אפילו אַ מצוה קלה, און ער טאָר ניט עובר זיין ח\"ו אַן עבירה (אפילו אַן עבירה קלה);\nנאָר די הוראה פון בן עזאי איז אין דעם אופן פון קיום המצוות — „הוי רץ למצוה קלה ובורח מן העבירה\": ניט נאָר זאָל מען די מצוה טאָן בפועל, נאָר מ'דאַרף לויפן מקיים זיין אפילו אַ מצוה קלה, און ניט נאָר אָפּהאַלטן זיך פון טאָן אַן עבירה בפועל, נאָר מ'דאַרף אָנט־לויפן פון איר.\nמען דאַרף אָבער פאַרשטיין: אויך דער ענין — אַז מען דאַרף לויפן טאָן אַ מצוה — איז (ניט נאָר אַ מידת חסידות, נאָר) אַ דין (מפורש אין שו\"ע<sup data-n=\"3\">3</sup>: „מצוה לרוץ (כשהולך) לבית הכנסת וכן לכל דבר מצוה\"; היינט וואָס איז דער אויפטו פון דעם מאמר „הוי רץ למצוה כו'\" אַלס מידת חסידות, בשעת עס איז אַ חיוב מן הדין („מצוה\") ?\nאויך דאַרף מען פאַרשטיין פאַרוואָס בן עזאי איז ניט מסיים „(הוי רץ למצוה קלה) כלחמורה\", ווי דאָס איז לכאורה מתאים מצד התוכן, און ווי מען געפינט אין אַ פריערדיקער משנה 4 לגבי זהירות אין מצות: „והוי זהיר במצוה קלה כבחמורה\" ?\n[אַנדערע זיינען טאַקע גורס (אויך) אין דער משנה דעם וואָרט „כבחמורה\" — אָבער דער אַלטער רבי (בסידורו) איז עס ניט גורס, און אויך רוב מפרשים נעמען ניט אָן די גירסא 5].\nמוז מען זאָגן, אַז אע\"פ אַז ביי זהירות אין מצוות, מוז עס זיין אין אַ מצוה קלה פּונקט ווי אין אַ מצוה חמורה 6, אָבער בנוגע ריצה למצוה, איז אַ מצוה קלה ניט גלייך צו אַ מצוה חמורה 7; און דער־פאַר זאָגט בן עזאי (נאָר) „הוי רץ למצוה קלה\", אַז מען דאַרף לויפן אפילו צו אַ מצוה קלה און פון דעם לערנט מען אַז מען דאַרף לויפן מיט נאָך אַ גרעסערער ריצה צו אַ מצוה חמורה.\nעס בלייבט אָבער ניט פאַרשטאַנדיק: פאַרוואָס דאַרף בן עזאי בכלל מוסיף זיין „(למצוה) קלה\" — לכאורה האָט ער גע־דאַרפט זאָגן „הוי רץ למצוה\" סתם, וואָס מיינט יעדע מצוה פון אַלע מצוות [און",[["1","1","משנה ב'."],["2","2","ראה ב\"ק ל, א."],["3","3","או\"ח ס\"צ סי\"ב, ואדה\"ז שם סי\"ג. ע\"פ ברכות ו, ב (וברי\"ף שם)."],["4","4","אבות פ\"ב מ\"א."],["5","5","ראה תוי\"ט ושינוי נוסחאות למשניות כאן."],["6","6","ראה בארוכה לקו\"ש ח\"ד ס\"ע 1191 ואילך."],["7","7","אבל להעיר ממדרש שמואל (פ\"ב שם) בשם הר\"א, מגן אבות (להרשב\"ץ) כאן ודרשות הר\"ן דרוש ו' בתחלתו — דמשמע, שמאמר בן עזאי הו\"ע אחד עם המאמר „הוי זהיר כו'\". ובספרי ראה (יב, כח. יג, א. שם, יט) שתהא מצוה קלה חביבה עליך כמצוה חמורה — ולכאורה ריצה מורה על חביבות כו' (וכדלקמן בפנים). וראה לקמן הערה 44."]]],[1300171383,"במילא וואָלט דאָס געמיינט אויך אַז די ריצה דאַרף זיין ביי יעדער מצוה לויט איר דרגת החומר, וויבאַלד אַז דאָ איז ניטאָ די הדגשה פון „קלה כלחמורה\"] ?\nב. דער טעם אויף דער הוראה „הוי רץ למצוה קלה ובורח מן העבירה\" — זאָגט בן עזאי אין דעם צוויי ענינים: (א) שמצוה גוררת מצוה ועבירה גוררת עבירה, (ב) ששכר מצוה מצוה ושכר עבירה עבירה.\nווי מען לערנט אין פשטות, איז דער חילוק צווישן די צוויי טעמים: דער ערשטער טעם איז מסביר פאַרוואָס אַ איד דאַרף לויפן טאָן אפילו אַ מצוה קלה, ווייל זי וועט ברענגען צו מקיים זיין נאָך (אַ סך) מצות 8; און דער צוויי־טער טעם טוט אויף, אַז די ריצה למצוה דאַרף אויך זיין מצד דער מצוה גופא, וואָרום „שכר מצוה מצוה\" [ווי דער רע\"ב טייטשט, אַז דער „שכר וההנאה\" וואָס דער מענטש האָט ביים טאָן אַ מצוה — וואָס דאָס דריקט זיך אויס אין זיין לויפן טאָן אַ מצוה — איז אויך אַ מצוה; אָדער ווי דער פירוש, אַז דער שכר פון אַ מצוה איז — „מצוה\" 9: די צוותא וחיבור 10 מיטן אויבערשטן וואָס ווערט דורך דער מצוה].\nעפ\"ז קומט אָבער אויס, אַז דער עיקר טעם איז „שכר מצוה מצוה\", וואָס גיט צו פאַרשטיין אַז די ריצה דאַרף זיין מצד דער מצוה גופא [ובפרט לויטן פירוש הרע\"ב, אַז „שכר מצוה מצוה\" מיינט (ניט דעם שכר פון דער מצוה צו וועל־כער ער איז „רץ\", נאָר) די ריצה גופא]; און דער טעם „שמצוה גוררת מצוה\" איז אַ טעם נוסף, אַז אין פאַל ווען די הסברה „ששכר מצוה מצוה\" וועט ניט פועל'ן אויפן מענטשן אַז ער זאָל זיין אַ רץ למצוה, זאָל ער דאָס טאָן צוליב דעם וואָס אין דעם קיום פון דער מצוה איז אָפּהענגיק דער קיום פון נאָך מצות [וואָס אין פאַרגלייך צום טעם פון „שכר מצוה מצוה\" איז דאָס אַן ענין פון „שלא לשמה\" (פון דער מצוה), בדקות עכ\"פ] —\nאון אויב אַזוי, פאַרוואָס איז ער מקדים דעם טעם פון „מצוה גוררת מצוה\" פאַר דעם טעם פון „שכר מצוה מצוה\" ?\nג. נאָך אַ הוראה געפינט מען — און אויך אין מס' אבות 11 — בנוגע דעם ענין פון „ריצה\" אין עבודת ה': „יהודה בן תימא אומר הוי . . ו(ר)ץ כצבי . . לעשות רצון אביך שבשמים\"; און די הוראה (פון מס' אבות) האָט דער טור, און אַזוי אויך דער אַלטער רבי בשולחנו (אין מהדורא תניינא), געשטעלט אַלס התחלה והוראה כללית ויסודית פון „אורח חיים\" (— פון גאַנץ שולחן ערוך).\nקומט אויס, אַז אין עבודת האדם לקונו זיינען דאָ דריי ענינים און אופנים פון „ריצה\":\n(א) די ריצה לדבר מצוה וואָס איז אַ חיוב — „מצוה\": און דער דין שטייט בעיקר בנוגע צו ריצה לבית הכנסת, נאָר דערנאָך איז מען מוסיף — „וכן לכל דבר מצוה\":\n(ב) די ריצה „לעשות רצון אביך שבשמים\" — וואָס דאָס איז ניט אַ דין 12,",[["8","8","ראה מפרשי המשנה. אדר\"נ פכ\"ה, ד. דב\"ר פ\"ו, ד. וראה במדב\"ר פ\"י, ח. ועוד."],["9","9","מובא במדרש שמואל. ועוד. וראה תניא רפל\"ז."],["10","10","לקו\"ת בחקותי מה, ג. מז, ב. וראה בארוכה לקו\"ש ח\"ז ע' 30 ואילך, וש\"נ."],["11","11","פ\"ה מ\"כ."],["12","12","להעיר מטור או\"ח סרמ\"ב. שו\"ע (ואדה\"ז) שם (ס\"ו)."]]],[1300171384,"נאָר אַ מידת חסידות — „הוי . . רץ\" (און דערפאַר שטייט עס אין מס' אבות); עס איז אָבער אַזאַ מידת חסידות וואָס איז נויטיק און שווה לכל נפש, און דער־פאַר איז עס אַריינגעשטעלט געוואָרן אין טור און שו\"ע (פון אַלטן רבי'ן);\n(ג) די הוראה פון בן עזאי „הוי רץ למצוה קלה\" — וואָס די הוראה איז אַ מידת חסידות וואָס איז ניט שווה לכל נפש, און דערפאַר שטייט עס (נאָר) אין אבות 13 — און דער חידוש פון דער „ריצה\" איז מודגש אין דעם וואָס ער איז מוסיף „הוי רץ למצוה קלה\".\nד. די כללות הזריזות פון אַ אידן ביים מקיים זיין דעם אויבערשטנ'ס רצון, ווייזט אויף זיין שמחה וחפץ „למלאות רצון קונו ולעשות נחת רוח ליוצרו\" 14; און זריזות אין אַן אופן פון „ריצה\" איז אַ באַווייז אַז די שמחה וחיות איז ביי אים למעלה פון זיין מדידה והגבלה 15, וואָס דערפאַר שטרענגט ער זיך אָן איבער זיין טבע און הילוך (כרגיל), צו טאָן די מצוה וואָס שנעלער.\nאָט די שמחה וחיות למעלה מהטבע והרגיל צו מקיים זיין דעם אויבערשטנ'ס רצון — וואָס דריקט זיך אויס אין „ריצה\" — איז שייך נאָר ביי דעם וואָס שטייט מיט אַ ביטול בלתי רגיל צום אויבערשטן:\nבשעת דער מענטש פילט זיך אַלס מציאות, ועאכו\"כ אויב ער איז „מגיס דעתו וחולק כבוד לעצמו ומתכבד בעיניו\" 16, קען ער טאַקע טאָן אַ מצוה מיט חיות און שמחה, אָבער די שמחה איז ע\"פ טעם ודעת ובמילא איז עס אַ שמחה מוגבלת — ער „לויפט\" ניט, ער גייט ניט „אַרויס פון די כלים\";\nבשעת אָבער דער מענטש שטייט אין אַ ביטול, קען זיך ביי אים דערוועקן אַ שמחה בלתי מוגבלת, וואָס דריקט זיך אויס אין לויפן (טאָן די מצוה), ביז אין אַן אופן פון „משפיל עצמו ומקל גופו\" 16 — על דרך ווי מ'געפינט ביי דוד המלך די הנהגה פון „מפזז 17 ומכרכר (בכל עוז<sup data-n=\"18\">18</sup> לפני ה'\", וואָס איז געקומען מצד דעם וואָס „ונקלותי עוד מזאת והייתי שפל בעיני\" 19.\nה. דערמיט קען מען מבאר זיין אַן ענין מוקשה אין אַלטן רבי'נס שו\"ע — וואָס ביי דעם דין 20 „מצוה לרוץ לבית הכנסת וכן לכל דבר מצוה\" ברענגט ער אַראָפּ דעם מקור פון וואַנען מ'לערנט אָפּ 21 דעם דין — „שנאמר 22 נרדפה 23 לדעת את ה' וגו'\" 24.\nדלכאורה: אע\"פ אַז ס'איז דער דרך פון אַלטן רבי'ן צו מפרש זיין די טעמי ההלכות 25, איז ער אָבער ניט (אומע־",[["13","13","בר\"מ אלשאקר (הובא במד\"ש פ\"ה שם) נעתק בדברי הטור „ורץ כצבי כנגד הרגלים שיהי' רץ למצוה קלה כבחמורה\" — אבל בטור לפנינו ליתא."],["14","14","אגה\"ק סי' כא."],["15","15","ראה ד\"ה משכני (הב') תש\"א פ\"א. ועוד. ולהעיר מלקו\"ת שה\"ש טו, סע\"ב ואילך."],["16","16","לשון הרמב\"ם סוף הל' לולב — לענין עבודת ה' בשמחה."],["17","17","ש\"ב ו, טז. הובא ברמב\"ם שם."],["18","18","שם, יד."],["19","19","שם, כב. הובא ברמב\"ם שם."],["20","20","נסמן לעיל הערה 3."],["21","21","ברכות שם."],["22","22","הושע ו, ג."],["23","23","בב\"ח ברכות שם גריס „ונדעה נרדפה\". ועד\"ז הוא בירושלמי ברכות פ\"ה ה\"א. רי\"ף, רא\"ש, ע\"י ודק\"ס (מכת\"י) ברכות שם. רמב\"ם הל' תפלה פ\"ח ה\"ב. סמ\"ג עשין יט. יל\"ש הושע שם. ועוד. וראה לקמן הערה 35."],["24","24","כ\"ה גירסת הרי\"ף שם. וראה יל\"ש שם. אבל בברכות שם (וכן בשאר מקומות שבהערה הקודמת) ליתא „וגו'\". ואכ\"מ."],["25","25","ראה הקדמת בני המחבר לשו\"ע אדה\"ז."]]],[1300171385,"טום) מעתיק דעם מקור פון יעדער הלכה; און ווי מ'געפינט ברוב ההלכות, אַז דער אַלטער רבי דערמאָנט ניט די פסוקים כו' פון וואַנען מ'לערנט זיי אָפּ (אפילו דאָרט וואו אין טור ווערט עס יע געבראַכט) — מיט וואָס איז אַנדערש דער דין פון „מצוה לרוץ כו'\", וואָס דאָ ברענגט ער דעם (מקור פון) פסוק ?\nנאָך מער תמי' איז, וואָס ביי דעם דין איז אפילו דער טור 26 ניט מעתיק דעם פסוק !\nאויך דאַרף מען פאַרשטיין: פון דעם לשון אין אַלטן רבי'נס שו\"ע 27 — „מצוה לרוץ לבהכ\"נ וכן לכל דבר מצוה שנאמר נרדפה לדעת את ה'\" — קומט אויס, אַז פון דעם פסוק לערנט מען אַרויס דעם דין פון „מצוה לרוץ\" סיי לבית הכנסת און סיי „לכל דבר מצוה\" — איז תמוה: אין גמרא 21 ברענגט זיך דער פסוק נאָר בנוגע צו ריצה לבית הכנסת, אָבער בנוגע צו ריצה לדבר מצוה (הלכה), ברענגט זיך אַן אַנדער פסוק 28 („אחרי ה' ילכו כארי' ישאג וגו'\") 29 ?\nו. איז דער ביאור אין דעם: מיטן ברענגען דעם פסוק „נרדפה לדעת את ה'\" איז דער אַלטער רבי ניט אויסן צו ברענגען דעם מקור הדין, נאָר טאַקע דעם טעם פון דער הלכה; און דער טעם אויף כללות ענין הריצה אין עבודת ה' 30 (סיי לבהכ\"נ און סיי לכל דבר מצוה) איז „נרדפה לדעת את ה'\" 31.\nוועט מען דאָס פאַרשטיין לויט דעם ביאור פון צ\"צ 32 אויפן פסוק הנ\"ל „ונדעה נרדפה לדעת את ה'\" — דלכ־אורה, פאַרוואָס חזר'ט איבער דער פסוק דעם ענין ה„דעת\" צוויי מאָל („ונדעה\" און „לדעת\") ?\nאיז דער צ\"צ מבאר, אַז די צוויי לשונות זיינען מרמז אויף די צוויי „דעות\" (ד„א־ל דעות ה'\"<sup data-n=\"33\">33</sup>, „דעת תחתון\" און „דעת עליון\" 34; און די עבודה אין אַן אופן פון „נרדפה\" וריצה נעמט זיך דוקא מצד „לדעת את ה'\", דעת עליון 35.",[["26","26","אף שהרמב\"ם (שם) הביאו."],["27","27","ועד\"ז בחרדים מ\"ע (ומל\"ת) מדברי קבלה ומד\"ס התלויים ברגלים. של\"ה עד, א."],["28","28","הושע יא, יו\"ד. — ובחרדים בתחלתו (הובא בשל\"ה רמ, א) ב„תנאי המצוות\" מביא הכתוב (תהלים קיט, לב) „דרך מצותיך ארוץ\" [ובמור וקציעה לטור ס\"צ — „דרך פקודך ארוץ\". ולכאורה צ\"ל „מצותיך\"]."],["29","29","אבל י\"ל עפמ\"ש במפרשים (יפה מראה לירוש' ברכות שם. צל\"ח ומפרשי הע\"י ברכות שם) שהלימוד מהכתוב „אחרי ה' ילכו גו'\" הוא (לא שמצוה לרוץ כו', כ\"א) רק להתיר ריצה אפילו בשבת."],["30","30","להעיר מזח\"ג קמח, רע\"א."],["31","31","ולא (רק) „כדי להראות שהיא חביבה עליו\" (לבוש או\"ח שם). ובזה יומתק מה שאדה\"ז לא הביא מ\"ש בספר היראה לר\"י (הובא בפרישה ואלי' רבה שם) שדוקא סמוך לבהכנ\"ס מצוה לרוץ (כי הטעם לדין זה הוא מפני „דקודם לכן אינו נראה שמתכוין לשם מצות ב\"ה\" (פרישה שם))."],["32","32","אוה\"ת נ\"ך עה\"פ (ע' תלז)."],["33","33","ש\"א ב, ג."],["34","34","ומתאים עם התרגום עה\"פ, ד„ונדעה\" תרגם „ונילף\" ו„לדעת\" — „למידע\", כי אמיתית תוכן הדעת הוא (לא רק ידיעה שכלית — „ונילף\" — כ\"א) „התקשרות והתחברות\" (תניא פ\"ג), ואמיתית ענין ההתקשרות כו' הוא בדעת עליון (ראה תו\"א ר\"פ משפטים. ועוד)."],["35","35","ע\"פ המבואר בפנים יומתק מה שאדה\"ז בשולחנו לא העתיק תיבת „ונדעה\" (אף שרוב המפרשים * גרסי כן בש\"ס, כנ\"ל הערה 23) — כי הטעם להדין ד„נרדפה\" הוא רק „לדעת את ה'\" (דעת עליון) [וגם בפשטות כן הוא, שעצם הטעם *) ולהעיר, שגם באוה\"ת — וכ\"ה בגוף כי\"ק — נ\"ך שם (ע' תלה) נעתק מגמ' עם תיבת „ונדעה\"."]]],[1300171386,"מצד דעת תחתון — די „דעה\" וואָס ווערט דערהערט אין „תחתון\" (וועלט), אַז וועלט איז אַ יש ומציאות וואָס דער „אין\" אלקי איז מהווה ומחי' — ווערט נאָר אויפגעטאָן די עבודה אין אַן אופן פון „הילוך\" וואָס איז מיט מדידה והגבלה „מדרגא לדרגא\"; מצד „דעת עליון\" ווערט דערהערט ווי די אמת'ע מציאות איז (למעלה), און וועלט (און אפילו דער „חיות של היש\") איז „אין וכלא חשיבי\". און דעריבער טוט עס אויף אין עבודה דעם ענין פון „נרדפה\" — פון „רצוא\", צו לויפן, אַרויסגיין פון די מדידות והגבלות פון דער אייגענער מציאות.\nז. אע\"פ אַז די עבודה בדרך „ריצה\" („נרדפה\") וואָס איז העכער פון מדידה והגבלה נעמט זיך דוקא מצד דעם ביטול פון מענטשן, ביז צום ביטול פון „דעת עליון\" („לדעת את ה'\") — זאָגט אָבער דער שולחן ערוך אַ פסק דין השווה לכל נפש, אַז „מצוה לרוץ לבית הכנסת וכן לכל דבר מצוה\".\nוואָרום אפילו דער וואָס האַלט ניט ביי „לדעת את ה'\" און זיין שמחה וחיות אין אַ מצוה איז מיט מדידה והגבלה, איז אָבער דאָ אויף אים אַ חיוב צו „לויפן\" ברגליו כפשוטו „לכל דבר מצוה\"; ווייל אין דעם „פועל ממש\" פון דער עבודה פון „ריצה\" איז יעדער איד מחוייב 35*, אפילו אַזאַ וואָס האַלט נאָך ניט אפילו ביי דעת תחתון.\nע\"ד ווי מען געפינט בכמה מצוות, אַז דער אופן קיום המצוה איז אויסגע־שטעלט בהתאם צו דעם תוכן פנימי פון דער מצוה, און יעדערער — אפילו דער וואָס האַלט נאָך ניט ביי דעם תוכן פנימי פון דער מצוה, און עס קען זיין אַז ער ווייס אפילו ניט פון דעם — דאַרף עס טאָן לויט דעם אופן דוקא.\n[ע\"ד ווי מ'געפינט ביי דער מצוה פון ק\"ש, אַז זי קומט נאָך פסוקי דזמרה און ברכות ק\"ש — וואָרום כדי צו צוקומען אין ק\"ש צום הרגש כדבעי פון „ה' אחד\" — דאמליכתי' בשבעה רקיעים ובארץ ובד' רוחות העולם 36 — און צו אהבת ה' „בכל לבבך ובכל נפשך ובכל מאדך\", דאַרף פריער זיין די התבוננות אין דעם תוכן פון פסוקי דזמרה און ברכות ק\"ש — אָבער פונדעסטוועגן איז דער סדר אָנגעזאָגט פאַר יעדערן, אפילו אויב ער האַלט נאָך ניט ביי דער מדריגה].\nח. דער טעם פאַרוואָס יעדער איד איז מחוייב אין דעם „פועל ממש\" פון „ריצה\" לכל דבר מצוה, אע\"פ אַז ער האַלט נאָך ניט ביי דעם תוכן פנימי פון דער מצוה, איז ווייל דורך דעם וואָס אַ איד איז זיך מרגיל צו לויפן „לכל דבר מצוה\" מיט אַ שמחה וחיות, ברענגט דאָס גופא דערצו, אַז ער זאָל שנעלער און לייכטער צוקומען צו דער דרגא פון „ריצה\" לאמיתתה — אַ שמחה וחיות בלתי מוגבלת אין עבודת ה' 37.\nוואָס דאָס איז אויך דער פירוש אין „נרדפה לדעת את ה'\", וואָס מיינט",[["","","ל„נרדפה\" הוא „לדעת את ה'\", ו„נדעה\" הוא רק הקדמה כו']. ומה שבגמרא (לרוב המפרשים) הובאה תיבה זו — כי בזה מרמז סדר העבודה איך להגיע ל„לדעת את ה'\" (המביאה ל„נרדפה\"), שהוא ע\"י הקדמת העבודה דדעת תחתון („נדעה\"). [ועד\"ז יש לתרץ השינוי בשל\"ה (שצויין לעיל הערה 27), ע\"ש]. 35*) להעיר מהמבואר (המשך תרס\"ו ע' רמב) דגם בנה\"ב שייך הביטול דיחו\"ע „במה ששייך לפועל בלבד\", עיי\"ש ביאור „העבודה בפועל דיחו\"ע\"."],["36","36","ברכות יג, ב ובפוסקים."],["37","37","ראה גם חינוך (מצוה טז) — בנוגע למעשה המצוות בכלל."]]],[1300171387,"בפשטות (ניט אַז דער „נרדפה\" איז אַ תוצאה ומסובב פון „לדעת את ה'\", נאָר פאַרקערט) אַז דער „נרדפה\" ברענגט צו „לדעת את ה'\" 38 — ווייל דורך ריצה בפועל („נרדפה\") קומט מען סו\"ס צום ביטול פון „דעת עליון\".\nדערמיט איז מובן פאַרוואָס דער חיוב (ריצה לדבר מצוה) שטייט בעיקר ביי בית הכנסת (כנ\"ל סעיף ג') — תפלה: תפלה איז „עבודה שבלב\" 39, וואָס ענינה איז אַז אַ איד איז זיך מתדבק צום אויבערשטן 40 אויף צוצוקומען צו העכערע דרגות אין עבודת ה'; און דערפאַר הויבט זיך אָן די עבודה פון „נרדפה (וואָס ברענגט) לדעת את ה'\" (דעת עליון) מיט דער ריצה לעבודת התפלה, ווייל זי איז די עבודה מיוחדת צו דערגרייכן די העכערע דרגא פון „דעת את ה'\" 41 [און פון (און דורך) עבודת התפלה ווערט אויפגעטאָן די עבודה פון „נרדפה\" וריצה ביי „כל דבר מצוה\" 42].\nט. און דאָס איז דער אויפטו פון די הוראות פון „הוי רץ כו'\" וואָס שטייען אין מס' אבות אויף דעם דין הנ\"ל שבשו\"ע: זיי ריידן וועגן דעם תוכן פנימי 43 פון ענין ה„ריצה\" — די זריזות, חיות ושמחה בלתי מוגבלת אין עבודת ה', וואָס איז אַן „עבודה גדולה\" 16 (מילתא דחסידותא).\nנאָר אין דעם גופא זיינען דאָ צוויי אופנים: (א) „הוי . . רץ . . לעשות רצון אביך שבשמים\" — וואָס די ריצה האָט אַ שייכות צו יעדערן (און דערפאַר ווערט עס געבראַכט אויך אין טור און אין אַלטן רבי'נס שו\"ע, כנ\"ל); (ב) די הוראה פון",[["38","38","ראה גם רבינו יונה לרי\"ף ברכות (ו, ב)."],["39","39","תענית בתחלתה. רמב\"ם ריש הל' תפלה. טור או\"ח סי' צח."],["40","40","ראה טושו\"ע (ואדה\"ז) או\"ח שם. הל' ת\"ת לאדה\"ז פ\"ד ס\"ה־ו."],["41","41","ובפרט ע\"פ המבואר בכ\"מ (תו\"א ביאור לד\"ה כי כאשר השמים. דרך חיים שער התפלה פל\"א ואילך. ועוד), דעיקר ענינה של תפלה הוא רצוא (ותומ\"צ — שוב)."],["42","42","ראה לקו\"ת בלק (ע, ד) דתפלה „היא עיקר המעמיד ומקיים את הרמ\"ח מ\"ע . . כמשל החוט השדרה שהוא המעמיד ומקיים את האברים\", ע\"ש."],["43","43","וכדמוכח עוד יותר במאמר בן עזאי, שמפורש בו „למצוה קלה\" — והרי הדוגמא למצוה קלה בדרז\"ל היא שילוח הקן * [משנה סוף חולין. תנחומא עקב ב. תצא ב. דב\"ר פ\"ו, ב. ובכ\"מ. ובדב\"ר (שם, ד) היא הדוגמא שמביא בן עזאי ל„מצוה גוררת מצוה\" — הטעם ל„הוי רץ כו'\"], שאין שייך בזה ריצה ברגלים כפשוטה, כי אין שייך מצוה לרדוף אחרי קן צפור, ואדרבה — „כי יקרא, במאורע לפניך\", שלא יחזור כו' כדי שימצא קן (חולין קלט, ב). להעיר אשר כהנ\"ל (שירוץ כו') אינו במצות דלא שייך בהם ריצה (כפשוטה, או גם כתוכנה) ומהם במצות הנקראות קלות: ציצית שנק' מצוה קלה (מנחות מד, רע\"א) — הרי אין ציצית מן המצות „שאדם חייב להשתדל ולרדוף ** עד שיעשה אותה\" (ל' הרמב\"ם הל' ברכות פי\"א ה\"ב), כי „אין אדם מחויב לקנות לו טלית ולהתעטף בה כדי שיעשה בה מצוה\" (רמב\"ם הל' ציצית פ\"ג הי\"א); סוכה — מצוה קלה (ע\"ז ג, א) שכשמקיימה כדבעי אין צורך לרוץ (ברגליו כפשוטו) להסוכה, שהרי — „כל שבעת הימים אדם עושה סוכתו קבע . . תשבו כעין תדורו\" (סוכה כח, ב). ועוד. *) וי\"ל שהיא „קלה\" עוד יותר מציצית וסוכה ולכן נק' (תנחומא עקב שם. דב\"ר שם. ועוד) „קלה שבקלות\", וראה תנחומא תצא שם: ואין לך מצוה קלה בכל המצות יותר משלוח הקן. **) ואולי י\"ל דבתור מילתא דחסידותא (ואולי עוד יותר) צריך לרוץ בזה וכבש\"ס שם (מא, א) שבעידן דריתחא מענישין ע\"ז. עיי\"ש. ואולי זהו המקור וזוהי כוונת הרמב\"ם הל' ציצית שם: אע\"פ שאין אדם מחוייב לקנות לו טלית . . אין ראוי לאדם חסיד שיפטור עצמו ממצוה זו אלא לעולם ישתדל להיות עטוף כו'. ובטור ושו\"ע אדה\"ז או\"ח רסכ\"ד: טוב ונכון להיות כל אדם זהיר וזריז במצות ציצית כו' (ובשו\"ע שם, השמיט תיבת „וזריז\")."]]],[1300171388,"בן עזאי „הוי רץ למצוה קלה\" — וואָס איז ניט שווה בכל נפש.\nדער ביאור אין דעם:\n„יהודה בן תימא\" רעדט ניט (אַזוי) וועגן דער ריצה ושמחה בעת עשיית המצוות, נאָר וועגן דער „ריצה\" ביי דער כללות'דיקער מסירה ונתינה וואָס אַ איד גיט זיך איבער צו עבודת ה' בתחלת היום, נאָך איידער ער פאַר־נעמט זיך מיט פרטיות'דיקע עניני עבודה 44; ע\"ד אמירת מודה אני „מיד כשניער משנתו\" 45, וואָס דאָס איז די הודאה כללית 46 און די מסירה ונתינה צום אויבערשטן בתחלת היום.\n[און דערפאַר: (א) זאָגט ער דאָ ניט דעם לשון „הוי רץ למצוה\", נאָר — „לעשות רצון אביך שבשמים\", וואָס איז די נקודה כללית פון אַלע עניני עבודה שבמשך היום; (ב) דאָס איז געשטעלט געוואָרן אין אָנהויב פון גאַנץ שו\"ע, און נאָכמער — נאָך פאַר דעם ענין פון אמירת מודה אני — ווייל די מסירה ונתינה צו עבודת ה' וואָס יהודה בן תימא איז אויסן מיט זיין הוראה, איז אַ מער כללות'דיקע „הודאה\" ומסירה ונתינה אפילו מער פון דער הודאה פון מודה אני].\nאון די התעוררות כללית צו עבודת ה' איז שייך צו יעדער איד, אין וואָס פאַר אַ מצב ער זאָל נאָר זיין, וע\"ד הידוע אינעם ענין פון אמירת מודה אני, אַז דער טעם פנימי וואָס מען זאָגט עס פאַר נעגל־וואַסער און אפילו בידים טמאות, איז ווייל „כל הטומאות שבעולם זיינען ניט מטמא דעם מודה אני פון אַ אידן. ער קען זיין אַ חסר בזה או בזה, אָבער דער מודה אני בלייבט גאַנץ\" 47.\nיו\"ד. אויף דעם טוט אויף בן עזאי אַ הוראה נוספת (אין מילי דחסידותא) — „הוי רץ למצוה קלה ובורח מן העבירה\": אפילו ווען מ'איז אַריינ־געטאָן אין דער עשי' פון אַ מצוה פרטית, ניט טראַכטנדיק באותה שעה וועגן דער כוונה כללית פון דער מצוה (וואָס איז גלייך ביי אַלע מצוות): „אשר קדשנו במצותיו וצונו\" 48 (לעשות רצון אביך שבשמים) — נאָר וועגן דעם תוכן (וסגולה) פון דער מצוה פרטית [וואָס דערפאַר פילט ער ווי דאָס איז אַ „מצוה קלה\"] — דאַרף אַ איד פועל'ן ביי זיך אַז זי זאָל געטאָן ווערן אין אַן אופן פון „רץ\", מיט אַ שמחה וחיות בלתי מוגבלת.\nווי מאָנט עס בן עזאי ביי אַ אידן, אַז דער תוכן וענין פרטי פון אַ מצוה (וואָס איז לכאורה אַן ענין שבמדידה והגבלה<sup data-n=\"49\">49</sup> זאָל אַרויסרופן אַ תנועה פון",[["44","44","אבל רישומו ניכר גם בעבודתו במשך כל היום, שמצד מסירה ונתינה זו הוא רץ בחיות ושמחה כפשוטה * בכל עניני עבודת ה' במשך היום (וראה ב\"ח או\"ח בתחלתו) — אלא שהריצה היא (לא מצד תוכן הפרטי שבכל מצוה — כהוראת בן עזאי, כדלקמן סעיף יו\"ד — כ\"א) מצד הנקודה הכללית שבכל מצוה ומצוה — „לעשות רצון אביך שבשמים\", ובמילא היא בכל מצוה בשווה. וראה לעיל הערה 7."],["45","45","שו\"ע אדה\"ז או\"ח מהד\"ת ס\"א ס\"ו. מהד\"ק שם ס\"ה."],["46","46","ראה לקו\"ש חט\"ו ע' 256, ובארוכה לקו\"ש חכ\"א ע' 282 ואילך (ועוד), שזה מרומז גם בשם בעל המאמר — יהודה בן תימא (מלשון הודאה כו'), ע\"ש. *) ועפ\"ז כוונת יהודה בן תימא היא גם לריצה כפשוטה ברגלים, וכפשטות לשון הטור „ואמר רץ כצבי כנגד הרגלים שרגליך לטוב ירוצו\". וראה ב\"ח ופרישה שם."],["47","47","היום יום ע' יט. וראה בארוכה קונט' ענינה של תורת החסידות סי\"א ובהערות."],["48","48","כנוסח ברכת כל המצוות."],["49","49","ראה בארוכה לקו\"ש חי\"ד ע' 181. לקו\"ש חט\"ו ע' 140."]]],[1300171389,"„ריצה\" שלמעלה ממדידה והגבלה ?\nאיז עס דערפאַר וואָס דאָס איז גע־ווען בן עזאי'ס הנהגה בכלל 50 — ער האָט זיך געקאָכט אין דער תנועה פון „רצוא\", אַרויסגיין פון וועלט: וואָס דערפאַר האָט ער זיך ניט עוסק געווען בפרי' ורבי', זאָגענדיג „מה אעשה שנפשי חשקה בתורה\" 51 [ביז דערפון איז סו\"ס אַרויס, אַז זיין כניסה לפרדס איז געווען אין אַן אופן פון „הציץ ומת\" 52 — „רצוא\" אָן אַ „שוב\" (דוגמת מיתת שני בני אהרן)].\nומהאי טעמא, איז אויך זיין עבודה אין עניני „תיקון\" — עשיית מצוות — גע־ווען אין אַן אופן פון „רצוא\" 53, אַז ער האָט דערהערט דעם גודל ה„נעימות עריבות . . מתיקות\" (בלשון האוה\"ח הק' 54 לגבי דער רצוא פון די שני בני אהרן) וואָס איז דאָ אין מצוות, וואָס דאָס רופט אַרויס אַ ריצה ושמחה אין קיום המצוות באופן בלתי מדוד ומוגבל 55, העכער אפילו פון די הגבלות פון דער אייגענער נפש האלקית.\nאון דערמיט איז פאַרענטפערט פאַר־וואָס דאָ פּאַסט ניט דער לשון „הוי רץ למצוה קלה כלחמורה\", ווייל די „נעימות\" פון מצוות (וואָס רופט אַרויס די ריצה למצוות) איז מצד דעם תוכן פרטי שבכל מצוה, ובמילא איז ניט גלייך די „נעימות\" פון אַ מצוה קלה צו דער „נעימות\" פון אַ מצוה חמורה,\nואדרבה, דער עיקר אויפטו איז „הוי רץ למצוה קלה\", אַז אפילו אין אַ מצוה קלה איז דאָ אַ „נעימות\" בלתי מוגבלת, וואָס דערפאַר דאַרף זיין ריצה אויך צו אַזאַ מצוה.\nיא. אין דערהערן די טייערקייט, די „נעימות\" פון מצוות, קענען זיין צוויי אופנים: (א) ער דערהערט דעם גודל הנעימות וואָס איז דאָ אין די מצוות עצמן — „קרבת אלקים טוב\"; (ב) ער דערהערט וואָס ער — נפשו האלקית — וועט פון דעם האָבן — „קרבת אלקים לי טוב\" 56.\nאון דאָס זיינען די צוויי טעמים וואָס בן עזאי זאָגט — פאַרוואָס עס דאַרף זיין „הוי רץ למצוה כו'\" — (א) שמצוה גוררת מצוה, (ב) ששכר מצוה מצוה:\nהטעם העיקרי: בנוגע דער „נעימות\" וואָס איז דאָ אין דער מצוה גופא „מצוה גוררת מצוה\" — דער גודל הנעימות שבמצוות איז דאָס וואָס זי איז „גוררת מצוה\" — זי ברענגט דעם צוותא וחיבור 57 פון אידן מיטן אויבערשטן 58;\nוויבאַלד אָבער אַז בן עזאי זאָגט אַ הוראה אויך פאַר אַזעלכע וואָס האַלטן",[["50","50","ראה בכ\"ז ד\"ה וכל הלבבות (אוה\"ת אחרי ע' תקמ). ד\"ה אחרי מות תרמ\"ט פ\"ג."],["51","51","יבמות סג, ב."],["52","52","חגיגה יד, ב."],["53","53","ע\"ד הנהגתו ד„נפשי חשקה בתורה\" שהיא הנהגה דתיקון (ראה הל' ת\"ת לאדה\"ז רפ\"ג בקו\"א ד„אין בידו — דהעושה כן — עון\"), אלא שבהנהגה דתיקון עצמו — ה\"ז הנהגה דרצוא ולא הנהגה דקיום העולם (עיי\"ש בקו\"א)."],["54","54","ר\"פ אחרי. הובא במאמרי אדה\"ז אתהלך־לאזניא ד\"ה כתוב באוה\"ח. דרך חיים שם פל\"ג. ד\"ה וכל הלבבות שם בתחלתו. ד\"ה אחרי מות שם פי\"ב. ועייג\"כ אגה\"ק סי' כט (קמט, א)."],["55","55","להעיר גם מלקו\"ש חי\"ד ע' 52."],["56","56","תהלים עג, כח."],["57","57","כן פירש הה\"מ — בנדו\"ד — לקו\"א סרנ\"ט (סז, רע\"א). או\"ת צג, ריש ע\"ד."],["58","58","אין הכוונה כאן להצוותא וחיבור שנעשה מצד קיום רצון העליון (שבזה אין הפרש בין מצוה למצוה), כ\"א להצוותא וחיבור שמצד ההמשכה פרטית דכל מצוה (תפלין — המשכת המוחין, וכו'), שבזה היא ה„נעימות\" שבמצוות, ובפרט באם תימצי לומר שגם עי\"ז נעשה חיבור וכו' ממש ולא רק מרכבה וכו'. ואכ\"מ."]]],[1300171390,"נאָך ניט ביי דער דרגא פון „קרבת אלקים טוב\" — אפילו פאַר אַזאַ וואָס האַלט נאָך ביי תחלת העבודה ובמילא טוט ער נאָר די עבודה וואָס ער פילט ווי עס איז נוגע צו אים — איז ער דערי־בער מוסיף „ששכר מצוה מצוה\":\nאויך דער שכר פון מצוות — וואָס „שכר\" איז אַ זאַך, וואָס דער אדם פילט אַז ער האָט פון דעם פאַרדינט — איז „מצוה\", וואָס ער באַהעפט זיך מיטן אויבערשטן 58 באופן אַז ער פילט אַ נעימות בלתי מוגבלת (וכידוע בענין שכר מצות בהאי עלמא ליכא 59, ווייל שכר המצות איז בלי גבול און „עולם\" קען ניט מכיל זיין דעם גודל השכר),\nאון דעריבער, אויך צוליב שכר מצוה, דאַרף זיין ריצה — בלי מדידות והגבלות.\n(משיחות ש\"פ אמור וש\"פ בהו\"ב תשכ\"ד)",[["59","59","קידושין לט, ב. אגה\"ק סי' ג'. סי' כג."]]],[1300171391,"<h3>פרק חמישי</h3>\nא. אין היינטיקן פרק¹ רעכנט אויס דער תנא עשרה דברים וואס „נבראו בערב שבת בין השמשות”. דערנאך ברענגט ער נאך א דיעה אז „אף קברו של משה רבנו ואילו של אברהם אבינו”, און איז מסיים: וי״א אף המזיקין ואף צבת בצבת עשוי׳².\nדער פירוש פון „צבת בצבת עשוי׳” איז (ווי די גמרא זאגט אין פסחים³): א צבת קען געמאכט ווערן ווען מ׳באנוצט דערביי אן אנדער צבת. שטעלט זיך די שאלה: ווער האט געמאכט די ערשטע צבת? זאגט מען, אז די ערשטע צבת איז געווען א בריאה בידי שמים⁴; און די צבת איז באשאפן געווארן בערב שבת בין השמשות.\nדארף מען פארשטיין: וואס איז די שייכות פון (בריאת ה)צבת צום זמן פון ערב שבת בין השמשות?\nבנוגע די אנדערע זאכן וואס ווערן גערעכנט אין משנה, זיינען מפרשים⁵ מסביר דעם טעם פארוואס זייער בריאה איז געווען בע״ש ביה״ש: וויבאלד זיי זיינען זאכן וועלכע זיינען ניט אין גדר הטבע פון די נבראים וועלכע זיינען באשאפן געווארן בששת ימי בראשית, נאר זיי זיינען דברים נסיים — דעריבער זיינען זיי באשאפן געווארן אין דעם זמן הסמוך לשבת, וואס שבת איז דער זמן המנוחה והשביתה פון בריאת דברים טבעיים.\nאבער דער חידוש פון „צבת בצבת עשוי׳” איז אן ענין טבעי, אזוי איז געווען (ואדרבה, ביתר חידוש) ביי כל הבע״ח וצמחים: די מציאות פון א שפעטערדיקן בע״ח אדער צומח מוז אנקומען צו א פריערדיקן (ביז צום — נברא בידי שמים) — איז פארוואס איז דער צבת באשאפן געווארן דוקא בערב שבת בין השמשות⁶?\nנאך מער תמי׳: די גמרא זאגט אין סנהדרין⁷, אז דער טעם וואס אדה״ר איז באשאפן געווארן ביום הששי (נאך אלע נבראים), איז „כדי (שימצא הכל מוכן) שיכנס לסעודה מיד”, ולפי הנ״ל, אז די ערשטע צבת איז באשאפן געווארן ערשט בערב שבת ביה״ש — נאך בריאת אדה״ר — קומט אויס, אז ס׳איז ניט געווען „הכל מוכן”, ווייל די „צבת” איז נאך ניט געווען „מוכן”.",[["1","1","משנה ו."],["2","2","כן הוא גירסת אדה״ז בסידורו. ובמשניות לפנינו „מזיקין” נמנה בדברי הי״א שלפנ״ז. וראה כמה גירסאות במפרשי המשנה, ברייתות דפסחים (נד, א) ועוד. ואכ״מ."],["3","3","שם. וראה גם רש״י, רע״ב (ועוד) למשנה כאן."],["4","4","בפסחים שם נדחה זה כי „אפשר יעשנה בדפוס ויקבענה . . ברי׳ בידי אדם”. וראה לקמן הערה 6."],["5","5","דרך חיים (למהר״ל). וראה רמב״ם: המובא במדרש שמואל ועוד כאן."],["6","6","כמו שהקשה בפרקי משה (להר״מ אלמושנינו) כאן. ויש להוסיף בהקושיא, ע״פ מסקנת הגמ׳ (פסחים שם) ד„אפשר יעשנה בדפוס כו׳” — שהרי דוחק לומר שפליגי במציאות, ובפרט שמעשים בכ״י שעושים כלים בדפוס כו׳ — ועכצ״ל, דזה שסתם במשנה כאן (ועד״ז בתוספתא וירושלמי סוף עירובין. תוספתא חגיגה ספ״א) „צבת בצבת עשוי׳”, הוא (לא מפני שמוכרח להיות כן, כ״א) מפני שיש כוונה בזה שצבת הא׳ היא בריאה בידי שמים (שמצד תוכן זה נבראה בערב שבת ביה״ש), כדלקמן בפנים סעיף ז."],["7","7","לח, א וברש״י."]]],[1300171392,"[פון די אנדערע „עשרה דברים וכו׳” איז ניט קיין קשיא כלל, זיי אלע זיינען געווען באשטימט פאר שפעטערדיקע דורות, ניט זאכן וועלכע זיינען שייך („מוכן”) פאר אדה״ר⁸ — אבער „צבת” איז לכאורה ניט קיין יוצא מן הכלל פונעם „הכל מוכן” וואס נעמט ארום אלע נבראים פון ששת ימי בראשית].\nב. אויך דארף מען פארשטיין:\nא) פארוואס זאגט ער דאס דורך דער הודעה אז „ואף צבת בצבת עשוי׳”, וואס אין די ווערטער רעדט זיך ניט וועגן דער בריאה פון דער ערשטער צבת\n(אדרבה, בפשטות מיינט עס א שפעטערדיקע צבת וואס זי איז „עשוי׳” פון א פריערדיקער צבת: נאר, פון דעם דרינגט מען ארויס אז גאר די ערשטע צבת האט געמוזט זיין א בריאה בידי שמים, און פון דעם (וואס ער שטעלט דעם ענין אין דער משנה) פארשטייט מען, אז דערמיט וויל די משנה זאגן אז א צבת איז באשאפן געווארן בערב שבת ביה״ש) —\nלכאורה וואלט מען געדארפט זאגן⁹ מיט קלארקייט ובקיצור „ואף הצבת”¹⁰ (ווי עס שטייט טאקע אין מס׳ פסחים¹¹: ר׳ יהודה אומר אף הצבת)?\nב) פון דעם וואס די זעלבע י״א זיינען מוסיף די צוויי זאכן — מזיקין און צבת — איז פארשטאנדיק, אז זיי האבן א נקודה משותפת, וואס צוליב דעם זיינען זיי ביידע (לויט דער שיטה המיוחדת פון די י״א) באשאפן געווארן בערב שבת ביה״ש\n[אמת טאקע, אז פון דעם לשון „ואף צבת כו׳” — ניט „וצבת כו׳” (ווי בא די פריערדיקע י״א: „אף קברו . . ואילו כו׳”) — איז משמע, אז מזיקין און צבת זיינען באזונדערע פרטים; אבער דאך מוז מען זאגן, אז זיי האבן א צד השווה וואס לויט שיטת י״א איז ער מכריח צו מוסיף זיין זיי אויף די פריערדיקע דעות]\nדארף מען פארשטיין: וואס איז דער צד השווה פון מזיקין און צבת¹²?\nג) וואס איז די הוראה אין עבודת ה׳ בכלל — ובפרט אין „מילי דחסידותא” — תוכן מס׳ אבות¹³ — וואס מ׳לערנט ארויס פון דעם וואס „ואף צבת בצבת עשוי׳”?\nדי אנדערע אויסגערעכנטע „דברים” האבן עכ״פ א שייכות מיוחדת צו אידן, און ווי די מפרשי המשנה¹⁴ זיינען מסביר, אז די זאכן זיינען „לתועלתם של ישראל” — אבער א צבת האט ניט קיין באזונדערע שייכות דוקא צו אידן, ועאכו״כ צו דער עבודה פון אידן.\nג. וועט מען דאס פארשטיין בהקדים דעם פירוש (פנימי) אין דעם מאמר חז״ל הנ״ל, אז אדה״ר איז באשאפן געווארן ביום ששי (נאך דעם וואס אלץ איז",[["8","8","אבל ראה לקמן בפנים סעיף ג."],["9","9","כמו שהקשה בפרקי משה כאן."],["10","10","ודוחק לומר שזהו מפני שרצה לבאר הטעם שהוצרך הקב״ה לברוא הצבת (בידי שמים) — כי: א) בלאה״כ אין זה טעם לבריאתה בערב שבת ביה״ש (כנ״ל ס״א), שזהו העיקר כאן. ב) לא הו״ל להשמיט העיקר (ע״ד צבת הא׳ שנבראה בידי שמים) ולהזכיר רק הצבת העשוי׳ בצבת. ג) אם בברייתא דפסחים דיו ב„אף הצבת” (כדלקמן), מכש״כ שכן הי׳ צ״ל במשנה שהיא „דבר קצר” (רמב״ם בהקדמתו לפיה״מ)."],["11","11","שם."],["12","12","כמו שהקשה בדרך חיים כאן (ולכן גריס „וי״א אף צבת כו׳”). וראה מד״ש כאן (בסופו)."],["13","13","ראה ב״ק ל, א."],["14","14","מדרש שמואל כאן. וראה גם מאירי כאן."]]],[1300171393,"געווען „מוכן”), „כדי שיכנס לסעודה מיד” — אז דאס מיינט, אז ער זאל האבן אלץ „מוכן” צו קענען טאן (גלייך) זיין עבודה.\nווארום ס׳איז א כלל¹⁵ אז „כל מה שנברא בששת ימי בראשית צריכין עשיי׳ (תיקון)” — „אשר ברא אלקים לעשות¹⁶ — לתקן”, וואס זייער תיקון ווערט אויפגעטאן דורך דעם אדם. און דאס מיינט די „סעודה” פון אדה״ר — די זאכן וואס ער דארף האבן פאר זיין עבודה¹⁷, „כל מה שנברא בששת ימי בראשית” וואס ער דארף מתקן זיין.\nדאס איז אויך דער ביאור פנימי פארוואס די זאכן וואס זיינען באשאפן געווארן בערב שבת ביה״ש זיינען ניט פון „סעודת” אדה״ר: און וויבאלד אז יעדער איד איז בדוגמת אדה״ר¹⁸, „אתם קרויין אדם”¹⁹, איז מובן, אז זיי געהערן אויך ניט צו דער „סעודה”-עבודה פון אידן (אפילו) אין שפעטערדיקע דורות:\nדי אויסגערעכנטע עשרה דברים זיינען ניט „מוכן” פאר עבודת האדם²⁰, זיי דארפן ניט האבן קיין עשיי׳ ותיקון דורך דעם אדם, ווייל דער אויבערשטער האט זיי לכתחלה באשאפן אלס „פארענדיקטע” און „פארטיקע” זאכן²¹. ומהאי טעמא זיינען זיי נברא געווארן בערב שבת ביה״ש, בסמיכות צו שבת, וואס דעמאלט איז דער זמן פון תענוג ומנוחה פון עשי׳ ועמל:\nאויך דער ענין פון עבודת ה׳ וואס איז דא בשבת, איז ניט צו מברר ומתקן זיין עניני העולם דששת ימי בראשית²² (שבת איז מען קדוש ומובדל פון וועלט זאכן, עניני חול), נאר די עבודה איז אין קדושה גופא, צו עולה זיין מדרגא לדרגא, וואס דערפאר איז די עבודה מתוך תענוג (בלי עמל)²³.\nד. כשם ווי די עשרה דברים הנ״ל (און די עבודה ביום השבת) גייען ניט אריין אין דער „סעודה”-עבודה פון דעם אדם — ווייל זיי זיינען מצד עצמם העכער פון די אנדערע נבראים (ובמילא פעלט ניט אין זיי דער ענין פון „לעשות לתקן” דורך עבודת האדם),\nאזוי זיינען אויך, אין קצה ההפכי, פאראן אזעלכע זאכן וואס זיינען ניט „מוכן” (מצ״ע) לעבודת האדם — ווייל זיי זיינען נידעריקער פון די נבראים פון ששת ימי בראשית און דער אדם קען זיי ניט מתקן זיין דורך אן עבודה רגילה ומסודרה; כדי זיי מתקן זיין דארף ער האבן די עבודה ניט פון „וחי בהם”²⁴ נאר פון מסירת נפש, פון „בכל מאדך”, העכער פון זיינע (טבעית׳דיקע) הגבלות.\nאון דערפאר זיינען אויך די זאכן ניט שייך צו דער „סעודה”-עבודה פון דעם",[["15","15","ב״ר פי״א, ו וברש״י לשם."],["16","16","בראשית ב, ג."],["17","17","„סעודה” (ועד״ז „יאכל” שברש״י שם) במובנו הרחב, שכולל כל צרכי האדם (ראה גמ׳ שם: וכל צורכי עולם), והרי עבודת האדם היא עיקר צרכיו, מכיון שזהו תכלית בריאתו."],["18","18","ראה סנהדרין לז, א. לח, א."],["19","19","יבמות סא, רע״א. וש״נ. וראה לקו״ת נצבים מז, ב."],["20","20","להעיר גם מאוה״ת דרושים לש״ש (ע׳ א׳תקמ) שהעשרה דברים שנבראו בע״ש ביה״ש שייכים למלאכת הרשעים או מלאכת הצדיקים (ב״ר ספי״א). אבל ראה ד״ה טוב טעם תש״ג (פט״ז)."],["21","21","ראה יומא (עה, א) בנוגע המן, שלצדיקים הי׳ לחם אפוי. ולא הי׳ בו פסולת (שם, ב). וראה תו״א פט, א-ב. לקו״ש ח״ד ע׳ 1036 ואילך (וש״נ). ועוד."],["22","22","להעיר מהמבואר בכ״מ (פע״ח הקדמה לש׳ השבת. ובכ״מ) שבשבת הוא עליית העולמות. ועיין סה״מ להצ״צ סוף מצות לא תבערו אש."],["23","23","ראה בכ״ז לקו״ת בלק עב, א ואילך. ובכ״מ."],["24","24","אחרי יח, ה. סנה׳ עד, א."]]],[1300171394,"אדם, ווייל עבודת האדם ווי זי איז (לכתחילה) אויסגעשטעלט געווארן מלמעלה, איז אין אן אופן פון וחי בהם, סדר והדרגה דוקא²⁵.\n[און ווי דאס איז מרומז אין דעם שם „אדם”, וואס די אותיות א׳ד׳ם׳ ווייזן, כידוע²⁶, אויפן ציור מסודר פון אדם (ראש גוף ורגל: מחשבה דבור ומעשה) — עבודה מסודרה: משא״כ „בכל מאדך” איז ווען מ׳איז מהפך דעם צירוף אדם — דער ענין פון „מאד”, העכער פון הגבלה²⁷].\nה. און דאס איז וואס די י״א זיינען מוסיף „אף המזיקין ואף צבת כו׳”:\n„מזיקין” זיינען ניט קיין זאכן אין וועלכע עס איז דא תיקון עבודת האדם, עבודה אויף זיי צו מתקן זיין — זייער מציאות האט זיך געשאפן מצד דעם חטא האדם²⁸, און עבודתו איז זיי שולל זיין, זיי מאבד זיין.\nאון אע״פ אז די תכלית הכוונה איז אז מ׳זאל זיי מהפך זיין לטוב, בלשון חז״ל²⁹ „משביתן שלא יזיקו” (זיי זיינען (אבער—) ניט מזיק, אויס מזיקין) — איז דאס אבער ניט אן ענין פון עשי׳ ותיקון אין זיי גופא, מ׳מאכט עס ניט דורך מגלה זיין דעם טוב וואס אין זיי — די מציאות זייערע איז דאס וואס זיי זיינען מזיקין — נאר מ׳פועלט אין זיי א חידוש³⁰, זיי ווערן (ווי) א נייע מציאות וואס איז פריער ניט געווען³¹.\nאון דאס איז די שייכות פון בריאת המזיקין צו ערב שבת בין השמשות:\nווי מזיקין ווערן באשאפן מלמעלה איז זייער מציאות, זייער „תכלית” — דאס וואס זיי וועלן סוף־סוף נתהפך ווערן לטוב; און דערפאר איז זייער בריאה (מלמעלה) געווען בערב שבת ביה״ש, ווייל אט דער חידוש אין די מזיקין („שלא יזיקו”) האט ניט קיין ארט מצד גדרי הטבע פון וועלט (ששת ימי בראשית), נאר דוקא מצד דעם כח פון שבת³², וואס איז העכער פון (די מדידות פון) וועלט.\nאון דערפאר איז אויך די עבודה ניט פון דער „סעודה” של האדם³³, ווייבאלד",[["25","25","וכמו שהוא בפשטות, שבששת ימי החול (שאז הוא זמן העבודה דבירור וזיכוך עניני העולם כנ״ל), האדם מלובש בעניני העולם, ואינו שייך (כ״כ) ליציאה מהגבלות הטבעיות שלו (משא״כ בשבת, ששובת מעניני עולם כו׳)."],["26","26","לקו״ת בהעלותך לא, ג. וראה המשך וככה תרל״ז פרק כ. ועוד."],["27","27","המשך וככה שם. ועוד."],["28","28","ראה נחלת אבות כאן (בסופו). רמב״ן בחוקותי כו, ו (לענין חיות רעות). וראה פרקי משה כאן: שמציאותם הוא מציאות הכחניות אל הרע כו׳."],["29","29","תו״כ בחוקותי שם. וראה אוה״ת (יהל אור) להצ״צ עה״פ (תהלים צב, א) מזמור שיר ליום השבת (ובמילואים שם). המשך מים רבים תרל״ז פקס״א ואילך. לקו״ש ח״ז שיחה א׳ לפ׳ בחוקותי (וראה שם ע׳ 196). לעיל ע׳ 59 ואילך."],["30","30","להעיר מלקו״ש ח״ז ע׳ 22 ואילך (ועוד) — לענין כללות העבודה של ביטול הסט״א שבעולם."],["31","31","אף שלפני החטא לא הזיקו (כנ״ל מרמב״ן) — מ״מ אי״ז דומה ל„משביתן שלא יזיקו” דלעת״ל (ראה לקו״ש ח״ז שם ע׳ 194 הערה 29)."],["32","32","ראה תו״כ שם: „וכה״א מזמור שיר ליום השבת — למשבית מזיקים מן העולם”. וראה יהל אור והמשך מים רבים שם השייכות לענין השבת. ולהעיר מהשייכות בין שבת לתשובה (שע״י זדונות נעשות לו כזכיות — יומא פו, ב) — אגה״ת ספ״י. לקו״ת לש״ש סו, ג. ובכ״מ. וראה ב״ר ספכ״ב וביפה תואר שם."],["33","33","נוסף לזה שאין שייך לומר ע״ז שהוא „מוכן” להאדם מכיון שכל מציאות המזיקין נתחדשה ע״י חטא האדם כנ״ל* — הנה גם עצם תנועת העבודה אינה מ„סעודתו”, כבפנים. *) להעיר גם מנחלת אבות (ועד״ז בלחם שמים להיעב״ץ) כאן, שהעשרה דברים „מתיחסים לחטא אדם וחוה”, ולכן נבראו רק לאחרי שסרח כו׳, ע״ש."]]],[1300171395,"אז דער תיקון פון די מזיקין איז דורך דעם וואס דער אדם גייט ארויס פון זיין „אדם”, זיינע טבעית׳דיקע הגבלות³⁴.\nו. אויף דעם זיינען די י״א אויך מוסיף „ואף צבת כו׳”: מצד אן ענלעכן טעם (ווי ביי די מזיקין), איז אויך „צבת” פון די זאכן שנבראו בערב שבת ביה״ש (נאר ביי „צבת” איז דאס ניט אזוי ווי ביי מזיקין, וואס דערפאר איז ער מדייק „ואף צבת כו׳”); און די הסברה אין דעם איז, ווייל „צבת בצבת עשוי׳”:\nמיטן לשון „צבת בצבת עשוי׳” ווערט ארויסגעבראכט, אז די מטרת הבריאה פון דער ערשטער צבת איז געווען אויסשליסלעך צוליב דעם אז מ׳זאל קענען מאכן דערנאך א צווייטע צבת: אלע נבראים (פון ששת ימי בראשית) — אויך די זאכן וואס פון זיי קומען ארויס (אדער מיט זיי ווערט געמאכט) נאך אנדערע זאכן — זיינען באשאפן געווארן (אויך) מיט א כוונה ותכלית אין זיי גופא, פאר זיך. אבער די בריאה פון דער ערשטער צבת איז געווען באופן, אז אין איר איז ניט געווען קיין מטרה ותכלית פאר זיך, איר גאנצע באשאף איז געווען נאר צוליב „צבת בצבת עשוי׳” — אז אדה״ר זאל מיט איר קענען מאכן א צווייטע צבת.\nיעדער ענין וואס איז דא אין וועלט איז דא „פריער” אין תורה³⁵. דער ענין פון „צבת בצבת עשוי׳” אין תורה — איז דער ענין פון הכשר מצוה.\nדי פעולת ההכשר איז ניט קיין מצוה, נאר בלויז אן אמצעי דורך וועלכן מ׳קומט צו צו מקיים זיין א מצוה מיט אן אנדער זאך. ווי די דוגמא³⁶: כורתין עצים לעשות פחמין לעשות ברזל (לאיזמל למילה) — וואס מיט די עצים ווערט ניט געטאן קיין מצוה, זיי זיינען בלויז א מכשיר למכשיר כו׳ צו מצות מילה.\nווייבאלד אז די כריתת עצים וכיו״ב איז בלויז א הכשר, דארף לכאורה אויסקומען (אויך ע״פ שכל התורה), אז זיי אליין ווערן ניט קיין כלי צו קדושה: דורך זייער פעולה אליין ווערט ניט אויפגעטאן המשכות אלקות, מען קען אפילו ניט זאגן אז זיי זיינען „מלובש” אין דער מצוה ווי מען זאגט עס — בעת א איד עסט א מאכל לשם שמים „לעבוד ה׳ בכח אכילה ההיא”³⁷, וואס דער חיות פון דעם מאכל איז זיך מתלבש „בתיבות התורה והתפלה”³⁷ (וכיו״ב) וואס ער האט געטאן „בכח אכילה ההיא”\nזייער תכלית פירט זיך אויס נאר דורך דעם וואס א צווייטע זאך ווערט א (מצוה און א) כלי לקדושה³⁸.\nז. און דאס איז דער חידוש אין דער משנה, אז „אף צבת בצבת עשוי׳”: אויך די „צבת” וואס איז באשאפן געווארן בלויז כדי מ׳זאל קענען מאכן דורך איר א צווייטע צבת — האט זיך דער אויבערשטער אליין („מהותו ועצמותו של המאציל ב״ה”³⁹) פארנומען מיט איר באשאף:",[["34","34","ראה בארוכה לקו״ש חי״ב (ע׳ 74 ואילך) שענין ההתחדשות (בהעבודה של אתהפכא כו׳) הוא מצד כח העצמות שבנש״י, מכיון שישראל וקוב״ה כולא חד, ע״ש."],["35","35","ראה ב״ר בתחלתה. זח״ב קסא, א-ב."],["36","36","שבת קל, א וברש״י שם."],["37","37","לשון התניא רפ״ח. וראה שם פ״ז: פל״ז (מז, א)."],["38","38","וזהו ההשוואה ל„מזיקין” (נוסף על ההשוואה בעבודת האדם בהם, כדלקמן בפנים) — שמציאותם אע״פ להעשות כלים לקדושה, ונמצא שאין תכלית בהם גופא (כי אם שע״י נעשית מציאות אחרת וחדשה שאינה מזיק)."],["39","39","אגה״ק סי׳ כ (קל, סע״א ואילך)."]]],[1300171396,"און ווייבאלד אז זי איז מעשה ידי הקב״ה (באופן גלוי), קען מען ניט זאגן, אז די מטרה פון איר גאנצער מציאות איז מער ניט ווי צוליב אן אנדער זאך — און נאך דעם ווי מ׳האט איר אויסגענוצט צו מאכן די צווייטע צבת, איז שוין מער ניטא קיין תכלית פאר איר מציאות — נאר זי באקומט דערמיט אויך א חשיבות ותכלית לעצמה⁴⁰.\nאון די סיבה אויף דעם וואס דאס איז אזוי אין גשמיות, איז ווייל אזוי איז דאס אין תורה: אע״פ אז מצד אן עבודה מסודרה, עבודה שע״פ טעם ודעת, איז אין א הכשר מצוה כו׳ ניטא קיין תכלית וחשיבות פאר זיך — אבער מצד דעם רצון העליון⁴¹ (פון דעם אויבערשטן אליין) וואס איז דא אין דעם, איז ניטא קיין חילוק⁴² צווישן דער מצוה גופא (וואס איז ממשיך אלקות) און דעם הכשר מצוה⁴³.\nאון דערפאר, ווען א איד שטייט מיט א ביטול עליון צום רצון העליון (העכער פון זיין טעם ודעת), איז ביי אים ניטא קיין נפק״מ אין וואס דער רצון העליון באשטייט — ווי דער אלטער רבי זאגט⁴⁴, אז אפילו „אלו נצטוה לחטוב עצים” (וואס וואלט ניט אויפגעטאן קיין „יחוד” והמשכת אלקות), איז ער דאס מקיים מיטן זעלבן קאך.\n[און דערפאר האט אויך די עבודה א שייכות צו ערב שבת ביה״ש — ווי־באלד ס׳איז אן עבודה וואס איז העכער פון עבודת ציור „אדם”, פון דער עבודה מסודרה כנ״ל: און דערפון ווערט נשתלשל אויך בנוגע צו ברואים גשמיים, אז די בריאת הצבת איז געווען בע״ש ביה״ש⁴⁵].\nח. דאס איז אויך די הוראה אין מילי דחסידותא — אויף וויפל ס׳איז נוגע די התעסקות פון א אידן אויך אין די ענינים וואס זיינען „ניט מער” ווי א הכשר מצוה; ומעשה רב:\nדי גמרא⁴⁶ דערציילט די „גדולים מעשה חייא”, אז ער אליין האט זיך אפגעגעבן ניט בלויז מיטן עצם לערנען מיט אידישע קינדער, נאר ער האט אליין דורכגעפירט אלע הכנות און הכנות להכנות (הכשר להכשר) צום לימוד התורה — אליין איינגעזייט פלאקס, אויסגעוועבט נעצן, געפאנגען הירשן, געמאכט קלף און געשריבן „חמשה חומשי” פאר די קינדער —\nדלכאורה איז דאס תמוה ביותר: פארוואס האט ר׳ חייא אליין געדארפט טאן די אלע זאכן? האט ער דאס ניט געקענט איבערגעבן צו איינעם פון זיינע",[["40","40","ראה כמה דוגמאות לזה ע״ד ההלכה בצפע״נ להרוגוצ׳ובי (עה״ת ר״פ מסעי. מהד״ת נא, ג. ועוד). וראה לקו״ש חי״ד ע׳ 39. ובארוכה — לעיל ע׳ 187 ואילך."],["41","41","להעיר מדעת ר״א הגדול (שבת קל, א) שגם כריתת עצים הנ״ל דוחה שבת כמו שהמצוה עצמה."],["42","42","והחילוקים שביניהם הם רק מצד ענין הפרטי שבמצוות (ראה לקו״ת שבהערה 44. ועוד). וראה לעיל שם (ע׳ 189 ואילך), שמטעם זה, בתשובה — שהיא „במקום” ענין הכללי של המצות (ועבירות), שהרי ענינה „שיגמור בלבו . . לבל . . יעבור עוד מצות המלך כו׳” (אגה״ת פ״א) — גם הזדונות (שהביאו וגרמו להתשובה מאהבה רבה — „הכשר”) נעשו זכיות, ע״ש."],["43","43","להעיר מלקו״ד (ח״ד ע׳ 1540) שמצד רצון העליון שבמצוות, גם הידור מצוה הוא מעצם המצוה (ראה לקו״ש ח״ג ע׳ 954 הערה 7)."],["44","44","לקו״ת שלח מ, א. וראה המשך תרס״ו ס״ע שס ואילך."],["45","45","אף שמצד עצם בריאת הצבת הי׳ אפ״ל בידי אדם, כנ״ל הערה 6."],["46","46","כתובות קג, ב. ב״מ פה, ב."]]],[1300171397,"תלמידים אדער עבדים אז ער זאל זיך פארנעמען מיט די הכנות (אויסנוצן דערויף איינעם וואס איז ניט קיין יושב אוהל)?\nנאר מצד דעם ביטול עליון צום רצון העליון, איז ביי אים די זעלבע מסירה ונתינה, דער זעלבער „קאך” אין די ענינים פון הכשר והכשר להכשר, ווי אין דער מצוה אליין.\n(משיחת ש״פ בהו״ב חשל״ז)"],[1300171398,"<h3>פ״ה ב•</h3>\nא. „בן הא הא אומר לפום צערא אגרא״¹. איז מפרש דער ברטנורא: „כפי רוב הצער שאתה סובל בלימוד התורה ועשיית המצוה יהי׳ שכרך מרובה״.\nדער ענין פון באקומען שכר פאר מצות איז א חיוב ע״פ הלכה [ווי ס׳איז מוכח אויך פון דעם וואס דער רמב״ם ברענגט עס אין זיין (הלכה) ספר ה״יד״²; און נאכמער: ער איז אין דעם מאריך און מבאר כמה פרטי דינים²•]. ד.ה. אז לויט די דינים פון תורה איז דער אויבערשטער כביכול „מחוייב״ צו געבן שכר דעם מענטשן פאר זיין עבודה, בדוגמא³ צום חיוב פונעם בעה״ב צו באצאלן א פועל פאר זיין ארבעט⁴.\nאון דער חידוש פונעם מאמר „לפום צערא אגרא״ (אין פשטות) באשטייט אין דעם וואס דער שכר ווערט גערעכנט לויט דעם צער, ניט לויט דער פעולה והתועלת והשבח. ועפ״ז — ווען דעם מענטשנס עבודה ברענגט ווייניק תועלת, ביז אז „ההוצאה והצער והטורח יתרים על השבח״⁵ (זיין הארעוואניע און צער כו׳ זיינען מער ווי זייער תוצאה און אויפטו), רעכנט מען דעם שכר ניט לויט דעם שבח נאר ער באקומט דעם פולן שכר פאר זיין ארבעט און זיין צער.\nדארף מען פארשטיין:\nשכר המצות איז מלכתחילה פארבונ־ דען מיט דער הוצאה וטרחא ועמל וצער וואס זיי פארלאנגען, וכמחז״ל בכו״כ מקומות: אם בחוקותי תלכו, שתהיו עמלים בתורה⁶ כו׳ ונתתי גשמיכם גו׳, עובד כו׳ לא עבדו כו׳ אינו דומה שונה פרקו מאה פעמים לשונה פרקו מאה ואחד כו׳ בשני זוזי⁷ (מפני שמשנה רגילותו⁸), ונפש כי תקריב⁹ כו׳ מי דרכו להביא מנחה עני מעלה אני עליו כאילו הקריב נפשו¹⁰. ועוד ועוד.\nועד״ז בא א בעה״ב ופועל: דאס וואס מ׳געפינט (אין ש״ס און פוסקים)¹⁰• אז מ׳צאלט א פועל בלויז דעם „שבח״ ווען די הוצאה איז „יתירה על השבח״ איז",[["","","•) וסיום דמסכת (משניות) אבות (ראה הערה הבאה). מהד״ב של שיחה זו (בלה״ק) נדפסה בס׳ ביאורים לפרקי אבות (קה״ת) בסופו."],["1","1","במשניות הוא בסוף פרק ה׳. וראה לקמן הערה 49, 51."],["2","2","ש„חיבור זה (הוא) הלכות הלכות״ (הקדמת הרמב״ם לספר היד). •2) ראה רמב״ם הל׳ תשובה פ״ג (ה״א־ה). וראה שם פ״ח וט׳. סוף הל׳ מלכים."],["3","3","והסברא לשלילת זה הוא רק „מי הקדימני ואשלם כו׳ נתתי לו נשמה כו׳״ כדרז״ל (ויק״ר פכ״ז, ב)."],["4","4","להעיר מאבות פ״ב מי״ד ומט״ז: בעל מלאכתך כו׳ שכר פעולתך. ושם מט״ו: והפועלים כו׳ ובעה״ב כו׳. ולהעיר מתו״כ (הובא ברש״י עה״פ) בחוקותי כו, ט: משל למלך ששכר פועלים כו׳. וראה לקמן סעיף ח׳."],["5","5","לשון המדרש שמואל סוף מס׳ אבות (בפירוש „לפום צערא אגרא״)."],["6","6","תו״כ (הובא בפרש״י) ר״פ בחוקותי."],["7","7","חגיגה ט, ב. וראה לקמן בפנים ס״ו."],["8","8","תניא פט״ו. וראה סוטה (יא, ב) דעבודת נשים לאנשים — ה״ז עבודת פרך."],["9","9","ויקרא ב, א."],["10","10","מנחות קד, ב. הובא בפרש״י עה״ת שם. •10) והרי „מגיד דבריו ליעקב חוקיו ומשפטיו לישראל כו׳ מה שהוא עושה הוא אומר לישראל לעשות כו׳״ (שמו״ר פ״ל, ט. וראה ירושלמי ר״ה פ״א ה״ג), שעפ״ז מובן שדיני תשלום שכר דבעה״ב לפועל הם דוגמת השכר שמשלם הקב״ה."]]],[1300171399,"נאר אין באשטימטע פאלן: ווען דער בעה״ב האט דעם פועל ניט געדונגען, נאר דער פועל האט עס געטאן על דעת עצמו („היורד לתוך שדה חבירו ונטעה שלא ברשות״¹¹), אדער ווען ער האט געטאן אנדערש ווי דער בעה״ב האט אים אנגעזאגט („אדום וצבעו שחור, שחור וצבעו אדום״¹²), אדער ווען ער האט מזיק געווען בכוונה („צבעו כאור״¹³).\nאבער ווען דער פועל האט געטאן די מלאכה אזוי ווי דער בעה״ב האט אים געהייסן, דאן איז אויך אין פאל אז די יציאה איז יתירה על השבח, און אפילו ווען ער האט גארניט אויפגעטאן — זיין ארבעט האט ניט געבראכט די תועלת וואס זי האט געדארפט ברענגען, ווי „השוכר את הפועל להביא כרוב ודורמסקנין לחולה והלך ומצאו שמת כו׳״¹⁴, וויבאלד אז „עביד שליח שליחו־ תי׳״, ער פון זיין זייט האט געטאן די מלאכה בשלימות (נאר צוליב א גע־ וויסער סיבה האט זיך ניט אויסגעפירט דער תכלית ומכוון פון דער מלאכה), איז דער דין, אז „נותן לו שכרו משלם״¹⁴ (אפילו אין פאל ווען „שכרוהו בשביל החולה יותר ממה שהי׳ ראוי לשוכרו״¹⁵).\nאיז בכן ניט מובן: וויבאלד אז בנדו״ד איז „עביד שליח שליחותי׳״, ער האט געטאן וויפל ער קען אין תום״צ, און נאכמער — די ארבעט האט געבראכט תועלת (כאטש אפילו זי איז קליין אין פארגלייך מיט דער טירחא וצער), איז דאך כש״כ אז מען דארף באצאלן דעם שכר בשלימות¹⁶, כולל אויך זיין הוצאה (צער)¹⁷ אע״פ וואס די הוצאה איז יתירה על השבח — היינט אין וואס בא־ שטייט דער חידוש פון „לפום צערא אגרא״?",[["11","11","ב״מ קא, א. שו״ע חו״מ רסשע״ה."],["12","12","משנה ב״ק ק, ב. שו״ע שם סש״ו ס״ג."],["13","13","ב״ק שם (וראה רש״י שם). שו״ע שם. וראה (ובהבא לקמן) אנציקלופדי׳ תלמודית ערך אומן."],["14","14","ב״ק קטז, סע״א ואילך. וברמב״ם (הל׳ שכירות פ״ט ה״ח) ושו״ע (שם סשל״ה ס״ג) „נותן לו כל שכרו״. ולהעיר, דמפשטות לשון השו״ע והרמ״א (שם ס״ב) ב„השוכר את הפועל להביא לו שליחות ממקום למקום והלך ולא מצא שם מה שיביא נותן לו שכרו משלם דהרי כבר עשה שליח שליחותו״ — משמע, שגם בזה נותן לו כל שכרו מה שפסק (ראה פתחי תשובה שם סק״ג •. ביאורי הגר״א שם סקט״ז). אלא שבסמ״ע (שם סק״ח. ובארוכה — דרישה שם סק״ב) ונתה״מ סק״ב שם — לא פירשו כן."],["15","15","תוד״ה להביא ב״ק (שם, ריש ע״ב. הובא בב״י חו״מ שם). נמוקי׳ שם. פרישה שם סרס״ד סק״ד. נתה״מ הנ״ל. וכן משמע ברמב״ם שם במ״ש „נותן לו כל שכרו״ (ראה הגהות מיי׳ שם. חסדי דוד לתוספתא ב״מ פ״ז, ב בסופו) •. וראה תו״ח ב״ק שם (ומה שהקשה בתוד״ה אין לו יבמות קו, א — ראה שו״ת לחם רב שצויין בגליון הש״ס שם)."],["16","16","והרי גם ב„ירד להציל ולא הציל״ נותן לו שכר פעולה (ב״ק שם. רמב״ם הל׳ גזילה ואבידה פי״ב ה״ד. טושו״ע חו״מ סרס״ד סי״ד). אלא דשם אין לו אלא שכרו הראוי ואינו משלם לו דמי חמורו שהפסיד לו בסיבת הצלתו, כיון ד„לא עביד שליח שליחותי׳״ (ב״ק שם), ד„לאצולי אגרי׳ והא לא אצילי״ (שטמ״ק שם). משא״כ בנדו״ד, שהציווי על האדם הוא על העשי׳ והפעולה (שהרי ההצלחה אינה תלוי׳ בו), הרי מובן דהוה עביד שליחותו ונותנין לו שכרו משלם (גם יותר מהראוי). ואכ״מ."],["17","17","והא דמצינו בהשוכר את הפועל להביא לו שליחות ממקום למקום והלך ולא מצא כו׳, ואם הי׳ דבר כבד מה שיש לו להביא מנכה לו שאינו דומה כו׳ (שו״ע שם) — הרי זה מפני שפעולתו וטרחתו בפועל היתה קלה יותר (מכיון שלא הביא), משא״כ בנדו״ד, שאדרבא, פעולתו וטרחתו היא בשלימות. •) ועיי״ש מה שתירץ בקושיית הלח״מ (הל׳ שכירות שם) מאי שנא הא מדין ירד להציל ולא הציל שאין לו אלא שכרו (נסמן לקמן הערה 16). וראה מחנה אפרים הל׳ שכירות שם. ועוד. •) אבל ראה דרישה שם סשל״ה סק״ב בסופו."]]],[1300171400,"ב. אין די אויבנדערמאנטע דינים איז די טירחא און מלאכה (די „הוצאה״) פון דעם פועל א באזונדער זאך פון דער תועלת („שבח״), וואס דער בעה״ב וועט האבן אלס תוצאה פון זיין מלאכה; און אפילו ווען „עביד שליח שליחותי׳״ איז דאס בלויז וואס ער האט געטאן זיין פעולה בשלימות, אבער דורך דעם האט זיך ניט (אלעמאל) אויפגעטאן דער מכוון צוליב וואס דער בעה״ב האט אים געדונגען.\nאבער בנדו״ד איז דער „צערא״ פון קיום התום״צ ניט קיין באזונדער זאך פון דעם ריוח ושבח; און ווי דער רמב״ם זאגט אין „שמונה פרקים״¹⁸: „שהמתאוה לעבירות ונכסף אליהם הוא יותר חשוב ויותר שלם מאשר לא יתאוה אליהם ולא יצטער בהנחתם כו׳ ולא דים זה עד שיאמר ששכר המושל בנפשו¹⁹ גדול לפי רוב צערו במשלו ואמרו לפום צערא אגרא ויותר מזה שהם ציוו להיות האדם מתאוה לעבירות²⁰ כו׳ לא יאמר אדם אי אפשי כו׳ אלא אפשי ומה אעשה אבי שבשמים גזר עלי״.\nולפ״ז איז נאכמער ניט פארשטאנדיק וואס איז דער חידוש אין לפום צערא אגרא: די הוצאה און צער גופא איז אן ענין פון שבח, ביז אז אויף דעם איז ער גאר נצטווה²¹ געווארן²² — היינט וואס איז דער חידוש אז ער באקומט שכר פאר „צערא״?\nודוחק גדול לומר אז דאס איז טאקע דער אויפטו פון דער משנה און זי איז דער מקור אויף דעם, וכפשטות לשון הרמב״ם וואס בריינגט איר בנדו״ז — וויבאלד אז עס זיינען דא א ריבוי מחז״ל בזה, כנ״ל.\nג. והביאור בזה י״ל: מיט „לפום צערא אגרא״ מיינט די משנה מחדש זיין: צערא סתם, יעדער צער, וביותר ובמיוחד א צער אמתי (אן דעם צומיש פון דעם תענוג וואס ער איז מקיים א ציווי, ווארום עס רעדט זיך וועגן) אזא צער אין תום״צ וואס דער אדם איז אין דעם ניט מחויב, נאר ער אליין נעמט דאס אויף זיך —\n[ועפ״ז יומתק וואס די משנה „לפום צערא אגרא״ שטייט אין מס׳ אבות ובסיומא וחותמה — וועלכע רעדט וועגן „מילי דחסידותא״²³, ענינים וואס זיינען לפנים משורת הדין, כדלקמן סעיף ה׳,\nאון ווי ס׳איז אויך מרומז אין דעם וואס די משנה רופט אן דעם בעל המאמר (פון „לפום צערא אגרא״) ניט מיט זיין פרטיות׳דיקן נאמען, נאר מיטן כינוי „בן הא הא״, וואס איז מדגיש אז",[["18","18","פ״ו. ולהעיר שבפיה״מ (להרמב״ם) אבות ספ״ה מפרש באו״א."],["19","19","ולהעיר, שהמעלה דהכובש את יצרו — וכן השכר על זה — היא הלכה (ראה רמב״ם הל׳ תשובה פ״ז ה״ד)."],["20","20","כ״ה בפיה״מ שלפנינו, ובהעתקת הרב קאפח שתיבות הנ״ל „ציוו .. לעבירות״ אינן בהמקור והן הוספת המעתיק. ובהעתקתו: שהם ציוו שיהא האדם כובש את יצרו (וכן בהמשך הלשון יש שם כמה שינויים בהסגנון)."],["21","21","אלא שמחלק דמה שאמרו „לא יאמר אדם אי אפשי כו׳ אלא אפשי ומה אעשה כו׳״ הוא רק בהתורות השמעיות (חוקים וכיו״ב), אבל במצות השכליות (רעות גם מצד השכל) צ״ל אי אפשי. ע״ש."],["22","22","ראה תוי״ט במשנה כאן מדרך חיים: וזה בשכר הצער הטורח עצמו שאם הוא מרובה שכרו מרובה. אבל שכר מצות עצמן אי אתה יודע שכרן. עיי״ש (בדרך חיים) בארוכה."],["23","23","ראה ב״ק ל, א."]]],[1300171401,"ער איז א גר („בן אברהם ושרה שנתוסף ה״א „בשמם״²⁴ — צו אנדייטן²⁵, אז דא רעדט זיך ווען ער איז מקבל אויף זיך א צער אין וועלכן ער איז כלל ניט מחויב, בדוגמא צו דער גאנצער מציאות (כקטן שנולד) פון א גר: ער איז זיך מגייר²⁶, וואס איז ניטא כלל קיין חיוב בזה, ולאידך נעמט ער אויף זיך די שווערי־ קייט און צער פון קיום כל התום״צ] —\nאון דעריבער וואלט געווען א הוה אמינא, אז פאר אזא צער²⁶• באקומט ער ניט קיין שכר, נאר לויט זיין אויפטו און שבח — ווי ס׳איז דער דין פון דעם וואס באארבעט שדה חברו על דעת עצמו, וואס ער באקומט שכר (ניט פאר זיין פולער „יציאה״) נאר לויטן שיעור פון דער „שבח״ — זאגט די משנה „לפום צערא אגרא״, אז מ׳גיט אים שכר אויך פאר זיין טירחא און צער (הגם ער איז אויף דעם ניט אנגעזאגט געווארן).\nולהעיר — בא א גר איז דאס זיין גאנצע מציאות — עס איז אבער דא דוגמתו בא יעדערן: בא א הידור מצוה, אדער הנהגה טובה, אדער א מינוי לדבר שבקדושה וכו׳ — וואס ער נעמט מעצמו²⁷ אויף זיך²⁷•.\nד. מ׳קען אבער פרעגן: ווען איינער באארבעט דעם חבר׳ס פעלד, אויב דער בעה״ב האט מגלה דעתו געווען, אז עס איז אים ניחא, דארף ער באצאלן דעם פועל פאר דער גאנצער הוצאה (אפילו ווען די הוצאה איז מער ווי דער שבח)²⁸, ולפ״ז איז הדרא קושי׳ לדוכ־ תא: וויבאלד דעם אויבערשטן איז „ניחא״²⁹ דאס וואס דער אדם טוט לפנים משורת הדין, דאס וואס ער איז ניט נצטווה געווארן — איז וואס איז דער חידוש אז „לפום צערא אגרא״ [ביז אז דאס איז (כנ״ל ס״ג) אן ענין פון מדת חסידות]?\nדער ביאור בזה:\nווען מען נעמט אויף זיך א טירחא וצער (אין תום״צ) ניט זייענדיק מחויב אין דעם — ווי א הידור מצוה אדער א הנהגה טובה וכיו״ב, און דערנאך (נאך דעם קיום ג׳ פעמים) איז ער ניט מקיים דעם הידור והנהגה — קומט אויס אז",[["24","24","תוס׳ חגיגה ט, ב. (ושם לענין „בר הי׳ הי׳״ •) מדרש שמואל כאן. ובמח״ז ספ״ג „וכן הוא הא חמש כאותיות אברהם״. ולהעיר דבן הא הא כאן •• הוא במילוי אל״ף — אף דבשרה י״ל שהוא במילוי ה׳ (שאז ה״ז בגימטריא י׳ שנטלה)."],["25","25","במדרש שמואל כאן (מרשב״ם בשם ר״י בן הרא״ש), שנקרא כן כדי להסתירו מן המלשינים (ובמח״ז שם: ולא רצה לפרסום וכינה המסדר בלשון הצנע ובלשון נקי׳). אבל מכיון שכל הענינים שבתורה — כולל גם השמות של בעלי המאמרים — הם נצחיים, מובן שהנוגע לתוכן מאמרו, כבפנים, וראה לקמן הערה 79. ובפרט שלכאורה אין להזכיר לגר שגר הוא (ובפרט ב(סיום) מס׳ דמילי דחסידותא — אבות)."],["26","26","וראה לקמן סעיף ו ובהערה 47. •26) ומה שהצער גופא הו״ע של שבח (כנ״ל ס״ב) — ראה לקמן ס״ד. •) ובמלאכת שלמה כאן כתב דהי׳ (זה דחגיגה) אמורא. וביוחסין ע׳ בן הא הא מסתפק (בהנ״ל) אם הי׳ תנא או אמורא. וראה שם ע׳ היהי. ובדק״ס חגיגה שם. ••) אבל בחגיגה שם במילוי יו״ד. — להעיר דשינוי המילוי הוא באותיות אי״ה (ראה יהל אור ע׳ קסה). וראה ענין המילואים בס׳ אתהלך ליאונא (ובביאור ר״צ״צ לשם — אוה״ת ענינים ע׳ רמ ואילך). ואכ״מ."],["27","27","להעיר מסוג המצות שאין „אדם חייב להשתדל ולרדוף עד שיעשה אותה .. שאינה חובה אלא דומין לרשות״ (רמב״ם הל׳ ברכות פי״א הי״ב). •27) ראה לקמן בפנים ס״ד (ובהערות) סי״ו."],["28","28","שו״ע חו״מ ססע״ה ס״ג ובסמ״ע שם סק״ז."],["29","29","ויתירה מזו, שהוה כיורד ברשות — שבזה לכו״ע (גם לדעת הרא״ש ב״מ פ״ח סכ״ב. הובא בטור שם) נוטל גם ההוצאה שיתירה על השבח."]]],[1300171402,"זיין נעמען אויף זיך דעם צער (סתם, ניט אויסטייטשנדיק אז דאס איז „בלי נדר״)²⁹• איז ווי א „פשיעה״, עס איז גורם דעם שפעטערדיקן הפסד³⁰ —\n[און עאכו״כ ביי גר שנתגייר וואס איז דערנאך ניט מקיים די מצות ווי מ׳דארף, איז זיין גיור אזוי ווי א פשיעה. ווארום וויבאלד אז „קשים גרים לישראל כספחת״³¹ דערפאר וואס „אין בקיאין בדקדוקי מצות וישראל למדין ממעשי־ הם״³² — און על פי דין דארף מען פריער באווארענען און ווארענען דעם גר וואס וויל זיך מגייר זיין: „מה ראית שבאת להתגייר וכו׳ דאי פריש נפרוש כו׳״³³ — און היות אז ער האט זיך פארט מגייר געווען ניט פארטראכנדיק וועגן די שוועריקייט וואס דערפון ארויסקומען (ניט צו מקיים די מצות בדקדוקיהן) איז עס אזוי ווי א „פשיעה״] —\nדעריבער, ווען ניט דער חידוש „לפום צערא אגרא״ וואלט מען געקענט אננעמען, אז ער באקומט ניט קיין שכר פאר דעם „צער״ — ע״ד ווי א פועל וואס האט זיך אונטערגענומען איבער־ צופירן „חבית ממקום למקום״ און זיי זיינען צעבראכן געווארן צוליב זיין פשיעה (צוליב דעם וואס ער האט זיי געפירט אויף א מקולקל׳דיקן וועג, וכיו״ב), וואס דער דין איז, אז דער בעה״ב דארף אים ניט באצאלן פאר דער ארבעט [און אדרבה: דער פועל דארף באצאלן פאר די צעבראכענע חביות]³⁴;\nאיז דער אויפטו פון „לפום צערא אגרא״, אז אויך ווען דער אנגענומענער „צער״ האט גורם געווען א הפסד (כביכול) צום בעה״ב (הקב״ה)³⁵, אעפ״כ גיט מען אים שכר פאר דעם „צער״ און טרחא לפנים משורת הדין³⁵•; און אזוי ווי ביים דערמאנטן פאל פון דעם וואס איז „מעביר חביות ממקום למקום״, אז (אויב ער האט ניט וואס צו עסן³⁶) מצוה",[["","","•29) ראה לקמן הערה 35."],["30","30","וכמו מי שקבל ע״ע מינוי וכיו״ב (שאינו מחויב בזה) וזה גרם ע״ד יומא (פו, א) „היכי דמי חילול השם אמר רב כגון אנא אי שקילנא בישרא מטבחא ולא יהיבנא דמי לאלתר״."],["31","31","יבמות מז, ב. וש״נ."],["32","32","תוד״ה קשים (וראה רש״י שם ד״ה דאמר), וכ״ה ברש״י שם קט, ב."],["33","33","יבמות שם."],["34","34","ב״מ פג, א. שו״ע חו״מ רסש״ד."],["35","35","ובפנימיות הענינים י״ל שההפסד שנגרם לבעה״ב הוא לא רק במקרים מסויימים (שאינו מקיים את ההידור כדבעי ולא התנה בל״נ) כ״א בכל אופן. כי מכיון „שלפי אמיתת עוצם גדולתו ורוממותו גם העבודה האמיתית היא כלא ממש ואדרבה לחטא יחשב כו׳״ (ד״ה החלצו תרנ״ט פי״ג, עיי״ש בארוכה. ועד״ז בד״ה ויכנעו עמי תרנ״א), הרי (בשלמא במצות שנצטוו אזי ההפסד שנגרם לא בא ע״י פשיעתו כיון שנצטוה בקיום התום״צ, אבל) כשמקבל ע״ע הידור וכיו״ב שלא נתחייב בו, הרי נמצא שההפסד (שעבודתו הוא לא כדבעי למעבד (כתובות סו, א) לגבי עוצם גדולתו, ויתירה מזו, כנ״ל) בא ע״י פשיעתו, והיציאה היא יתירה על השבח. •35) ועפ״ז מתורץ ג״כ מאי נפק״מ — בהנהגת האדם — הא דלפום צערא אגרא, דלכאורה דוחק לומר שזהו רק בכדי לזרזו בקיום התום״צ (ובפרט שבהתחלת המס׳ (משנה ג׳) מפורש „אל תהיו כעבדים המשמשין את הרב ע״מ לקבל פרס כו׳״, ולאחרי (קיום) הוראה זו וכל ההוראות עד לסיום המס׳, יזרזו את האדם לקיום התום״צ (גם כשיהי׳ קשור עם צער) ע״י ההודעה שיגיע לו שכר גם עבור הצער!) — כי (נוסף ע״ז ש״ל שמודגש הנהגה ד„מידת חסידות״ — לפנים משורת הדין — של הקב״ה והדבק בדרכיו, הנה) בזה מודיע שגם קבלת צער כזה שאפשר שיבוא מזה הפסד כו׳ ניחא לי׳ להקב״ה, כדלקמן סעיף ה׳."],["36","36","בב״ח שם, שהכוונה ב„אין לו מה יאכל״ היא שאין לו „כדי סעודת היום״ [וצ״ע אם זהו לד״ה — מכיון שלא הוזכר זה בשאר פוסקים]. ובנדו״ד יש לומר, שמלא עומסו של הקב״ה שיתן לכל צדיק בה״ש עולמות (סנהד׳ ק, סע״א. רש״י שם) — זה נעשה „סעודת היום״ של האדם."]]],[1300171403,"היא לעשות לו לפנים משורת הדין וליתן לו שכרו״³⁷.\nה. און הגם אז דער דין („מצוה היא לעשות לו לפנים משורת הדין וליתן לו שכרו״) איז געזאגט געווארן דוקא ווען דער בעה״ב האט געדונגען דעם פועל איבערצופירן די חביות — און בנדו״ד טוט ער דאך דעם גיור וההידור והנהגה טובה מדעת עצמו — וויבאלד אבער דעם בעה״ב איז ניחא דעם פועל׳ס ארבעט בכלל, איז אויך ווען ער האט פושע געווען אין איין פרט\n[לדוגמא, אז איבערפירנדיק די חביות „במקום רעוע״³⁷• האט זיך צעבראכן נאר איין חבית און דער ריוח פון די איבערגעפירטע חביות איז מער פונעם הפסד פון דער איינציקער צעבראכע־ נער חבית, וואס דאן איז דעם בעה״ב ניחא די פעולה פון איבערפירן די חביות (ער איז נאר ניט צופרידן פון דעם אופן ווי ער האט דאס געטאן)],\nדארף דער בעה״ב מצד מדת חסידות אים געבן דעם פולן שכר פאר זיין ארבעט (אויך פארן איבערפירן די חבית וועלכע האט זיך צעבראכן). ווארום היות דעם בעה״ב איז ניחא די פעולה בכלל, איז עס כאילו ער וואלט אים געדונגען אויף דעם³⁸.\nאון דעריבער איז אויך אזוי בנדו״ד, אז וויבאלד דעם בעה״ב (דעם אויבערשטן) איז ניחא דאס וואס דער אדם נעמט אויף זיך³⁹ די טירחא און צער פון א הידור מצוה וכו׳ (ס׳איז נאר וואס דער אופן פון זיין אננעמען אויף זיך איז ניט כראוי. און צו מתנה זיין „בלי נדר״⁴⁰, גיט ער דעם גאנצן שכר פאר דעם צער — „לפום צערא אגרא״.\nאון עד״ז איז ביי גר שנתגייר: היות אז דער עצם גיור איז א דבר הרצוי ביים בעה״ב (ביים אויבערשטן)⁴¹, איז הגם אז ס׳איז דערנאך געווען ביי אים א „פשיעה״ אין דעם וואס ער איז ניט מקיים די מצות מיט אלע דקדוקים, באקומט ער שכר פאר זיין גיור⁴² (כאטש דאס האט גורם געווען א הפסד)⁴³.",[["37","37","טור שם (מב״מ שם). סמ״ע שם. שו״ע אדה״ז הל׳ שאלה ושכירות סי״ט. והא דאיתא בב״מ שם שרבה בר בר חנן סבר שאינו צריך לשלם שכר, וגם רב לא הביא לו ראי׳ (שצריך לתת שכר) מהא דאבות — הוא לפי שמנהג הקב״ה, אין מוכרח כלל שמחוייב בזה בן אדם בכל פרטיו ממש [וע״ד מרז״ל (ויק״ר פכ״ז, ב) עה״פ (איוב מא, ג) מי הקדימני ואשלם]. ובפרט שההנהגה ד„לפום צערא אגרא״ היא חידוש, גם לגבי מסקנת הגמרא (בב״מ שם), כבהערה 38. •37) ל׳ שו״ע אדה״ז שם."],["38","38","אלא שאעפ״כ, אין זה דומה ממש לשוכר את הפועל — שלכן היא רק מידת חסידות [משא״כ בשוכר את הפועל, מצוה הוא לעשות לו לפנים משורת הדין, ועד שכופין על זה (ב״ח שם)]. ועפ״ז מובן החידוש שב„לפום צערא אגרא״ על הדין ד„ארחות צדיקים תשמור״ שבב״מ שם. וראה הערה 43. ועצ״ע."],["39","39","להעיר מתוד״ה ואתה — שבת פז, א."],["40","40","וגם לפי הנ״ל הערה 35, הרי ניחא לי׳ לבעה״ב (הקב״ה) עצם הענין שמקבל ע״ע הידור וכו׳ נוסף, וההפסד הוא רק באופן עבודתו, כנ״ל."],["41","41","וכמ״ש (רות ב, יב): ישלם ה׳ פעלך ותהי משכורתך שלמה גו׳ אשר באת לחסות תחת כנפיו, ובמד״ר שם (איר חסא) מפרש ד„אשר באת לחסות תחת כנפיו״ הוא „פעלך״ שע״ז „ישלם ה׳ פעלך״. וראה יתירה מזו יבמות (מח, סע״ב) מפני מה גרים בזה״ז מעונין ויסורין באין עליהן כו׳ מפני ששהו עצמם להכנס תחת כנפי השכינה אר״א כו׳ מאי קראה ישלם ה׳ פעלך גו׳ אשר באת גו׳. ראה רש״י ותוס׳ וחדא״ג שם. וראה הערה הבאה."],["42","42","והחידוש דבן הא הא על הפסוק דרות לפי׳ המדרש — פשוט, שהרי שם אין מפורש כלל ענין דצער בקיום תום״צ, ופשטות הכתוב מדבר בענין אחר לגמרי."],["43","43","ועפ״ז מובן עוד יותר החידוש שבהנהגת הקב״ה „לפום צערא אגרא״ — גם על ה„מדת חסידות״ דנתינת שכר על פעולת העברת החביות כשניחא לי׳ לבעה״ב בכללות הפעולה (ראה לעיל"]]],[1300171404,"ו. ויש לומר, אז דאס וואס דער בעל המאמר פון „לפום צערא אגרא״ ווערט דא אנגערופן מיטן כינוי „בן הא הא״ אויף צו מדגיש זיין אז ער איז א גר, כנ״ל — הגם אויך ביי א (געבוירענעם) איד איז שייך אזא ענין אז ער זאל אויף זיך אננעמען א צער וטורח (בתום״צ) וואס ער איז ניט מחויב על פי דין — איז עס דערפאר ווייל דוקא ביי גירות איז דא א קבלת צער אין וועלכן מ׳איז אינגאנצן ניט מחויב⁴⁴.\nדי הסברה אין דעם:\nדי גאנצע בריאה פון א אידן איז „לשמש את קונו״⁴⁵. איז דערפון מובן, אז מען דארף אויסנוצן אלע זיינע כוחות אויף דעם שימוש — עבודת ה׳, ביז ווי רז״ל זאגן⁴⁶, אז יעדער איד איז „חייב לומר מתי יגיעו מעשי למעשה אבותי אברהם יצחק ויעקב״. דעריבער איז ביי א אידן שווער צו געפינען א טרחא און צער אין עבודת ה׳ אין וועלכן ער איז כלל ניט מחויב. ווארום ענינים אויך ווי פון לפנים משורת הדין און מילי דחסידותא זיינען סוף־סוף ניט קיין זאכן וואס א איד איז פטור פון זיי, וויבאלד ער איז מחויב „לשמש את קונו״ מיט אלע זיינע כוחות.\nמשא״כ א גר שנתגייר איז פאר זיין גירות איז אויף אים כלל ניט חל קיין חיוב זיך צו מגייר זיין (און אדרבה: גר שבא להתגייר אומרים לו מה ראית שבאת להתגייר כו׳³³), אזוי אז די קבלת צער דורך גירות אויף צו מקיים זיין תום״צ איז אין אזא אופן וואס ער איז אין דעם כלל ניט מחויב⁴⁷.\nפונדעסטוועגן ווערט דער ענין („לפום צערא אגרא״) געבראכט אין מס׳ אבות וואס איז שייך צו אלע אידן (און ניט נאר צו גרים), ווייל אויך ווען א איד נעמט אויף זיך א תוספת צער אין תום״צ אין וועלכן ער איז ניט מחויב ע״פ דין — ובפרט ווען דאס איז ניט לויט זיין טבע ורגילות ביז אז צוליב דעם (צער און שינוי הרגילות) איז דאס ע״ד ווי ער נעמט אויף זיך אינגאנצן א נייע זאך — איז עס בדוגמא צו גר שנתגייר⁴⁸.",[["","","בפנים ובהערה 38) — כי מכיון שאין שייך גיור לחצאין, הרי נמצא שכל פעולת הגיור הוה (אח״כ) כמו „פשיעה״ — ובפרט את״ל שגיור הוא פעולה נמשכת — (ודלא כבהעברת החביות, שהפשיעה היא רק באופן העברתם, בזה שהעביר אותם במקום רעוע); ואעפ״כ, מכיון שהגיור מצד עצמו ניחא לי׳ לבעה״ב — נותן לו שכרו על זה."],["44","44","ונוסף לזה: גם החידוש ד„לפום צערא אגרא״ הוא בעיקר בגר שנתגייר — ראה הערה הקודמת."],["45","45","סוף מס׳ קידושין."],["46","46","תדבא״ר רפכ״ה."],["47","47","עוד ענין בהשייכות לגר דוקא: עבודתו של גר בכל המצוות שמקיים היא ע״י שקיבל ע״ע (כשנתגייר) „צער״ שלא נתחייב בו. ואפילו ז׳ מצות ב״נ שהי׳ מחויב בהם גם לפני הגיור — הרי מובן שאינו דומה כלל הציווי וקיומו בתור ב״נ, או בתור בנ״י אשר הוצאתיך מארמ״צ ע״מ כן שישמרו התום״צ (תו״כ (הובא בפרש״י) שמיני יא, מה. פרש״י בהר כה, לח. ספרי (ופרש״י) שלח טו, מא. ועוד). ולהעיר שב״נ בז״מ דילי׳ „אין מקבלין עליהם שכר כמצווה ועושה אלא כמי שאינו מצווה ועושה״ (ע״ז ג, א), והיצה״ר מתגבר (יותר) על המצווה (יותר) להחטיאו (תוד״ה גדול שם (בגירסת העץ). וראה ט״ז יו״ד סרמ״ו סק״ג. ש״ך שם סק״ז) — נמצא, שע״י הגיור מתווסף לו „צער״ גם בקיום ז׳ מצות אלו. משא״כ בישראל שרק בפרט זה ד„צער״ נוסף שמקבל עליו הוה כמו גר, כבפנים."],["48","48","עפכהנ״ל תומתק שייכות המאמר בחגיגה (ט, ב): ושבתם וראיתם כו׳ בין עובד אלקים לאשר לא עבדו כו׳ ואינו דומה שונה פרקו מאה פעמים לשונה פרקו מאה ואחד, ל„בר הי׳ הי׳״, כי מצד „זאת הפעם המאה ואחת היתרה על הרגילות שהורגל מנעוריו״ (לשון התניא פט״ו — כא, א — בביאור מרז״ל הנ״ל) הוא אצלו כדבר חדש לגמרי ולכן הוא כגר שנתגייר בזה שמשנה טבע הרגילות שלו."]]],[1300171405,"נאכמער: די משנה („לפום צערא אגרא״) שטייט (לויט כמה גירסאות⁴⁹) דוקא בסיום (המשניות⁵⁰ פון) מס׳ אבות⁵¹, וואס דאס מיינט אז דאס איז די העכסטע מעלה אין „מילי דחסידותא״, וכנ״ל, ווייל אין דער משנה רעדט זיך וועגן אזא קבלת צער וואס איז אינגאנצן ניט לויט זיין טבע ורגילות און מהאי טעמא איז דאס א דרגא הכי נעלית אין מדת חסידות.\nז. והנה, אויף דעם וואס האט זיך פריער גערעדט (סעיף א׳), אז דער שכר פון מצות איז א חיוב ע״פ הלכה (אז על פי דין תורה דארף א איד קריגן שכר פאר זיין עבודה פון תום״צ), קען מען פרעגן:\nדער גדר החיוב ביי מענטשן צו באצאלן א פועל פאר זיין ארבעט (א שכיר יום, א קבלן וכיו״ב) איז דוקא ביי אזא וואס האט ניט אויף זיך קיין חיוב צו ארבעטן פארן בעה״ב און זיין מלאכה איז צוליבן שכר. משא״כ אן עבד וואס האט אויף זיך די התחייבות לשמש את רבו דערפאר וואס ער איז קנוי צו אים; און עד״ז ביי א בן וואס איז מחויב צו באדינען זיין פאטער צוליב דער מצוה וחיוב פון כבוד אב⁵² — איז ביי זיי ניטא דער גדר פון באצאלן שכר פאר זייער שימוש און עבודה⁵³.\nהיינט וויבאלד אז די שייכות פון אידן צום אויבערשטן איז „אם כבנים אם כעבדים״; און נאכמער: די מטרה פון דעם אידנ׳ס באשאף איז „לשמש את קונו״, איז דאך מובן, אז דאס וואס א איד איז קנוי ומחויב „לשמש את קונו״ איז דאס (ע״פ הלכה) אין א פיל גרעסערער מאס ווי דער קנין און חיוב פון עבד לאדונו — און אוודאי מער ווי דער חיוב פון דעם בן צו זיין פאטער⁵⁴ — טא ווי קען מען זאגן אז",[["49","49","כ״ה בש״ס ומשניות. וכ״ה בדפוס ראשון דמשניות (נאפולי, רנב), כת״י קופמאן, כת״י תימני, כת״י פארמה (א׳), (ג׳). וראה שינויי נוסחאות למשניות. הוצאת קאפח. אבל בסדור אדה״ז ובכו״כ סדורים (ועוד) סיום הפרק הוא במשנה „הוא הי׳ אומר בן חמש שנים כו׳״. ראה שינויי נוסחאות למשנה כ׳. וראה לקמן הערה 51."],["50","50","שהרי פרק ו׳ הוא ברייתא. וראה מדרש שמואל רפ״י. ולהעיר שבמח״ז (שהובא בשינויי נוסחאות למשניות) המאמר לפום צערא אגרא (ומאמר בן בג בג) הוא בסוף פ״י."],["51","51","וגם להגירסא שמסיים במשנה „הוא הי׳ אומר בן חמש שנים כו׳״ — ראה מדרש שמואל במשנה הנ״ל, שאין אלו דברי ר״י בן תימא וגם אינם מסדר מסכתא זו • אלא שחכמים הסמיכום והוסיפום כאן. וראה מ״ש בריש משנה זו (הובא בתוי״ט). וראה שער הכולל פ״ל ס״ג. •) כדמוכח במשניות נוסחאת הרמב״ם וכת״י קופמאן, כת״י פארמה הנ״ל — שליתא שם משנת הוא הי׳ אומר בן חמש שנים כו׳."],["52","52","רמב״ם הל׳ ממרים פ״ו ה״ג. טושו״ע יו״ד סר״מ ס״ה."],["53","53","שהרי בעבד כנעני קיי״ל דיכול הרב לומר לו עשה עמי ואיני זנך (רמב״ם הל׳ עבדים פ״ט ה״ז. טושו״ע יו״ד סרס״ז ס״ג. וגם בעבד עברי שחייב האדון להשוותו לו במאכל ובמשקה בכסות ובמדור (רמב״ם שם פ״א ה״ט) וגם חייב במזונות אשתו ובניו ובנותיו (שם רפ״ג) — ה״ז גדר בחיובי אדון לעבד (עברי) — שהוא כקנהו אדון לעצמו (קדושין כ, א) — ולא בתור שכר פעולה. ועצ״ע."],["54","54","וכדמוכח גם מהחיוב דמס״נ על קדה״ש — ודלא כבן שאינו מחוייב למסור נפשו עבור אביו, שהרי חייך קודמים (ב״מ סב, א) ועד שאבידתו ואבידת אביו אבידתו קודמת (שם לג, א). אבל להעיר מלקו״ת ר״ה סב, ד: וזה (מה שבן אינו מחויב למסור נפשו עבור אביו, זהו) מחמת שהוא נהי׳ מהות בפ״ע, אך הנשמה אינה כך רק כולא חד ואינה נפרדת ממנו ית׳ כלל — שמזה משמע, שהחיוב דמס״נ על קדה״ש הוא גם מצד זה שבנ״י הם בנים להקב״ה (מכיון שאינם נפרדים). ועיין תניא ספכ״ד: אפי׳ בעבירה קלה כו׳ גזירת הכתוב הוא (דלכאורה משמע דגזה״כ הוא ביהרג ואל יעבור — אף שי״ל דיעבור פ״א כדי שישמור פעמים הרבה). ואכ״מ."]]],[1300171406,"דעם אידן קומט (ע״פ דין) א שכר⁵⁵ פאר זיין דינען דעם אויבערשטן⁵⁶?\nח. איז דער ביאור אין דעם:\nוויבאלד תורה ומצות זיינען געגעבן געווארן פון דעם אויבערשטן צו אידן, איז מובן אז אין זיי זיינען פאראן גדרים מצד דעם נותן (דעם אויבערשטן), און גדרים מצד דעם מקבל (אידן)⁵⁷.\nאון דעריבער געפינט מען אין דער תורה צוויי קצוות: „אין דברי תורה מקבלין טומאה״ — ווען עס לערנט זיי א איד וואס איז ניט טהור — ווייל זיי זיינען „דברי (כאש)״⁵⁸: דעם אוי־ בערשטנ׳ס רייד; און פונדעסטוועגן איז „רב שמחל על כבודו כבודו מחול״, דערפאר וואס די „תורה דילי׳ היא״⁵⁹ (ס׳איז (ווי) דעם רב׳ס תורה). ד.ה. אין געוויסע ענינים איז די תורה געבליבן אין דער „בעלות״ פון דעם אויבערשטן, און אין אנדערע פרטים איז זי איבערגעגעבן געווארן צו דעם מקבל, צום אידן.\nאון אזוי ווי דאס איז בנוגע תורה ומצות גופא, עד״ז איז עס אויך בשייכות דעם חיוב צו לערנען תורה און מקיים זיין מצות, אז אין דעם זיינען פאראן די צוויי גדרים:\nמצד דעם גדר הנותן איז דא אויפן אידן א חיוב צו מקיים זיין תום״צ אינעם אופן ווי דער חיוב השימוש פון א בן לאביו און אן עבד לרבו; און מצד דעם גדר המקבל איז זיין עסק אין תורה ומצות אין אזא סוג חיוב וואס איז (ע״פ תורה)⁵⁶ פארבונדן מיט קבלת שכר⁶⁰, אזוי ווי א קבלן ושכיר⁶¹.\n[די צוויי היפך׳דיקע גדרים אין דעם חיוב פון קיום התום״צ, זאגן זיך ארויס (אויך) אין דעם חילוק צווישן די צוויי סוגי מצוות — די מצות (ע״ז ג״ע ושפ״ד) וואס ביי זיי איז „יהרג ואל יעבור״ און די אנדערע מצות, אויף וועלכע ס׳ווערט געזאגט „אשר יעשה אותם האדם וחי בהם, וחי בהם ולא שימות בהם״⁶²:\nביי די מצות איז מודגש זייער גדר החיוב מצד דעם מקבל, און דעריבער איז ביי זיי נוגע דער מקבל — ויתרה מזו — זיי מאכן אויף דעם מקבל — כמחז״ל אז בכדי עס זאל זיין „לשמש את קוני״ איז „נבראתי״ — „וחי בהם״⁶³; משא״כ אין די דריי ענינים (מצות) הנ״ל, איז זייער עיקר⁶⁴ גדר החיוב מצד הנותן, דערפאר⁶⁵ איז ביי זיי ניטא די",[["55","55","להעיר מאבות פ״א מ״ג: אל תהיו כעבדים כו׳ ע״מ לקבל פרס כו׳. ובתוי״ט שם: שגם העובדים להפרע לקבל שכר הוא קורא אותם עבדים כו׳, עיי״ש."],["56","56","להעיר מחסדי אבות (להחידא״א) כאן."],["57","57","ראה בארוכה הדרן הא׳ על מס׳ פסחים (נדפס בהגש״פ עם לקוטי טעמים מנהגים וביאורים (קה״ת, תשמ״ו־ז) ע׳ תסד ואילך). וראה שם כו״כ דוגמאות לזה."],["58","58","ברכות כב, א."],["59","59","קדושין לב, סע״א ואילך."],["60","60","ושני ענינים בזה: א) בכוונת האדם — דמכיון שהעבודה מאהבה „היא מעלה גדולה מאד ואין כל חכם זוכה לזה״ (רמב״ם הל׳ תשובה פ״י ה״ב), לכן העבודה ברוב בנ״א, ובפרט בקטנים כו׳ היא „כדי לקבל שכר״ (ראה רמב״ם שם ה״ה). ב) שהקב״ה מחויב (כביכול) לתת שכר לאדם עבור עבודתו (גם כשעבודתו היא שלא ע״מ לקבל פרס), בדוגמת החיוב דשכר שכיר."],["61","61","להעיר שבנוגע לישראל בזה״ג אומרים (ברכות ג, א) אב שהגלה את בניו .. לבנים שגלו מעל שלחן אביהם."],["62","62","אחרי יח, ה. סנהדרין עד, א וברש״י שם. רמב״ם הל׳ יסודי התורה רפ״ה."],["63","63","ועפ״ז יומתק אמרו ברמב״ם פעם ב׳ „וחי בהם״."],["64","64","אבל פשיטא שיש בהם גם גדר המקבל ולכן גם הן בכלל ד(נבראתי) לשמש את קוני. וי״ל דלכן אינו מחויב עונש אם עבר (רמב״ם שם הי״ד)."],["65","65","אבל להעיר מלקו״ת שבהערה 54."]]],[1300171407,"זאך פון „יעבור״ — „יהרג ואל יעבור״].\nט. דער ענין הנ״ל אינעם שכר פון תום״צ, אז דאס איז מצד די גדרים פון מקבל, איז נאכמער מודגש אין דעם, וואס דער אופן השכר איז „לפום צערא״, אויף ווי פיל דער מקבל האט אין דעם געהאט צער און טרחא.\nאון דערמיט קומט צו א ביאור נוסף אין דער שייכות פונעם מאמר „לפום צערא אגרא״ צו מסכת אבות — מילי דחסידותא:\nדער מושג פון „מילי דחסידותא״ (לפנים משורת הדין) איז מתאים נאר מצד המקבל. משא״כ מצד הנותן אז כל תכליתו פון דעם אדם איז נאר „לשמש את קונו״, איז ניטא קיין הגבלה אין זיין חיוב צו דינען דעם אויבערשטן (ביז, כנ״ל סוף ס״ז, אז ער איז דערפאר מחויב זיך מוסר נפש זיין) און במילא איז אויך ניט שייך די הגדרה פון „לפנים משורת הדין״⁶⁶.\nאון דאס גיט (נאך⁶⁷) א הסברה וואס מס׳ אבות הויבט זיך אן מיטן לשון „משה קבל תורה מסיני״ (און ניט אז „הקב״ה נתן תורה למשה בסיני״ וכיו״ב), ווארום דער ענין פון „מילי דחסידותא״ (דער תוכן פון מס׳ אבות) איז שייך נאר אין פארבינדונג מיט „קבל״, מיט גדר המקבל פון תום״צ:\nאון נעוץ תחילתה בסופה⁶⁸ — דער־ פאר איז אויך דער סיום פון (די משניות פון) מס׳ אבות בענין השכר⁶⁹ — און אין דעם גופא דער ענין פון „לפום צערא אגרא״ — וואס דאס איז מצד גדר המקבל, כנ״ל.\nיו״ד. דאס וואס אין „לפום צערא אגרא״ דריקט זיך אויס „גדר המקבל״ איז דאס ניט נאר אין דעם, וואס דער שכר („אגרא״) איז לויטן ערך פונעם צער וטרחא („לפום צערא״), נאר אויך אין דעם „צערא״ גופא, אין דעם אופן הצער והטרחא.\nוויבאלד אז דא רעדט זיך (כנ״ל ס״ג) וועגן א צער אין עבודת התום״צ וואס דער מענטש איז אין דעם ניט מחויב ע״פ דין, נאר ער איז דאס אויף זיך מקבל אינגאנצן מיט זיין אייגענעם ווילן — אין דער דוגמא ווי די קבלת המצות (צער) פון א גר, וואס קומט אינגאנצן פון זיין אייגענער בחירה און רצון (ניט האבנדיק קיין חיוב מגייר זיין זיך, כנ״ל) — קומט אויס, אז דער „צערא״ בעבודת התום״צ (צי ביים כללות המצות ביי א גר, אדער⁷⁰ א מילתא דחסידותא וכיו״ב ביי א אידן)•⁷⁰ גע־ הערט אינגאנצן צו דעם אדם⁷¹.",[["66","66","להעיר מהמבואר בההדרן על מס׳ פסחים (שבהערה 57) בפלוגתת ר״י ור״ע (סוטה ג, א) בכו״כ ענינים שבתורה, אם הם „רשות״ או „חובה״ — שפלוגתא זו היא חלק ופרט משיטתם הכללית בגדרי התום״צ, אם הם (בעיקר) בגדרי הנותן או בגדרי המקבל: שיטת ר״י היא שהתום״צ הם (בעיקר) בגדרי המקבל, ולכן ס״ל שכל ענין שבתורה (כאם אין הכרח לפרשו שהוא „חובה״) ניתן ל„בעלותו״ של האדם — „רשות״; ושיטת ר״ע היא שהתום״צ הם (בעיקר) בגדרי הנותן, ולכן ס״ל שכל ענין שבתורה נשאר ב„בעלותו״ של הקב״ה ולא נמסר לבעלות האדם — „חובה״."],["67","67","ראה מדרש שמואל ריש מס׳ אבות, טעמים על מה ש„ייחס הענין אל המקבל״ ולא אל הנותן (כמו „ומסרה ליהושע ויהושע לזקנים וכו׳״ שייחס אל הנותן)."],["68","68","ראה הדרן הנ״ל ס״ג (ובהערות שם), לעיל ע׳ 135 (שוה״ג להערה 31), דמה שפשט המנהג לקשר — ב„הדרן״ — סיום המסכת בהתחלתה הוא („לא בכדי לחדודי לבד וכיו״ב, כי אם) לפי שסיום מסכת יש לו שייכות עם התחלתה."],["69","69","ולהעיר שגם סיום ספר יד החזקה של הרמב״ם הוא בהשכר שיהי׳ לעתיד."],["70","70","אבל לא ממש — ראה לעיל ס״ו. •70) ולהעיר ממשנית לעיל ע׳ 325 ואילך."],["71","71","בההדרן על מס׳ פסחים (שבהערה 57), דזה מה שר״ע ס״ל שהתום״צ הן ב„בעלותו״ של הקב״ה"]]],[1300171408,"דערמיט קומט צו א הסברה נוספת אין דעם קישור פון סיום מס׳ אבות מיט איר אנהויב⁶⁸ (אין צוגאב צו דעם וואס ס׳האט זיך גערעדט אין סעיף ט׳), ווייל אויך ביי קבלת התורה, ווען „משה קבל תורה מסיני״ (וואס אינעם לשון „קבל״ איז מודגש דער גדר המקבל ועניינו, כנ״ל שם), זיינען אלע אידן געווען גרים⁷².\nיא. ע״פ כהנ״ל וועט אויך פאר־ שטאנדיק ווערן די שייכות פון דעם מאמר „בן הא הא אומר לפום צערא אגרא״ צום מאמר וואס שטייט גלייך פאר דעם: „בן בג בג אומר הפך בה והפך בה כו׳״ [ביז אז לויט כמה גיר־ סאות⁷³ זיינען ביידע מאמרים איין משנה]:\nאויך בן בג בג איז געווען א גר (אדער א בן גרים⁷⁴). און כשם ווי דער כינוי „בן הא הא״ איז מרמז (כנ״ל ס״ג) אז ער איז געווען א גר — „בן אברהם ושרה שנתוספה ה״א בשמם״, אזוי איז אויף דעם מרמז אויך דער כינוי „בן בג בג״, ווייל „בג בג״ איז בגימטריא ה׳ ה׳⁷⁵ [און אויך איז עס מרומז אין נוטריקון פון „בג בג״⁷⁶: „בן גר בן גיורת״⁷⁷].\nאון מצד דעם זעלבן טעם (ווי כנ״ל בנוגע „בן הא הא״) ווערט דער בעל־ המאמר אויך דא אנגערופן (ניט מיט זיין",[["","","(כנ״ל הערה 66) הוא לפי שר״ע הי׳ בן גרים (ראה סה״ד בערכו), והגרים מתייחסים בעיקר לא „לאברהם יצחק ויעקב (ישראל) כ״א למי שאמר והי׳ העולם״ (תשובת הרמב״ם לר׳ עובדי׳ הגר — תשובות הרמב״ם (ירושלים תשכ״ג כרך ב׳ סרצ״ג. רמב״ם הוצאת שולזינגר — נ.י. תש״ז — סוף כרך א סי״ט)). אבל אין מזה סתירה למ״ש בפנים — כי מ״ש כאן הוא בנוגע למעשה הגיור, וזה נמסר לבעלותו של האדם: משא״כ מה שהגרים מתייחסים „למי שאמר והי׳ העולם״ הוא לאחר שנתגיירו •."],["72","72","ראה יבמות מו, א־ב. כריתות ט, א."],["73","73","וכ״ה במס׳ אבות שבסידור אדה״ז. •) וי״ל שב׳ ענינים אלו תלויים זה בזה: כי מכיון שהמסירה לרצון הקב״ה (קבלת המצוות) שבגר באה מצד האדם — לכן, המסירה ונתינה שלו היא בתכלית, ולכן מתייחס הוא להקב״ה. וע״ד המבואר בהמשך תרס״ז (ע׳ שכב) המעלה ד„עבד פשוט״, דמכיון דזה שנותן את עצמו לעבד הוא „בכח עצמו״ — לכן המסירה ונתינה שלו היא באופן ש„מציאותו הוא רק מציאות האדון״. ע״ש בארוכה."],["74","74","ראה בהמצויין בהערה הבאה — שהי׳ גר. אבל לפי הפירוש (המובא לקמן בפנים) ש„בג בג״ הוא נוטריקון „בן גר בן גיורת״ — הי׳ בן גרים. וגם הלשונות (במקומות שבהערה הבאה) „גר הי׳״ „גרים היו״ י״ל שהיו בני גרים (והרי גם במד״ש בשם י״א (שהובא בהערה 77) שהפירוש שהוא נוטריקון בן גר בן גיורת, כתב „וגר הי׳״). ובסה״ד (שהובא בהערה שם) הביא מתוס׳ חגיגה (ט, ב) „וכ״נ בתוס׳ חגיגה פ״ק בן בג בג ובן הא הא היו בני גרים (ע״ש) ולא כתבו כו׳״), ובכבס״מ שגם בן גר וגיורת עד כמה דורות נק׳ „גר״ — ראה רמב״ם הל׳ איסורי ביאה פט״ו ה״ח, ובכ״מ (ראה אנציקלופדיא תלמודית בערכו, וש״נ)."],["75","75","תוס׳ חגיגה שם. מדרש שמואל כאן מהרשב״ם בשם הר״י בן הרא״ש. מח״ז בפי׳ הב׳. ובפי׳ הא׳: וב״ג עולה ה׳ כלומר בן אברהם שיש בו ה׳ אותיות."],["76","76","י״ג (ראה פיה״מ להרמב״ם הוצאת קאפח) „בן בגבג״ — בתיבה אחת, וכן „בן האהא״. וי״ל (לחדודי עכ״פ) הנפק״מ בין ב׳ הגירסאות — להפי׳ שהי׳ „בן גר בן גיורת״: כששניהם בתיבה אחת ה״ז מורה שהגירות הן של אביו („בן גר״) והן של אמו („בן גיורת״), הי׳ בדור אחד: משא״כ „בן בג בג״ בב׳ תיבות מורה שהגירות של אביו ושל אמו לא היו בדור אחד."],["77","77","סה״ד מע׳ בן בג בג. מדרש שמואל מר׳ יוסף ן׳ נחמיאש בשם „יש אומרים״. וקצת הכרח לזה י״ל, שאם נק׳ בן בג בג רק מטעם שהוא בגימטריא ה׳ או „בן אברהם שיש בו ה׳ אותיות״ (כנ״ל הערה 75), הי׳ אפשר לקרותו בצירוף ושם אחר שעולה ה׳ כמו „בן גב בג״ או „דא דא״ וכיו״ב. וראה אוה״ת לך (כרך ד) ס״ע תשכד. שער מאמרי רז״ל (להאריז״ל) לאבות כאן (הובא ונתבאר בהמשך תרס״ו ע׳ תיז ואילך)."]]],[1300171409,"נאמען, נאר) מיטן כינוי „בן בג־בג״ (וואס דייטעט אן אויף זיין גירות) — צו מרמז זיין אז דאס וואס דער בעל המאמר איז געווען א גר האט א שייכות צו זיין מאמר⁷⁸ „הפך בה והפך בה״⁷⁹:\nוויבאלד א בן־נח איז מחויב אין די שבע מצוות, איז מובן, אז אויף זיין לערנען תורה (די דינים ופרטים פון די ז׳ מצות) כאטש דאס איז אן ענין נעלה — ביז אז „נכרי ועוסק בתורה הרי הוא ככהן גדול״⁸⁰ — פונדעסטוועגן איז זיין עסק התורה ניט קיין מטרה פאר זיך נאר בלויז (ווי א „מיטל״) צו וויסן ווי אזוי צו מקיים זיין די מצוות, און ס׳האט ניט די מעלת הלימוד בתורה פון א אידן. דוקא ברגע ווען ער איז זיך מגייר און ווערט מחויב צו לערנען תורה אלס מצוה ותכלית פאר זיך, דעמאלט ווערט אין זיין לימוד התורה אויפגעטאן א שינוי עיקרי, עס ווערט אין דעם עילוי און מעלה נפלאה פון „הפך בה והפך בה דכולה בה״.\nאון דאס איז אויך די שייכות פון „בן בג בג״ צום מאמר „הפך בה והפך בה״ (ד.ה. אז דאס וואס ס׳האט ביי אים ארויסגערופן צו זאגן דעם מאמר איז דאס דערפאר) ווייל דער ציווי און דער עילוי בתורה פון „הפך בה והפך בה״ ווערט דערהערט ביי א גר באופן מיוחד.\nועפ״ז איז מובן דער קשר צווישן די צוויי מאמרים — „בן בג בג אומר הפך בה וכו׳״ און „בן הא הא אומר לפום צערא אגרא״: דער תוכן פון ביידע מאמרים האט א באזונדערע שייכות צו א גר.\nאון ס׳איז מדויק דער סדר פון די צוויי מאמרים — פריער דער מאמר „הפך בה כו׳״, וואס רעדט זיך וועגן לימוד התורה (תלמוד), און דערנאך דער מאמר „לפום צערא אגרא״, וואס דאס איז צער וטרחא בנוגע מעשה המצות — ווארום „תלמוד מביא לידי מעשה״⁸¹.\nיב. אלע ענינים אין תורה — אויך די נעמען פון די בעלי המאמרים — זיינען בתכלית הדיוק, איז דערפון פארשטאנ־ דיק, אז די שייכות פון די צוויי מאמרים („הפך בה כו׳״ און „לפום צערא כו׳״) צו די צוויי חכמים (בן בג בג און בן הא הא) איז ניט נאר א כללות׳דיקע, מצד דעם וואס זיי זיינען ביידע געווען גרים, נאר אז די צוויי באזונדערע שמות זיינען מרמז אויף די ענינים שונים פון די צוויי מאמרים.\n[א הוכחה אויף דעם: לויט איין דיעה⁸² זיינען „בן בג בג״ און „בן הא הא״ צוויי נעמען פון דעמזעלבן תנא. איז וויבאלד אז ביים מאמר „הפך בה״ ווערט ער אנגערופן „בן בג בג״ און ביי „לפום צערא״ — „בן הא הא״⁸³, מוז מען זאגן, אז דער אונטערשייד צווישן",[["78","78","ראה לקו״א להה״מ סי׳ עח."],["79","79","ועד״ז צריך לומר בכל המאמרים שהובאו בשמו של בן בג בג. משא״כ בקדושין (י, ב) שנק׳ „יוחנן בן בג בג״. ומזה (שנקרא גם בשמו — יוחנן) הוכחה (נוסף על מ״ש לעיל הערה 25) שבמקומות שמובא רק „בן בג בג״ — אינו (רק) בכדי „להסתירו מן המלשינים״ וכיו״ב."],["80","80","ב״ק לח, א. וש״נ."],["81","81","קדושין מ, ב. וש״נ."],["82","82","מד״ש כאן מר׳ יוסף ן׳ נחמיאש בשם „יש אומרים״. הובאה דיעה זו גם בסה״ד שם (אלא שלא ס״ל כן)."],["83","83","וגם להדיעות שהם ב׳ אנשים הרי הו״ל לקרוא הראשון (באם את״ל כן) בן הא הא שמורה בגילוי שהי׳ גר והשני בן בג בג שהוא רק גימטריא („כדי להכיר ולידע בין זה לזה״ — מד״ש שם מרשב״ם), כדלקמן בפנים ובהערה 85."]]],[1300171410,"די נעמען איז בהתאם צום חילוק בתוכן צווישן די צוויי מאמרים].\nדער הסבר אין דעם:\nאין דעם כינוי „בן הא הא״ (בעל המאמר „לפום צערא אגרא״) איז מער קענטיק דער אנדייט אויף א גר ווי אינעם כינוי „בן בג בג״: בלשון פון רשב״ם (בשם הר״י בן הרא״ש)⁸⁴: שבג בג (וואס איז נאר בגימטריא ה׳ ה׳) יותר נסתר ונעלם⁸⁵.\nאון עד״ז איז דער חילוק צווישן זייערע מאמרים: אין „הפך בה״ רעדט זיך וועגן אן ענין וואס איז „נסתר ונעלם״, און מען דארף אין עם מהפך זיין, און נאכאמאל מהפך זיין, משא״כ „צערא״ איז א גלוי׳דיקע זאך.\nוהביאור: „הפך בה והפך בה״ מיינט בעיקר (וכנ״ל סי״א) דעם עסק התורה אלס מטרה און תכלית פאר זיך (לערנענדיק צוליב פארשטיין און משיג זיין תורת ה׳ און ניט נאר צו „לדעת את המעשה״), איז מובן אז דאס נעמט ארום ניט נאר די עניני הלכה וואס זיינען נוגע למעשה (גלוי׳דיקע ענינים), נאר בעיקר דער לימוד פון שקו״ט וכדומה (וואס זיינען פריער און אויך נאך דער שקו״ט בלייבט אין זיי „נעלם״ און מ׳קען נאך ווייטער שקו״ט).\nאון ווי מפרשים⁸⁶ זיינען מסביר דעם פירוש פון „הפך בה והפך בה״: לפי שמצינו .. שהי׳ דורש מ״ט פנים טמא ומ״ט פנים טהור ואפי׳ שהיו אלו היפך אלו .. לכן אמר .. הפך בה והפך בה ודרוש דברים הפכיים זמ״ז פנים לטהר ופנים לטמא דכולא בה ואלו ואלו דא״ח⁸⁷.\nלויט דעם קומט אויס, אז דער אונטערשייד צווישן „לפום צערא אגרא״ און „הפך בה כו׳״, איז דער חילוק פון „גילוי״ און „העלם״: דער „צערא״ (אין תום״צ) וואס א איד איז אויף זיך מקבל, איז שייך בנוגע א באשטימטער (גלוי׳־ דיקער) זאך (א הנהגה, וכיו״ב)⁸⁸; משא״כ „הפך בה כו׳״, איז דער חידוש אין דעם וואס ער איז עוסק (אויך) אין דעם חלק פון תורה (שקו״ט דתורה, מ״ט פנים לכאן ומ״ט פנים לכאן) וואס די הוראות זיינען דארט „סתומות ולא מפורשות וגלויות וידועות״⁸⁹.\nאון דעריבער, כאטש אז אין ביידע מימרות איז מודגש דער ענין פון גר (וואס איז די נקודה פון ביידע מאמרים), איז אין דעם מאמר „הפך בה כו׳״ איז דאס אין דעם נאמען — באופן „נסתר",[["84","84","הובא במד״ש כאן."],["85","85","ועניין זה [ש„בג בג״ הוא „יותר נסתר ונעלם״] הוא גם להפירוש ש„בג בג״ הוא ר״ת „בן גר בן גיורת״. כי הה״א שנתוסף באברהם ושרה — שעל זה מורה השם „בן הא הא״ — מורה בגילוי על שייכותם לגרים (ראה לך לך יז, ה וברש״י שם. שם, טו וברש״י שם) משא״כ ענין הגיור ד„בג בג״ מרומז רק בהנוטריקון שלו (וראה אוה״ת שם). ונוסף לזה: השם „בן הא הא״ משמע שהוא עצמו הי׳ גר, משא״כ הנוטריקון ד„בג בג״ הוא (רק) „בן גר בן גיורת״ (וראה לעיל הערה 74)."],["86","86","מדרש שמואל כאן. וראה המשך תרס״ו (שבהערה 77) ושם לפנ״ז ע׳ תט ואילך)."],["87","87","עירובין יג, ב."],["88","88","ועד״ז במאמר בר הי׳ הי׳ בחגיגה (שבהערה 48), שהגם שנקט הדוגמא ד„עובד אלקים״ בלימוד התורה, הרי מדגיש לא העסק בחלק הסתום שבתורה כו׳ כ״א „שונה פרקו מאה (פעמים) ואחד״."],["89","89","לשון אדמו״ר הזקן באגה״ק סי׳ כט (קנא, א) — לענין תושב״כ. אבל מובן, שעד״ז הוא גם בתושבע״פ בחלק השקו״ט וכיו״ב דתושבע״פ. וכמובן גם ממה שמסיים באגה״ק שם במעלת השונה הלכות דוקא."]]],[1300171411,"ונעלם״, און אין דעם מאמר „לפום צערא אגרא״ — באופן גלוי⁹⁰.\n(משיחות יו״ד, י״ג וט״ו שבט תשל״ט)",[["90","90","ועד״ז הוא בהענין דגר דאפשרי בכאו״א, כנ״ל: במאמר לפום צערא אגרא הוא בגילוי, ואפ״ל תמיד בעבודתו דאופן דגר, בהנהגות שקיבל ע״ע באמירת בל״נ, ובפרט כשמזמן לזמן מוסיף ומקבל ע״ע הנהגות והידורים נוספים (להעיר מהנהגת כ״ק אדמו״ר (מהורש״ב) נ״ע (ספר המנהגים חב״ד ע׳ 56). והוראת כ״ק מו״ח אדמו״ר (לקו״ש ח״ב ע׳ 386)). משא״כ בהמאמר „הפך בה והפך בה כו׳״ שהענין דגר שבזה הוא „יותר נסתר ונעלם״ כי אינו ניכר בלימודו שלו כ״א רק כשנזכר ע״ד אופן לימודו קודם שנתגייר."]]],[1300171412,"<h3>פרק שישי</h3>\nא. „ר' מאיר אומר כל העוסק בתורה לשמה זוכה לדברים הרבה כו'“ — און ער רעכנט דערנאָך אויס אַ סך „דברים“1 צו וועלכע דער עוסק בתורה לשמה איז זוכה.\nדאַרף מען פאַרשטיין: וואָס פאַר אַ סוג אידן איז ר' מאיר אויסן מיט זיין הוראה — ממנ\"פ: רעדט ער וועגן אַ אידן וואָס זיין לערנען איז שוין לשמה, טאָ וואָס איז אים נוגע אַז ער וועט זוכה זיין צו „דברים הרבה“? ער לערנט דאָך „לשמה“, צוליב דער תורה אַליין, און ניט צוליב די „דברים“ צו וועלכע ער איז זוכה; און אויב ס'רעדט זיך וועגן אַ אידן וואָס האַלט נאָך ניט ביי לערנען תורה לשמה און די כוונה איז צו באַ־ווירקן עם ער זאָל לערנען תורה לשמה — וויבאַלד ער וועט לערנען בכדי צו דערגרייכן די „דברים הרבה“, וועט דאָך דאָס ווידער ניט זיין קיין לימוד לשמה?\nלכאורה וואָלט מען געקענט זאָגן, אַז דאָס איז ע\"ד ווי דער ביאור פון רמב\"ם2 אין דעם וואָס תורה איז מבטיח גשמיות'דיקן טוב אַלס שכר פאַר לימוד התורה און קיום המצות (כאָטש אַז לכאורה איז דאָס ניט בערך צו זיין אַ שכר פאַר תומ\"צ) — אַז דאָס איז בכדי אַ איד זאָל וויסן, „שאם נעשה אותה בשמחה ובטובת נפש כו' שיסיר ממנו כל הדברים המונעים אותנו מלעשותה כו' וישפיע לנו כל הטובות המחזיקות את ידינו לעשות התורה כו'“;\nועד\"ז בעניננו: מיט דעם זאָגט אָן ר' מאיר דעם עוסק בתורה לשמה, אַז ער איז „זוכה לדברים הרבה“ וועלכע וועלן העלפן אַראָפנעמען די מניעות און בלבולים אין זיין לימוד התורה3; ווי ער איז גלייך ממשיך „ולא עוד אלא שכל העולם כולו כדאי הוא לו“, וואָס מיינט, אַז ניט נאָר זיינען די עניני העולם אים ניט מבלבל, נאָר אדרבה — די גאַנצע וועלט איז „כדאי הוא לו“, די ענינים פון וועלט העלפן אים אַרויס ער זאָל קענען עוסק זיין אין תורה מתוך מנוחה ושלוה.\nדער ביאור איז אָבער ניט מספיק, ווייל דאָס פאַרענטפערט נאָר עטלעכע פרטים4 פון די זאַכן וואָס ר' מאיר רעכנט אויס — אָבער כו\"כ פון זיי האָבן ניט קיין שייכות צו דער באַוואָרעניש פון „יסיר ממנו כל הדברים המונעים אותנו“ פון לימוד תורה לשמה.\nב. פון די זאַכן וואָס ר' מאיר רעכנט אויס, זיינען דאָ אַזעלכע אויף וועלכע עס פאַסט לכאורה בכלל ניט צו זאָגן אַז זיי זיינען דער שכר פאַר עוסק בתורה לשמה דוקא. ולדוגמא — אחדים:",[["1","1","ראה מדרש שמואל (ועוד), דיש ב' פירושים — האם הדברים שפרט אח\"כ הם ה„דברים הרבה“ שבתחלת המאמר."],["2","2","הל' תשובה רפ\"ט."],["3","3","נוסף על הסיוע בלימוד התורה גופא — „מגלין לו רזי תורה ונעשה כמעין המתגבר וכנהר שאינו פוסק“."],["4","4","כמו „ונותנת לו מלכות וממשלה“, „ומגדלתו ומרוממתו על כל המעשים“. ואולי גם „אוהב את הבריות .. משמח את הבריות .. ונהנין ממנו כו'“ (ושאר ענינים שבין אדם לחבירו) — שלכן אין הבריות מבלבלים אותו (ואדרבה — מסייעים אותו)."]]],[1300171413,"(א) „אוהב את המקום אוהב את הבריות“ — אויף דעם איז דאָך דאָ אַ חיוב מצות עשה מן התורה5: ואהבת את ה\"א, ואהבת לרעך כמוך.\n(ב) „מרחקתו מן החטא“ — דאַרף מען דען אָנקומען צו דער מעלה מיוחדת פון (שכר פאַר) תורה לשמה בכדי צו דערווייטערן אַ אידן פון אַ חטא? — דערויף איז גענוג דער הרגש פון יראת העונש, יראת חטא. נאָכמער: פריער אין פרקי אבות6 געפינט מען מפורש „הסתכל בג' דברים ואין אתה בא לידי עבירה“ — און דאָס זיינען דברים פשוטים, וואָס די הסתכלות, דער אַריינ־טראַכטן אין זיי האַלט אָפ פון אַן עבירה.\n(ג) „מוחל על עלבונו“ — לכאורה איז אין דעם ניט ניכר די גרויסע מעלה וואָס קומט פון לערנען „תורה לשמה“; וואָרום מוחל זיין אויף אַן עלבון (ד.ה. אַז ער פילט די באַליידיקונג) איז נאָך ניט די אמת'ע מעלה פון ביטול — אַ טיפערער ביטול איז ווען דער עלבון אַרט אים איבערהויפט ניט, ווען ער פילט זיך ניט באַליידיקט מלכתחילה7.\nג. עס זיינען אויך דאָ כמה דיוקים אין לשון פון דעם מאמר, ומהם8:\n(א) דער לשון „מלבשתו ענוה ויראה“ און ניט ע\"ד הרגיל (אַז דורך תורה לשמה) „נעשה עניו וירא“ אָדער „יבוא לענוה ויראה“ וכדומה?\n(ב) וואָס איז די הדגשה „נהנין ממנו עצה ותושי'“ — ניט „מבקשים ממנו“ אָדער „מקבלים ממנו“?\n(ג) ביים סיום פון דעם מאמר שטייט „מגדלתו ומרוממתו על כל המעשים“ — וואָס איז דער חילוק צווישן די צוויי לשונות אין תוכן און ענין?\nד. דער ביאור אין דעם:\nר' מאיר איז מדייק אַז דאָ רעדט זיך וועגן איינעם וואָס איז „עוסק בתורה לשמה“, וואָס די כוונה אין דעם איז:\n„לשמה“ מיינט, אַז מען לערנט ניט צוליב אויסנוצן דעם לימוד אויף וועלכן־ס'איז תכלית אויסער דעם לימוד גופא, אפילו ניט צוליב אַ קדושה'דיקן תכלית (ווי לידע את המעשה אשר יעשון כו', וכיו\"ב), נאָר בלויז צוליב תורה, השגת התורה9 — בלויז צוליב לימוד התורה עצמו.\nאון „עוסק בתורה לשמה“ מיינט, אַז ער לערנט (אין דעם אופן פון, און) מיט עמל ויגיעה10; און נאָכמער, אַז זיין לערנען איז בדוגמא ווי איינער וואָס פירט אַ עסק כפשוטו11, וואָס ער איז אין דעם פאַרנומען טאָג און נאַכט ביז ער",[["5","5","ואתחנן ו, ה. קדושים יט, יח."],["6","6","רפ\"ב ורפ\"ג."],["7","7","ראה פיה\"מ להרמב\"ם אבות פ\"ד מ\"ד. חובת הלבבות שער יחוד המעשה פ\"ה. צוואת הריב\"ש סי' ב' (וראה שם סי' יו\"ד ובשינויי נוסחאות שם)."],["8","8","ראה גם נחלת אבות ועוד כאן."],["9","9","ובתניא ספ\"ה (מפע\"ח) כדי לקשר נפשו לה' ע\"י השגת התורה. וראה ג\"כ ב\"ח או\"ח סמ\"ז ד\"ה ומ\"ש דאמר. בהל' ת\"ת לאדה\"ז (פ\"ד ס\"ג) „לשמה ללמוד ע\"מ לשמור ולעשות“ — כי יש כו\"כ דרגות בלשמה כמו שיש בשלא לשמה (וזב\"ז תליא) — ראה הל' ת\"ת שם. ובארוכה — פיה\"מ להרמב\"ם סנה' ר\"פ חלק. והענין ד„לשמה“ המדובר בנדו\"ד במס' אבות — מילי דחסידותא (ב\"ק ל, א) — הוא דרגא גבוה. וראה ר\"ן נדרים (פא, א. מרבינו יונה), לבוש ושו\"ע אדה\"ז או\"ח שם (בריש הסימן) שלימוד לשמה היינו מצד חשיבות התורה. ובחידושי חת\"ס שם, שזהו לימוד לשם השגת התורה עצמה (ע\"ד „דרוש וקבל שכר“), ולא רק כדי לידע את המעשה כו'. ובארוכה רמב\"ם הל' תשובה (פ\"י ה\"ה) — דלשמה היינו העובד מאהבה, ע\"ש."],["10","10","ב\"ח שם ד\"ה ונוסחא. ט\"ז שם סק\"א."],["11","11","סד\"ה אריב\"ל כו' כל העוסק בתורה וסד\"ה אריב\"ל בכל יום ויום תפר\"ח. ועוד."]]],[1300171414,"הערט ניט אויף צו טראַכטן וועגן דעם — אַזוי, אַז זיין גאַנצע חיות און האָרע־וואַניע איז אין לימוד התורה לשמה, ביז דאָס ווערט זיין גאַנצע מציאות ומהות.\nה. וויבאַלד דאָ רעדט זיך וועגן אַן „עוסק בתורה לשמה“, קען ביי אים נתעורר ווערן אַ שאלה:\nרז\"ל11* זאָגן דאָך „כל האומר אין לו אלא תורה .. אפילו תורה אין לו“, נאָר עס דאַרף זיין תורה מיט גמילות חסדים, ד.ה. אַז אויך דער עוסק בתורה לשמה דאַרף זיך עוסק זיין מיט גמ\"ח12, וואָס דאָס איז מעגלעך נאָר דורך פאַרנעמען זיך מיט מענטשן אַרום אים; נאָכמער: די התעסקות אין גמ\"ח כדבעי איז פאַר־בונדן מיט דער עבודה פון בירור וזיכוך המדות — האָבן אַ געפיל פאַר אַ צווייטן, ניט זיין קיין בעל גאוה, וכו' — וואָס צו דעם פאָדערט זיך אַ באַזונ־דערע עבודה ויגיעה.\nאון אפילו אין ענינים שבין אדם למקום זיינען דאָ כמה וכמה עניני עבודה — מעורר זיין אהבת ה', זיין אַ ירא־שמים כדבעי וכו' — וואָס זיי ווערן ניט אויפגעטאָן בדרך־ממילא, נאָר מ'דאַרף אויף זיי פיל האָרעווען. ובפרט לויט דער הוראה פון רמב\"ם12*: והאיך היא הדרך לאהבתו ויראתו13, בשעה שיתבונן האדם במעשיו וברואיו14 הנפלאים הגדולים ויראה מהן חכמתו כו' מיד אוהב כו' וכשמחשב בדברים האלו עצמן מיד הוא נרתע לאחוריו וירא14* ויפחד כו'.\nפרעגט דער „עוסק בתורה לשמה“: וויבאַלד אַז זיין גאַנצער „עסק“ איז אין תורה לשמה, ווי אַזוי וועט ער קענען טאָן און אויפטאָן אין אַלע אַנדערע עניני עבודת ה'15? וועט ביי אים פעלן, ח\"ו, אין די ענינים?!\nווען ביי אים וואָלט דער עסק בתורה ניט געווען אין דער דרגא פון תורה לשמה, נאָר לידע את המעשה אשר יעשון, כולל אַלע עניני עבודת ה'16 — דעמאָלט זיינען „לימוד“ און „מעשה“ ניט סותר איינע די אַנדערע, נאָר אדרבה, ס'איז אַ לימוד וואָס ברענגט אים צו מעשה ועבודת ה';\nוויבאַלד אָבער אַז דאָ רעדט זיך וועגן אַן עוסק בתורה לשמה — ער טראַכט בכלל ניט וועגן דאָס וואָס ער וועט האָבן און דערגרייכן דורך דעם לימוד, נאָר ער לערנט בלויז צוליב השגת התורה גופא —\nאיז ער דאָך שטענדיק אין אַ מצב, אַז ער טראַכט אינגאַנצן ניט וועגן „זיך“ און זיינע „מדריגות“ אין עבודת ה'17; ער",[["","","11*) יבמות קט, ב. אגה\"ק ס\"ה (קח, סע\"ב). ועוד. וראה ע\"ז יז, ב ומפרשי הע\"י שם."],["12","12","עכ\"פ „מיעוט ימיהם“ (אגה\"ק שם — קט, א). 12*) הל' יסוה\"ת פ\"ב ה\"ב."],["13","13","בכו\"כ כת\"י ודפוסים: וליראתו."],["14","14","בסהמ\"צ להרמב\"ם מ\"ע ג': שנתבונן ונשכיל מצותיו ופעולותיו. ובחינוך סתי\"ח: בפעולותיו ובפקודיו. ובשניהם ממשיך: עד שנשיגהו. וצ\"ע. *) וראה לקו\"ש ואתחנן תשמ\"ח ס\"ב ואילך. 14*) וירא — בדפוס ווארשא חסר (ובמילא גם בצילומיו וכו'). ולפענ\"ד היא השמטת הדפוס דמוכח."],["15","15","פשוט, שבמדריגות גבוהות דעוסק בתורה לשמה (כמו „לשם התורה עצמה“, מחבר תורה שלמעלה בקוב\"ה — לקו\"ת שלח מז, רע\"ג. ובכ\"מ), האדם כבר אוהב וירא ה' וכו' — אבל [נוסף לזה, שגם בזה יתכן שהענינים שבין אדם לחבירו לא יהיו בתכלית השלימות, הרי] הוראת ר\"מ היא ל„כל העוסק בתורה לשמה“, גם דרגות נמוכות יותר (וראה מד\"ש כאן)."],["16","16","דלעשיית מצוות כפשוטה — הרי (כל) תלמוד מביא לידי מעשה (קידושין מ, ב. וש\"נ). ואפילו תורתו אומנתו מפסיק לעשיית מצוה (ירושלמי ברכות פ\"א סה\"ב. שבת פ\"א סה\"ב). וראה בארוכה לעיל ע' 305 ואילך."],["17","17","אף שמפסיק לעשיית מצוות (כנ\"ל הערה הקודמת). וראה תוד\"ה כאן מו\"ק ט, ריש ע\"ב."]]],[1300171415,"האָט ניט קיין צייט אַריינצוקלערן צי ער האָט שוין מברר ומזכך געווען זיינע מדות צי ניט (ועאכו\"כ צו פאַרנעמען זיך מיט (עניני גמ\"ח —) מענטשן אַרום זיך)18 — טאָ וואָס וועט זיין מיט אַלע אַנדערע ענינים אין עבודת ה'?\nו. איז ר' מאיר מחדש „כל העוסק בתורה לשמה זוכה לדברים הרבה“ — דער דיוק איז „זוכה“ (און ניט אַז ער וועט זיי האָבן אַלס שכר):\nדער שכר וואָס דער אויבערשטער צאָלט אַ אידן פאַר לימוד התורה וקיום המצות איז בערך צו דער תורה און מצות עצמן. וואָס דאָס איז אפילו לויט דער דיעה19 אַז שכר מצוות איז (ניט ווי אַ תוצאה ומסובב פון די מצוות אַליין, נאָר) אין אַ סגולה'דיקן אופן, ווי אַ (זייטיגע) באַלוינונג פאַר טאָן די מצוה.\nוואָרום וויבאַלד יעדע מצוה האָט זיך איר שכר, איז פאַרשטאַנדיק, אַז דער שכר האָט אַ שייכות און אַ התדמות צו דער מצוה פאַר וועלכער דער שכר איז באַשטימט געוואָרן20;\nועל אחת כמה וכמה לויט דער דיעה19 אַז שכר מצוות איז ווי אַ טבעית'דיקע תוצאה פון דער מצוה גופא21 — איז דאָך אַוודאי דער שכר בערך צו דער מצוה גופא.\nועד\"ז בנדו\"ד: דער שכר פאַר „עוסק בתורה לשמה“ — איז אין דעם זעלבן ענין, דהיינו: התקשרות צום נותן התורה וואָס אורייתא וקוב\"ה כולא חד22. און דערפאַר קען מען ניט אָנ־רופן די „דברים הרבה“ וואָס זיינען דאָ אויסגערעכנט געוואָרן מיטן נאָמען „שכר“, וויבאַלד אַז אין זיי דריקט זיך ניט אויס דער ענין פון תורה לשמה (התקשרות להקב\"ה, לנותן התורה).\nאון דאָס איז ר' מאיר מחדש, אַז אין צוגאָב צום עיקר השכר (אַלס תוצאה) פון „עוסק בתורה לשמה“, איז ער אויך „זוכה לדברים הרבה“ — ער באַקומט, בדרך זכי', „דברים הרבה“ וואָס זיינען נידעריקער23 פון דער עצם מדריגה פון עוסק בתורה לשמה, וואָס די „דברים“ זיינען אים מסייע אין אַלע אַנדערע עניני עבודת ה', כדלקמן.\nז. די „דברים הרבה“, צו וועלכע דער עוסק בתורה לשמה איז זוכה, טיילן זיך אין צוויי סוגים: „דברים“ וואָס ער באַקומט בדרך ממילא, ער דאַרף אויף זיי ניט האָבן קיין באַזונדערע יגיעה; און אַנדערע „דברים“ צו וועלכע ער איז „זוכה“ נאָר באופן חלקי ובמילא איז נויטיק אויך זיין עבודה; ד.ה. ער באַ־קומט זיי דורך אַ פיל גרינגערער עבודה ווי אַ צווייטער — אָבער דאָך דאַרף ער טאָן אַז זיי זאָלן ביי אים זיין כדבעי ובשלימות.",[["18","18","ראה עד\"ז לקו\"ש חט\"ז (ע' 271־2) בביאור מאמר ריב\"ז (ברכות כח, ב) איני יודע באיזו (דרך) מוליכים אותי — שמפני גודל טרדותיו במילוי שליחותו בעלמא דין לא הי' מרגיש אהוי\"ר שלו. עיי\"ש."],["19","19","ב' הדיעות הובאו ונתבארו בשל\"ה בית אחרון (יב, א־ב)."],["20","20","ועפ\"ז יש להתאים מ\"ש אדה\"ז בתניא פל\"ט (נג, א) — „שכר מצוה מצוה פי' שמשכרה נדע מהותה“ — גם לדיעה זו."],["21","21","בלשון התניא (רפל\"ז): כי הגורם שכר המצוה היא המצוה בעצמה. וראה הנסמן בלקו\"ש ח\"ה ע' 135 הערה 23."],["22","22","ראה תניא פכ\"ג. ליקוט פי' לפרק זה (קה\"ת, ברוקלין, תשל\"ח). ולהעיר מחדא\"ג פסחים נ, ב."],["23","23","וכן זוכה לדברים שלמעלה מה„שכר“ שמגיע לו, כי הם למעלה מגדר נברא (מצ\"ע) ובאים אל האדם רק דרך זכי' ואתעדל\"ע, כגון: מגלין לו רזי תורה ונעשה כמעין המתגבר וכנהר שאינו פוסק. וכן לפמשנ\"ת (לקו\"ש ח\"ז ע' 371) הפירוש ב„דברים הרבה“ שהו\"ע הריבוי א\"ס שבתורה — שהוא רק בדרך „זכי'“."]]],[1300171416,"און דאָס זיינען די שינוים און די דיוקי לשונות פון ר' מאיר „ומלבשתו ענוה ויראה, ומכשרתו להיות צדיק חסיד ישר ונאמן, ומרחקתו מן החטא ומקרבתו לידי זכות“ — ווייל אויף די זאַכן דאַרף דער עוסק בתורה לשמה האָרעווען צו באַקומען זיי בשלימותם:\nדער עוסק זיין בתורה לשמה טוט נאָר אויף אַז „מלבשתו ענוה ויראה“ — די תורה פועל'ט ביי אים אַז ער זאָל האָבן די מדות (ענוה און יראה<sup data-n=\"24\">24</sup> בדרך לבוש, אין אַן אופן חיצוני (ווי אַ לבוש אויפן אדם) — זיי ווערן אָבער ניט פאַר־איינציקט מיט אים ביז צו ווערן זיינע מדות („נעשה עניו וירא“); אַזוי איז תורה אים (נאָר) מכשיר צו ווערן אַ „צדיק .. ונאמן“, מרחיק פון אַ חטא (ע\"ד (ולא ממש) לא יאונה לצדיק כל און<sup data-n=\"25\">25</sup> און מקרב צו מצוות — אָבער בכדי צו זיין „צדיק .. ונאמן“ בפועל, זיין אָפגעהיט פון חטאים און האָבן זכיות בפועל — דאַרף ער האָבן עבודה ויגיעה.\nועד\"ז „מוחל על עלבונו“: די תורה, וואָס איז „דברי כאש“26, איז מלבן ומזכך27 די מדות פון דעם וואָס לערנט תורה לשמה, אַז ער זאָל זיין אַ מוחל על עלבונו; אָבער בכדי צו דערגרייכן די שלימות אין בירור המדות, אַז ער זאָל מלכתחילה ניט פילן קיין עלבון, פאָדערט זיך אַן עבודה מיוחדת.\nח. לאידך אָבער, זיינען דאָ „דברים“ צו וועלכע דער עוסק בתורה לשמה איז זוכה בשלימותם, אינגאַנצן אָן זיין השתדלות מיוחדת אין זיי28 — לדוגמא: אוהב את המקום אוהב את הבריות, משמח את המקום משמח את הבריות .. ונהנין ממנו עצה ותושי' בינה וגבורה .. ונותנת לו מלכות וממשלה וחקור דין.\nאון וויבאַלד אַז ער איז „אוהב את הבריות .. משמח את הבריות“, וועט דאָך ביי אים ניט פעלן ח\"ו אין זיין הנהגה טובה בין אדם לחבירו; און נאָכ־מער: דוקא דערפאַר וואָס ער איז עוסק בתורה לשמה איז ער זוכה צו דער־הויבנקייט אין שכל בכלל, אויך אין וועלט־זאַכן, אַזוי אַז ער קען געבן אַן „עצה“ אויך אין מילי דעלמא כו'29, ביז צו אַן עצה וואָס תורת אמת איז מעיד אַז „נהנין ממנו כו'“ — און וויבאַלד אַז „נהנין ממנו עצה ותושי'“ איז ער דאָך „משמח את הבריות“30.",[["24","24","הטעם שנותנים לו ב' מדות אלו דוקא, י\"ל שהוא מפני שהן מוכרחות לעבודת האדם, כמשנ\"ת בארוכה בהתוועדות (ע\"פ סיום מס' סוטה: לא תיתני ענוה ... יראת חטא)."],["25","25","משלי יב, כא. וראה דרך חיים (למהר\"ל) אבות כאן."],["26","26","ירמי' כג, כט."],["27","27","ראה לקו\"ש חט\"ז ע' 387־8 (בפי' „עיקר טבילותא בנורא“ — סנה' לט, א)."],["28","28","וי\"ל, שזהו בעיקר בענינים דמילי דעלמא ואלה הנוגעים בין אדם לחבירו — כדי שלא יצטרך „לצאת“ מד\"א של תורה ועבודה להתעסק בהם. ומה ש„אוהב את המקום .. משמח את המקום“ (ולא רק „מכשרתו“ לזה וכדומה) — יש לומר, כי מדת האהבה (החפץ לדבקה בו ית') נוגע לעוסק בתורה לשמה גופא — ראה תניא פמ\"א שם איך שכל הכוונות דחשיב מיוסדים באהבה כו' — (וראה בארוכה רמב\"ם הל' תשובה פ\"י). וראה חינוך (מצוה תיח): שעם ההתבוננות בתורה תתישב האהבה בלב בהכרח; ומכש\"כ מה שמגלין לו רזי תורה ונעשה כמעין המתגבר וכנהר שאינו פוסק."],["29","29","להעיר גם מתולדות י\"י ס\"פ ויצא בשם הבעש\"ט (בפי' משנה זו). ובאגה\"ק סכ\"ב: ונהנין ממנו עצה ותושי' היינו בד\"ת כו'."],["30","30","וי\"ל, שהענין ד„אוהב .. משמח את הבריות“ נעשה דוקא מצד היותו עוסק בתורה לשמה. כי התואר „בריות“ מורה על מי שאין בו שום מעלה רק זה שנברא ע\"י הקב\"ה [ראה תניא פל\"ב. תענית כ, ריש ע\"ב. ובארוכה לקו\"ש חט\"ז ע' 123־5], ולכן: העוסק בתורה בשביל איזו תכלית, הרי טיפולו והתעסקותו הוא עם אלה שבידם להביא לו תועלת"]]],[1300171417,"ט. דערפון איז פאַרשטאַנדיק, אַז אין דעם מאמר פון ר' מאיר איז דאָ אַ הוראה (ניט נאָר פאַר דעם עוסק בתורה לשמה אַליין, נאָר) אויך פאַר אַ צווייטן אידן, וואָס קען טראַכטן:\nוויבאַלד אַז אַן עוסק בתורה לשמה מוז זיין אָפגעזונדערט פון עניני העולם און פון מענטשן אַרום — איז דאָך ביי אים ניטאָ קיין ידיעה אין עניני העולם (וואָרום אויב יע, איז דאָך דאָס גופא אַ באַווייז אַז ער איז ניט קיין עוסק בתורה לשמה); און על אחת כמה וכמה אַז עס איז ניט שייך צו פאַרלאָזן זיך אויף זיינער אַן עצה אין מילי דעלמא אָדער עסקנות ציבורית וכיו\"ב.\nבאַוואָרנט עס ר' מאיר, אַז אדרבה: דוקא צוליב דעם וואָס ער איז עוסק בתורה לשמה איז ער זוכה צו אַ שלימות'דיקער הבנה אין עניני העולם — און דערפאַר איז „נהנין ממנו עצה ותושי' כו'“, אַז די עצה וואָס ער גיט איז אין אַן אופן פון „נהנין“.\nובפשטות: אויב ער האָט ניט גענוג קלאָרקייט אין די געפרעגטע זאַכן, וועט ער זיך אָפהאַלטן פון געבן אַן עצה; אָבער לאידך, אויב ער וועט יע אַרויס־זאָגן זיין מיינונג און אַן עצה, איז דאַן קלאָר אַז דאָס איז די אמת'ע און ריכטיקע עצה ותושי' לויט תורת אמת; און אפילו ווען ס'דוכט זיך אַז די עצה וואָס ער גיט איז ניט אויסגעהאַלטן לויטן שכל אנושי — וויבאַלד אָבער אַז ער, דער עוסק בתורה לשמה, איז אַן „אוהב .. משמח את הבריות“, איז אַ דבר ברור אַז „נהנין ממנו כו'“, אַז פון דער עצה וואָס ער גיט זייענדיק אַן אוהב און מיטן כח התורה וועט מען געוויס הנאה האָבן.\nיו\"ד. דערמיט וועט אויך זיין פאַר־שטאַנדיק דער לשון המשנה „מגדלתו ומרוממתו על כל המעשים“, אַז דאָס איז ניט סתם אַ כפל לשון —\nע\"פ כל הנ\"ל קומט אויס, אַז אין דעם ציור ומצב פון אַן עוסק בתורה לשמה זיינען דאָ צוויי אופנים און דרגות שונות: (א) מצד זיין עצם עסק אין תורה לשמה איז ער העכער פון אַלע עניני העולם (פונקט ווי תורה אַליין); (ב) מצד די „דברים הרבה“ צו וועלכע ער איז „זוכה“ האָט ער אַ שייכות צו עניני העולם (כאָטש זיי זיינען פיל נידערי־קער פון זיין דרגא ומעלה — עוסק בתורה לשמה).\nאון בהתאם צו די צוויי דרגות זאָגט די משנה די צוויי לשונות „מגדלתו ומרוממתו“: „גדול“ פאַסט אין פאַר־גלייך צו איינעם וואָס (האָט אַן ערך צו אים, נאָר ער) איז קלענער פון אים; „רוממות“ ווייזט אויף אַ דערהויבנקייט און אָפגעטראָגנקייט וואָס איז שלא בערך העכער פון דעם פון וועמען ער איז מרומם.\nובעניננו: מצד די „דברים הרבה“ צו וועלכע ער איז זוכה (וואָס זיי האָבן אַ שייכות און אַן ערך צו עניני העולם והבריאה) איז ער גדול על כל המעשים — זיין גדלות קעגן די מעשים און עניני העולם איז בערך, נאָר ער איז גרעסער פון זיי;\nמצד דעם עצם עסק בתורה לשמה איז ער אינגאַנצן אָפגעטראָגן און העכער",[["","","לתכלית זו שבשבילה לומד, אבל לא עם בריות בעלמא שלא יוכלו לסייע לו; אבל העוסק בתורה לשמה, שלומדה אך ורק משום שהיא תורתו של הקב\"ה, הרי דוקא משום זה יש בו רגש וקירוב ואהבה גם לבריות (מכיון שגם הם נבראו מאתו ית'), ולכן מטפל עמהם ולא עוד אלא ש„משמח את הבריות“."]]],[1300171418,"פון כל עניני העולם — „מרוממתו על כל המעשים“.\nיא. אע\"פ אַז די דרגא פון עוסק בתורה לשמה — אין אַן אופן תמידי — איז ניט צו יעדן איינעם31 שייך, זאָגט אָבער דער אַלטער רבי אין תניא32, אַז די כוונה פון לשמה דאַרף זיין ביי „יעדערן“33 עכ\"פ „בתחלת הלימוד“.\nויש לומר דעם ביאור אין דעם:\nוויבאַלד אַז תורתו של הקב\"ה איז אין סוף, קען זי ניט נתפס ווערן אין דעם שכל פון אַ מענטשן, אַ נברא און מוגבל, סיידן עס איז ביי אים דאָ די תנועה פון ביטול, וואָס דורכדעם קען ער מקבל זיין תורתו של הקב\"ה34; און ע\"ד ווי מען געפינט ביי מתן תורה, אַז די כלי צו קבלת התורה איז געווען דער ביטול פון זייער זאָגן „נעשה ונשמע“35 (און — בהקדמת נעשה לנשמע<sup data-n=\"36\">36</sup>.\nאון אַזוי איז עס אויך ביי יעדערן, אַז איידער עס הויבט זיך ביי אים אָן דער סדר פון לימוד התורה — וואָס דאַן איז דער פסק־דין אַז לעולם יעסוק אדם בתורה ואפילו שלא לשמה כו'37 — דאַרף זיין די תנועה פון „קבלת התורה“, כדי צו באַקומען אַ שייכות מיט תורתו של הקב\"ה38;\nאון דאָס איז דורך דער תנועה פון ביטול, וואָס דריקט זיך אויס אין דער כוונה „לשמה“ — ער האָט ניט קיין אייגענע פני' אין זיין לימוד (וואָס ווייזט אויף אַ הרגש פון דער אייגענער מציאות), און עס הערט זיך נאָר אָן די מציאות פון תורה39.\nאון דאָס איז אויך דער טעם פאַר־וואָס דער מסדר הברייתא האָט אָנגע־הויבן די ברייתא פון „קנין תורה“ מיט דעם מאמר פון ר' מאיר\n— דלכאורה תמוה: פריער וואָלט גע־פאַסט צו ברענגען די ברייתות וואָס זיינען מזרז אויף לימוד התורה בכלל, און ערשט דערנאָך אויף דער העכסטער מדריגה אין לימוד התורה (עוסק בתורה לשמה)? —\nווייל די ברייתא פון „קנין תורה“ וועלכע מען לערנט אין דעם שבת פאַר שבועות, זמן מתן תורתנו, גיט אַרויס דעם סדר ווי אַ איד דאַרף זיך גרייטן צו קבלת התורה בחג השבועות40; וואָס דער סדר איז: צום אַלעם ערשטן פאָדערט זיך די תנועה פון „עוסק",[["31","31","ראה רמב\"ם הל' תשובה שם ה\"ב: ומעלה זו היא מעלה גדולה מאד ואין כל חכם זוכה לה והיא מעלת אברהם אבינו כו'. וראה גם (בארוכה) פיה\"מ סנה' ר\"פ חלק."],["32","32","ספמ\"א (נח, ב)."],["33","33","כמ\"ש שם „בבינונים“ — ש„היא מדת כל אדם כו'“ (תניא רפי\"ד). וראה שם לפנ\"ז (נח, א) „בזה חפץ כל אדם מישראל באמת לאמיתו לגמרי בכל לב ובכל נפש ... לדבקה בה'“. ועיג\"כ בסיום הפרק שם."],["34","34","ראה גם לקו\"ש חט\"ז ע' 326 ואילך."],["35","35","משפטים כד, ז."],["36","36","שבת פח, א."],["37","37","פסחים נ, ב. וש\"נ. רמב\"ם שם ה\"ה. פיה\"מ שם. וראה הל' ת\"ת לאדה\"ז פ\"ד ס\"ג ובקו\"א שם."],["38","38","להעיר ממשנ\"ת (לקו\"ש חט\"ז ע' 1 ואילך) הטעם שהתורה מתחילה בבי\"ת — כי לימוד התורה בהבנה והשגה הו\"ע ה„ב“ שבתורה, כי אפ\"ל רק לאחרי הקדמת הביטול."],["39","39","בערך הדרגא בלשמה „לשם התורה“ (נסמן לעיל הערה 15), הכוונה דלשמה לקשר נפשו לה' נק' לימוד אדעתא דנפשי' (ראה הנסמן בתורת שלום ע' 19 הערה 3) — אבל בכללות, מכיון שגם בכוונה זו לומד אך ורק בשביל התקשרות זו שנעשה ע\"י השגת התורה גופא, נק' לימוד שלא אדעתא דנפשי'. וראה תורת שלום שם."],["40","40","ראה מדרש שמואל כאן בריש הפרק."]]],[1300171419,"בתורה לשמה“41, וואָס דורכדעם איז מען מקבל תורה; און ערשט דערנאָך הויבט זיך אָן דער סדר פון לימוד התורה בפועל.\n(משיחות ש\"פ במדבר, חגה\"ש וש\"פ נשא תשל\"ה)",[["41","41","עדמשנ\"ת כמ\"פ (לקו\"ש חי\"ב ע' 229. ועוד) דאפשר לכאו\"א לקבוע עתים בתורה באופן שבעת ההיא יהי' לימודו באופן דתורתו אומנתו."]]],[1300171420,"<h3>פרקי אבות</h3>\nא. „רבי חנני' בן עקשיא אומר רצה הקב\"ה לזכות את ישראל לפיכך הרבה להם תורה ומצות שנאמר 1 ה' חפץ למען צדקו יגדיל תורה ויאדיר”.\nדער מאמר פון ר' חנני' בן עקשיא, הגם אַז מקומו בסדר המשניות איז בסיום מס' מכות, איז מנהג ישראל צו זאָגן עם נאָך יעדן פרק פון פרקי אבות, ווייל, ווי רש\"י 2 איז מפרש דעם טעם, „לפי שיש בה סיום נאה נהגו כל העם לאומרו בסוף כל פרק ופרק לפי שאין אומרים קדיש על המשנה אלא על האגדה כו'” 3.\nוויבאַלד אָבער אַז אַלע ענינים אין תורה זיינען בתכלית הדיוק (און אויך „מנהג ישראל תורה היא”<sup data-n=\"4\">4</sup>, ובפרט אַז אַ טייל מפרשי המשניות פון אבות האָבן דעם מאמר צוגעשטעלט צו פרקי אבות, וואו זיי זיינען מפרש דעם מאמר — איז מובן אַז דער מאמר האָט אַ שייכות אויך צו מס' אבות.\nאויך איז מנהג ישראל, אַז פאַר יעדער פרק אין פרקי אבות זאָגט מען די משנה „כל ישראל יש להם חלק לעולם הבא כו'” — אַ משנה אין מס' סנהדרין 5. און ס'איז דאָ אַ צד השוה צווישן די צוויי משניות (וואָס מ'זאָגט בהתחלה ובסיום) וואָס אין ביידע איז מודגש די מעלה פון אידן 6: אין דער משנה „כל ישראל” — אַז זיי זיינען „נצר מטעי מעשה ידי”, און אין דער משנה פון „ר\"ח בן עקשיא” — אַז דער ריבוי פון תורה ומצות איז צוליב אידן, „רצה הקב\"ה לזכות את ישראל לפיכך הרבה להם תורה ומצות”.\nדאַרף מען פאַרשטיין: פרקי אבות אַנטהאַלטן, כידוע, הוראות און הנהגות ומדות טובות, ביז מילי דחסידותא 7, איז וואָס איז אין דעם נוגע דער ענין פון מעלתם של ישראל ?\nב. וועט דאָס זיין פאַרשטאַנדיק בהקדים דעם ביאור אין אונזער משנה:\nדער ברטנורא 8 איז מפרש: לפיכך הרבה להם תורה ומצות כגון פרשת שקצים ורמשים 9 כדי להרבות שכר כשהן בדלים מהם, אע\"פ שבלאו הכי לא היו אוכלין אותן שנפשו של אדם קצה בהן [לפ\"ז קען מען זאָגן כעין זה אויך בנוגע צו תורה ולימודה, אַז דער אויבערשטער האָט אין תורה אַריינ־געשטעלט אויך אַזוינע ענינים וואָס זיינען „בלאו הכי” פאַרשטאַנדיק מצד השכל של האדם, „כדי להרבות שכר” פאַר לערנען אויך די ענינים 10].",[["1","1","ישעי' מב, כא."],["2","2","בסיום מס' אבות."],["3","3","וראה מג\"א או\"ח סנ\"ד סק\"ג. שו\"ע אדה\"ז שם ס\"ד. ובהמובא (מבאר שבע) במסורת הש\"ס לאבות בסופו. ואכ\"מ."],["4","4","ראה ירושלמי פסחים פ\"ד ה\"א, ועוד (נסמן בלקו\"ש ח\"ד ע' 1080)."],["5","5","רפי\"א (צ, א)."],["6","6","ראה דרך חיים למהר\"ל בריש מס' אבות בביאור המשנה „כל ישראל”."],["7","7","ראה ב\"ק ל, א."],["8","8","בסוף מס' מכות. ועד\"ז הוא בפרש\"י (ריב\"ן) להמשנה במכות (כג, רע\"ב). ומאירי שם. וכ\"פ בזית רענן לילקו\"ש שמיני רמז תקלו. ובז\"ר שבהערה 10. וראה מלאכת שלמה מכות שם."],["9","9","ובפרש\"י (מכות שם) שקצים ונבלות. וצ\"ע שלא הזכירו דם, דבי' קאי לפני זה בהמשנה שם. וראה פרש\"י עה\"ת ראה יב, כה (שם, כג)."],["10","10","וע\"ד חולין סו, ב (וראה ז\"ר לילקו\"ש שמיני שם (דף קמו, ע\"א)). משא\"כ בענינים שעליהם אמרו"]]],[1300171421,"לויט דעם פירוש איז אָבער ניט מובן: א) דער לשון „הרבה להם” — וואָרום לפי הנ\"ל איז „לזכות את ישראל” אַ טעם ניט אויף דעם (כללות ה)ריבוי פון תומ\"צ, נאָר אויף דעם ציווי פון באַשטימטע מצות. ב) דער לשון „לזכות את ישראל” — דלפי פירושו האָט גע־דאַרפט שטיין אַ לשון וואָס דריקט אויס דעם ענין השכר, ווי „להרבות את שכרם” 11 וכיו\"ב.\nג. דער רמב\"ם 12 איז מפרש די משנה הנ\"ל: „כי 13 כשיקיים אדם מצוה מתרי\"ג מצות כראוי וכהוגן ולא ישתף עמה כוונה מכוונת העולם בשום פנים אלא שיעשה אותה לשמה מאהבה כו' הנה זכה בה לחיי העולם הבא ועל זה אמר ר\"ח כי המצות בהיותם הרבה אי אפשר שלא יעשה אדם בחייו אחת מהם על מתכונתה ושלמותה ובעשותו אותה המצוה תחי' נפשו באותו מעשה”.\nלויט דעם פירוש איז מוסבר דער לשון „הרבה להם תומ\"צ”: דווקא דורך דעם ריבוי אין תומ\"צ וועט דער אדם געוויס מקיים זיין (עכ\"פ) איינע בשלימותה וכו', איז שוין רעכט אַז דער „הרבה להם” איז געווען דערפאַר וואָס „רצה הקב\"ה לזכות וכו'”.\nאָבער (נוסף אויף דעם וואָס אויך לפירושו בלייבט די שוועריקייט פאַר־וואָס עס שטייט דער לשון לזכות 14 את ישראל, און ניט אַ לשון פון שכר, כנ\"ל, איז) דער עצם פירוש 15 דורש ביאור 16: לפי פירושו קומט אויס, אַז אין דעם ענין פון „הרבה להם (תורה ו)מצות” איז ניטאָ קיין מעלה לעצמו, דער ריבוי אין מצות איז נאָר אַ מיטעל (אַן ענין טפל צוליב דער איין מצוה) וואָס פאַר־זיכערט אַז אַ איד וועט מקיים זיין איין מצוה „על מתכונתה ושלמותה” 17.\nד. אויך דאַרף מען פאַרשטיין:\nא) ר\"ח בן עקשיא איז מדגיש „רצה הקב\"ה לזכות את ישראל”? — און אין פסוק איז די הדגשה „ה' חפץ למען צדקו” — צוליב דעם אויבערשטנ'ס צדק 18 ?\nב) אין פסוק רעדט זיך בלויז וועגן תורה — „יגדיל תורה ויאדיר” — און ר\"ח בן עקשיא איז מדגיש „לפיכך הרבה להם תורה ומצות” 19 ?",[["","","(סנהדרין עא, א. ובכ\"מ) „דרוש וקבל שכר”. אבל ראה של\"ה (תט, סע\"ב ואילך. וש\"נ) דגם במקום שאמרו יגדיל תורה ויאדיר שאינו ענין להך מילתא אבל מ\"מ יש ללמוד ממנו כו' למקום אחר, ע\"ש. וראה לקו\"ש חי\"ד ע' 72 הערה 14. אנצקלופדי' תלמודית ערך דרוש וקבל שכר. ואכ\"מ."],["11","11","וכהלשון בתנחומא שמיני ח. יל\"ש שם (רמז תקלו): כדי שיתן שכר טוב לישראל שמשמרין את המצות. כמו שפי' בזית רענן שם."],["12","12","בפיה\"מ סוף מס' מכות. וראה עקרים מ\"ג פכ\"ט. מדרש שמואל בסוף מס' אבות."],["13","13","בדברי הרמב\"ם — עייג\"כ שער המצות להאריז\"ל בתחלתו. עיי\"ש."],["14","14","אע\"פ שגם בפיה\"מ כתב „זכה” — ה\"ז לכאורה שכר קיום מצוה במתכונתה ושלימותה."],["15","15","וראה בארוכה דרך חיים למהר\"ל בסופו, שהרבה להשיג על פי' הרמב\"ם."],["16","16","גם: הרי אין זה הסברה על הריבוי בתורה."],["17","17","אבל י\"ל בפירוש דברי הרמב\"ם — ועפ\"ז מתורצות לכאורה גם קושיות המהר\"ל — (דלא נחית להחילוק אם יש לו חציו זכות כו', אלא) דכוונתו ע\"ד המבואר (אגה\"ק ס\"ז. ובכ\"מ) בפי' (שבת קיח, ב) אבוך במאי הוי זהיר טפי, שלכל אחד יש מצוה מסוימת שע\"י נמשך ומאיר לו האור שבכל המצות. וראה צפע\"נ לפיה\"מ מכות שם. חדא\"ג מהרש\"א מכות (כג, ב ד\"ה תרי\"ג מצות)."],["18","18","ראה רד\"ק ישעי' שם. אבל ראה פיה\"מ ורע\"ב מכות שם."],["19","19","בדרך חיים שם בסופו: נגד שהרבה להם תורה אמר יגדיל תורה וכנגד רבוי מצות אמר ויאדיר. וצ\"ע איך מרומז זה בל' ויאדיר."]]],[1300171422,"ג) אויך פאָדערט זיך ביאור פאַרוואָס דער לשון המשנה איז אַנדערש ווי דער לשון הכתוב: אין דער משנה שטייט „רצה הקב\"ה” און אין פסוק — „ה' חפץ”.\n[אע\"פ אַז „לשון תורה לעצמה ולשון חכמים לעצמן” 20, געפינט מען אָבער בכמה מקומות, אַז אָפלערנענדיק אַ גע־וויסן ענין פון פסוק נוצן די חכמים אין זייער רייד דעם לשון הפסוק; ולדוגמא (אין די לשונות הנ\"ל און בנוגע לתומ\"צ): לעולם 21 ילמוד אדם תורה במקום שלבו חפץ שנאמר כי אם בתורת ה' חפצו. ממצוא חפצך, חפציך אסורין חפצי שמים מותרין 22. וכמה כיו\"ב 23].\nד) די משנה זאָגט „לפיכך הרבה להם תורה ומצות”, וואָס דער פשוט'ער טייטש פון „הרבה” איז אַ ריבוי אין מספר 24 וכמות, דאַקעגן דער לשון הכתוב (הראי') איז „יגדיל תורה ויאדיר” איכות'דיקע גרויסקייט און שטאַר־קייט 25.\nה. די נקודת הביאור בכל זה:\nדער ריבוי אין תומ\"צ וועגן וועלכן די משנה רעדט דאָ איז ניט ווי ס'איז משמע בפשטות (ומלשון פירוש המשניות), אַז דאָס מיינט דעם מספר תרי\"ג פון מצות 25* וואָס דאָס איז אַ ריבוי, וואָרום מ'האָט דאָך ניט קיין טעם ויסוד וויפל עס דאַרף זיין מספר המצות, און אויף יעדן מספר וואָלט מען געקענט פרעגן פאַרוואָס איז לא פחות (ולא יתר).\nנאָר די משנה רעדט דאָ וועגן דעם „הרבה” אין דעם זעלבן ענין פון תורה און מצות.\nובלשון (וע\"ד) מחז\"ל 26 — וויבאַלד אַז באַ דוד והעמידן על אחד עשר וואָלט געווען גענוג אַז דאָס זאָל זיין מספר המצות, ועד\"ז לויט ר' סעדי' גאון 27 אַז אַלע מצות זיינען נכלל בעשרת הדברות — וואָלט געווען גענוג די עשר מצות.\nאון אפילו את\"ל אַז עס דאַרפן זיין אַלע תרי\"ג ענינים, וואָלט יעדערע פון די עלף אָדער צען געהאַט כו\"כ פרטים אין דער מצוה גופא — ע\"ד ווי אויך איצטער האָט יעדער מצוה כו\"כ פרטים 28 — און דאָס פאַרענטפערט דער רמב\"ם אַז דאַמאָלס וואָלט ניט גע־ווען די זיכערקייט פון קיום מצוה אפילו איינע פון הנ\"ל במתכונתה ושלימותה. ואולי י\"ל יתרה מזה — דורך עובר זיין אויף איין פרט פון די מצות הנ\"ל פעלט אין דער שלימות המצוה כאָטש ער האָט מקיים געווען אַלע איבריגע פרטים.\nו. ובפנימיות הענין:\nיעדער מצוה און ענין אין תורה איז אַנדערש פון אַ צווייטער מצוה און אַ צווייטן ענין אין תורה, ביז אַז דאָס איז טיילמאָל אין אַן אופן הפכי — אָנהויבנ־דיק פון דער חלוקה כללית מצות עשה",[["20","20","חולין קלז, ב. וראה תוד\"ה שתי (מנחות צד, א). שד\"ח כללים מערכת למד כלל קטו."],["21","21","ע\"ז יט, א. וראה שם בגמרא לפני\"ז."],["22","22","שבת קיג, א."],["23","23","וראה מו\"ק ט, ב. ועוד."],["24","24","ובפרט בנדו\"ד כמפורש בפיה\"מ."],["25","25","וגם בחולין (סו, ב) שהובא „יגדיל תורה גו'” — הרי הכוונה לכאורה לההגדלה וכו' בענין זה שבתורה. ולהעיר מתוס' שם. ובהמצוין בהערה 10. וראה רמב\"ם הל' ת\"ת ספ\"ב. 25*) להעיר גם מאו\"ת (להה\"מ) צג, ג."],["26","26","מכות כד, א. בחדא\"ג שם „שהם כוללים חלק גדול מהתורה” ולא כולו — וצע\"ג. וראה תפא\"י למהר\"ל פנ\"ד, וביאורו בהצ\"צ לתהלים (יהל אור) טו, ב (בסופו)."],["27","27","באזהרות שלו — הובא בפרש\"י עה\"ת (משפטים כד, יב)."],["28","28","להעיר מסה\"מ להרמב\"ם שורש ז. מבוא הרי\"פ פערלא לסהמ\"צ להרס\"ג."]]],[1300171423,"ומצות לא תעשה (חיוב ושלילה) 29, די חילוקים פון עדות חוקים ומשפטים, ביז צו דער התחלקות פון תרי\"ג מצות, וואָס יעדע מצוה האָט איר תוכן 30, טעם און כוונה 31; און אַזוי אויך אין תורה, אָנהויבנדיק מיט דער התחלקות פון די פיר אופנים אין יעדער ענין שבתורה: פשט רמז דרוש סוד, די חילוקים פון מ\"ט פנים טמא מ\"ט פנים טהור 32, ע' פנים לתורה 33, און נאָכמער — ביז ששים רבוא פירושים אין יעדן אופן הנ\"ל פון תורה 34.\nוואָס דאָס איז דורש ביאור: תורה אחת ומצותי' זיינען געגעבן געוואָרן מהשם אחד און ענינם איז צו ממשיך זיין און מגלה זיין הוי' אחד ושמו אחד, די אחדות הפשוטה פון דעם אויבערשטן. איז דאָך מובן, אַז אויך אין דער עבודה פון אַ אידן דאַרף יעדער מצוה זיין פאַר־בונדן מיט דער איין־איינציקער כוונה ותכלית: צו פועל זיין דעם פאַרבונד און התאחדות כביכול פון דעם מקיים המצוה מיטן אויבערשטן, וואָס איז אחדות הפשוטה; און אַזוי אויך אין תורה, צו פאַראיינציקן זיך מיט'ן נותן התורה דורך השגת התורה.\nאון עד\"ז אויך אין דעם אויפטו פון תומ\"צ, אַז זייער ענין איז צו אַראָפּ־נעמען דעם העלם והסתר פון וועלט (וואָס מצד דעם זיינען עניני העולם אין אַ ציור פון ריבוי ופירוד) און מאַכן פון וועלט (רשות הרבים) אַ רשות היחיד ליחידו של עולם — מגלה זיין אחדותו של הקב\"ה אין וועלט.\nאון וויבאַלד אַז תומ\"צ איז ענינם — אחד — פאַרוואָס איז דאָ אין זיי אַזאַ ריבוי התחלקות ?\nז. איז די משנה מסביר „רצה הקב\"ה לזכות את ישראל לפיכך הרבה להם תורה ומצות”, „לזכות” איז פון לשון „זיכוך”: דער רצון פון אויבערשטן איז ניט (נאָר) אַז אידן זאָלן צוקומען צו ביטול צו אלקות, נאָר אַז ביי זיי זאָל זיך אויפטאָן (אויך) דער ענין פון זיכוך 35. און דער חילוק ביניהם 36:\nתוכן הביטול איז אַז עס פאַרלירט זיך די מציאות האדם און דורך דעם איז ער דבוק לאלקות; און הגם אַז דער אדם איז צונויפגעשטעלט פון פאַרשידענע כחות ואברים — ביז צום ריבוי התחלקות פון רמ\"ח אברים ושס\"ה גידים — האָט אָבער די התחלקות קיין אָרט ניט אין דער תנועה פון ביטול, וואָס פועל'ט דעם ביטול והעדר פון (זייער מציאות ובמילא פון) זייערע ענינים פרטיים, אַזוי אַז עס איז כאילו ניטאָ קיין חילוק צווישן זיי.\nדער ענין פון „זיכוך” איז, אַז ער גופא — איבריו וגידיו — ווערן נזדכך און",[["29","29","ראש „הדרן” על הרמב\"ם (קה\"ת, תשמ\"ה) בביאור דברי הרמב\"ם ריש הל' יסודי התורה."],["30","30","כמובן גם ממחז\"ל (זח\"א קע, ב. וראה מכות כג, סע\"ב) דרמ\"ח ושס\"ה הם כנגד איברים וגידים שאין דומים זל\"ז. וראה לקו\"ת עה\"פ תמים תהי' (נצבים מה, ג)."],["31","31","ראה בספרי טעמי המצות. ולהעיר מכוונות המצות — שיש כוונה כללית וכוונה פרטית (עט\"ר בסופו). וראה תניא רפמ\"א. לקו\"ת שלח מ, א. ובכ\"מ."],["32","32","ירושלמי סנהדרין פ\"ד, ה\"ב. מדרש תהלים ז, ח. יב, ז. זח\"ב טו, ריש ע\"ב. ועוד."],["33","33","במדב\"ר פי\"ג, טז. ובכ\"מ."],["34","34","שער הגלגולים הקדמה יז. וכ\"כ בש' רוה\"ק בענין היחודים על קברי צדיקים הקדמה ג' (קח, ב). לקוטי מהרח\"ו שבסוף שער מאמרי רז\"ל להאריז\"ל."],["35","35","וכמרז\"ל (ב\"ר רפמ\"ד. וש\"נ) „לא נתנו המצות אלא לצרף בהם את הבריות”. וראה לקו\"א להה\"מ סרנ\"ט (סז, רע\"א) בביאור המשנה שבפנים. תפארת ישראל (למהר\"ל) ספ\"ה. ועוד. וראה במדב\"ר ר\"פ בהעלותך."],["36","36","ראה גם בהנסמן בהערה 31. לקו\"ש ח\"ד ע' 1193 ואילך."]]],[1300171424,"ווערט איין זאַך מיט אלקות 37 — און אין דעם איז, אדרבא, נוגע דער ריבוי התחלקות פון די (כחות ו)אברים וגידים, וואָרום די הזדככות פון יעדן (כח ו)אבר וגיד מוז זיין בהתאם לתוכנו וענינו הפרטי.\nוויבאַלד אַז דער אויבערשטער האָט געוואָלט אַז ביי אידן זאָל זיך אויפטאָן דער ענין הזיכוך („לזכות”), „לפיכך הרבה להם תורה ומצות” — דערפאַר איז דאָ אַזאַ ריבוי והתחלקות אין תורה 37* ומצות, ווייל יעדער מצוה האָט איר ענין מיוחד וואָס פועל'ט אַ זיכוך אין אַ באַש־טימטן (כח און) אבר וגיד האדם 38 (ועד\"ז אין אַ חלק פון וועלט<sup data-n=\"39\">39</sup>, און אַזוי אויך אין תורה, אַז די ענינים שונים ומחולקים אין תורה זיינען פועל אַ זיכוך אין די אופנים שונים פון גדר השכל 40.\nח. מען דאַרף אָבער פאַרשטיין: ווי־באַלד דער אויבערשטער איז דאָך אחדות הפשוטה, וואָס מצד דעם האָבן אויך תומ\"צ געדאַרפט זיין באופן כזה, אַז אין זיי זאָל ניט זיין קיין ריבוי התחלקות וקווין שונים, און דאָס וואָס „הרבה להם תומ\"צ” איז נאָר „בכדי לזכות את ישראל” — קומט דאָך במילא אויס, אַז דער ריבוי אין תורה און מצות איז אַן ענין פון ירידה כביכול און איז ניט אַזוי פאַרבונדן מיט עצם התורה ומצותי', וואָס ענינם איז אחדות און פשיטות.\nאויף דעם ברענגט די משנה דעם פסוק „ה' חפץ למען צדקו יגדיל תורה ויאדיר”, אַז אדרבה, דער ריבוי בתורה ומצות טוט גאָר אויף כביכול אַ הגדלה והאדרה אין תורה, און דאָס איז דער־פאַר וואָס „ה' חפץ למען צדקו”.\nט. די הסברה בזה:\nס'איז ידוע אין דעם ענין פון נתאוה הקב\"ה להיות לו דירה בתחתונים 41 [וואָס די פנימיות הדירה איז „לדור ולשכון בנש\"י וכו' שיהיו כנס\"י מכון לשבתו ית' כו'” 42], אַז די „דירה” אמיתית איז דווקא ווען זי ווערט אויפגעטאָן דורך דעם זיכוך פנימי פון דעם אדם, ד. ה. אַז יעדער כח פרטי לפי מהותו וענינו ווערט מיוחד מיט אלקות, כנ\"ל.\nאָבער מצד דער כוונת הדירה ווי דאָס איז כביכול בעצמותו איז ניט שייך קיין גדר פון ריבוי און היפך הריבוי און מ'קען ניט זאָגן אַז אין עצמותו ית' ואחדות הפשוטה זאָל זיך הערן אַן ענין וואָס איז ח\"ו חוץ הימנו ואחדותו",[["37","37","להעיר ג\"כ ממשנ\"ת (לקו\"ש חט\"ז ע' 436-7; 439 ואילך) בהחילוק בין תורה למצות, יחוד וביטול. וראה לקו\"ש שם ע' 246 ואילך. 37*) להעיר משער הגלגולים (ולקוטי מהרח\"ו) שם: הנשמות הם ס' רבוא כו' התורה היא שרש נשמות כי ממנה חוצבה ובה נשרשו ולכן יש בתורה ס' רבוא פירושים כו' ונמצא כי מכל פי' מן הס' רבוא פירושים נתהוו נשמה אחת כו', ע\"ש."],["38","38","ראה במדב\"ר פי\"ד יו\"ד (קרוב לסופו): נתן להם תורה שבכתב שיש בה תרי\"ג מצות כדי למלאם מצות ולזכותם שנאמר ה' חפץ גו'. ולכן כל אדם מישראל צריך לבוא בגלגולים רבים עד שיקיים כל תרי\"ג מצות התורה במחשבה דבור ומעשה וישלים לבושי נפשו ולתקנם כו' כדי להלביש כל תרי\"ג בחי' וכחות שבנפשו אחת ממנה לא נעדרה כו' (אגה\"ק ר\"ס כט (קמח, ב) בשם האריז\"ל. הל' ת\"ת לאדה\"ז פ\"ד ס\"ד)."],["39","39","ראה במדב\"ר פי\"ז, ה."],["40","40","ראה הל' ת\"ת שם: ועוד אמרו חכמי האמת שכל נפש צריכה לתיקונה לעסוק בפרד\"ס כו', וכל מי שיכול להשיג ולידע הרבה כו' צריך לבוא בגלגול עד שישיג וידע כל מה שאפשר כו' הן בפשטי ההלכות הן ברמזים ודרשות וסודות כי כל מה שנשמתו יכולה להשיג ולידע מידיעת התורה זהו תיקון שלימותה וא\"א לה להתתקן ולהשתלם כו'."],["41","41","תנחומא נשא טז. ועוד."],["42","42","המשך תרס\"ו ס\"ע תסח. וראה תו\"א משפטים עו, ד. אוה\"ת שם ע' א'רסז. סה\"מ תר\"ל ע' סד. ועוד."]]],[1300171425,"הפשוטה. דוקא אין סדר ההשתל־שלות 43, וואו דער אור א\"ס ב\"ה ווערט נתצמצם וכו' ורצה הקב\"ה אַז עס זאָל זיין בעשרה מאמרות (און אין יעדערן פון זיי כו\"כ תיבות ואותיות) נברא העולם כאָטש אפילו אַז במאמר אחד יכול להבראות 44 און גיט אַן אָרט אויף ריבוי והתחלקות און עולם (ביז „נעשה אדם” לשון רבים) — דאָרטן ווערט נתגלה און דערהערט אַז דער ריבוי איז פון אחדותו ית', און אַז כוונת הדירה איז אין דעם, וואָס דאָס קומט דורך דעם זיכוך פרטי פון יעדער כח בפ\"ע 44*.\nיו\"ד. און דאָס איז דער חילוק צווישן דער לשון אין מרז\"ל און דעם לשון הכתוב:\nאין תורה שבכתב — כפי שאני נכתב 45 — דערהערט זיך יעדער ענין ווי ער איז אין שורש, אין פנימיות הכוונה, און בשרשו איז די כוונה „למען צדקו” — פון דעם אויבערשטן. אָבער ווי דאָס קומט אַראָפּ אין המשכה והתגלות, אין תורה שבעל פה — ע\"ד אני נקרא 45 — דאָרטן זאָגט זיך עס אַרויס אין אַן אופן פון „רצה הקב\"ה לזכות את ישראל”, כאילו ווי דאָס איז אַ באַזונדער זאַך, ובמילא איז דאָרט נוגע דעם זיכוך פון די כוחות פרטיים — לזכות את ישראל.\nאון דאָס איז אויך דער חילוק צווישן דעם לשון „רצה” און „חפץ”: „רצה” איז מתאר אַ תנועה 46, די תנועת הרצון, ווי ער ציט זיך (ער לויפט) צום דבר הנרצה (און דערפאַר שטייט דער לשון ביי „לזכות את ישראל”); און „חפץ” איז דער תענוג אין דעם רצון 47 (און דערי־בער איז „ה' חפץ למען צדקו”).\nאון עד\"מ ווי דאָס איז ביים אדם למטה, אַז דער רצון איז וואָס ער שטייט מיט אַ המשכה צו אַ זאַך וואָס איז אויסער אים; משא\"כ דער ענין החפץ, תענוג, איז עס ווי ער איז זיך מתענג.\nאון דערפון נעמט זיך דער אונטער־שייד אַז אין רצון, וואָס דער נפש ציט זיך צו אַ געוויסער זאַך, זיינען פאַראַן חילוקים מצד די פאַרבונדנקייט מיט ענינים צו וועלכע ער ציט זיך. משא\"כ תענוג, וואָס דער נפש איז זיך מתענג בעצמותו איז אין דעם ניטאָ קיין חילוק פון וואָס ער האָט דעם תענוג, ווייל ער איז ניט פאַרבונדן מיט דער זאַך, נאָר מיטן נפש אַליין 48.",[["43","43","להעיר מהמשך תער\"ב ח\"ב ע' א'קט. ועד\"ז בכ\"מ."],["44","44","אבות רפ\"ה. וראה ב' הפי' בזה בפרדס (שער ב' פ\"ז) רמ\"ז (לזח\"א דקל\"ה ע\"א). מד\"ש (אבות שם) הובא ונתבאר בד\"ה פדה בשלום תרנ\"ט. ד\"ה הנ\"ל (וד\"ה שלום רב) תש\"ז. 44*) ואולי י\"ל שזהו שנאמר הלשון „צדקו” כי מבואר בכ\"מ (לקו\"ת ראה כג, ג. המשך (ד\"ה והר סיני) שבועות תרס\"ב) דלשון צדק (צדיק) מורה על היושר ולמעלה הו\"ע מ\"ש צדיק ה' צדקות אהב ישר יחזו פנימו היינו שיהי' הגילוי אור למטה כמו שהוא למעלה ממש שבבחי' יחו\"ת שורה ומתגלה יחו\"ע, וזה נעשה ע\"י התרי\"ג מצות (שלכן נק' בשם צדקה), והיינו להיות בחי' אחדות פשוטה בתחתונים כמו שהוא למעלה אחדות פשוט. שזהו דוקא ע\"י שיש ריבוי התחלקות דכחות (וריבוי בעולם) והם מזדככים בענינם הפרטי ע\"י התרי\"ג מצות שאז הגילוי למטה הוא אחדות פשוטה כמו שהוא למעלה (ראה בארוכה בההמשך שם ד\"ה וירד הוי')."],["45","45","ראה פסחים נ, א."],["46","46","להעיר משני הפי' „ברצתה לעשות רצון קונה” (תו\"א א, סע\"ג. ועוד)."],["47","47","ראה לקו\"ת שלח לח, ג. ראה יח, ג. שה\"ש כח, ד. ובכ\"מ."],["48","48","בלקו\"ת (במדבר יח, ב ואילך) ובדרמ\"צ (מב, א ואילך) ובכ\"מ, מבואר שבחי' רצון העליון אין בה התחלקות. ולכן הרצון המלובש במצות כולל כל המצות בשוה כו', אבל העונג העליון ב\"ה המלובש במצות יש לכל מצוה תענוג פרטי, כי העונג הוא פנימי' המכוון המלובש ברצון כו', ע\"ש בארוכה. ואולי י\"ל שזהו כפי שהעונג הוא כבר בבחי' המשכה"]]],[1300171426,"יא. אין 49 תומ\"צ זיינען בכללות דאָ די צוויי מדריגות, ווי תורה איז למעלה, ווי זי שטייט העכער פון ריבוי און התחלקות, און ווי תורה ווערט נמשך אין השתלשלות און קומט אַראָפּ למטה, וואָס דאָס פועל'ט אַז אין איר זאָל זיין ריבוי התחלקות 50.\n[וואָס דאָס דריקט זיך אויך אויס אין דעם חילוק צווישן תורה און מצות, אַז תורה לגבי מצות איז אַן ענין פון אחדות 51, וכידוע 52 אַז תורה איז „נמשלה לדם”, וואָס דם איז אומעטום בכל מקום בגוף די זעלבע מציאות; און מצות צו אברים, וואָס יעדער אבר איז מוגדר אין זיין גדר וציור און איז אַנדערש פון אַ צווייטן אבר].\nאָבער דוקא דורכדעם וואָס תורה ווערט נמשך אין השתלשלות אין ריבוי התחלקות בכדי „לזכות את ישראל”, וואָס איז מצד „ה' חפץ למען צדקו” — מצד דער כוונה און תענוג בעצמותו 52* ית' 53, קומט צו אַן עילוי אויך אין דער מדריגה פון תורה ווי זי איז למעלה („יגדיל 54 תורה ויאדיר”) מער ווי דאָס איז אין תורה למעלה מצ\"ע (וע\"ד המבואר אין ספר הבהיר 55 אַז דוד הי' מחבר תורה שלמעלה בקוב\"ה), דהיינו אַז עס ווערט נמשך פון א\"ס אין תורה.\nאון דאָס איז דער טעם אויף דעם שינוי הלשונות צווישן דעם לשון חז\"ל און לשון הכתוב:\nאין תושב\"כ הערט זיך די תורה שלמעלה ווי זי איז בבחי' כלל 56, העכער פאַר ריבוי והתחלקות 57, וואָס דערי־בער איז אויך, אַז אין תושב\"כ זיינען „כל המצות בין מ\"ע ובין מל\"ת הן סתומות ולא מפורשות וגלויות וידועות” 58. משא\"כ אין תורה שבע\"פ ווערט נתגלה דער ריבוי והתחלקות פון מצות.",[["","","בהדבר (ע\"ש „כמו עד\"מ בפנים הרי התענוג שבראי' מלובש בעינים כו'”) וחיצוניות הרצון, אבל התענוג כפי שהוא בעצמותו, הרי אין שייך לומר ענין התחלקות וריבוי. וראה המשך תרס\"ו ע' סג ואילך. המשך תער\"ב שם. או י\"ל לאידך דדוקא מצד פנימיות התענוג כמו שהוא בעצמותו בא ונמשך פרטי התחלקות התענוג (משא\"כ מצד הרצון). וע\"ד המבואר בכ\"מ (ראה תו\"ח ד\"ה ויהי כל הארץ פכ\"ו ואילך. ד\"ה מי מדד תרס\"ב ועוד) ענין ההתחלקות וריבוי הבא דוקא מצד אחדות הפשוטה. ולהעיר ממשנ\"ת (לקו\"ש חי\"ט ע' 248 בנוגע לחיות פרטי."],["49","49","בהבא לקמן ראה תו\"ח מקץ פה, ג. אוה\"ת (יהל אור) תהלים ע' 352 ואילך. שה\"ש (כרך ב') ע' תשס ואילך. וש\"נ."],["50","50","וראה תניא קו\"א להבין מ\"ש בפע\"ח (קנה, ב). ד\"ה ואתם תהיו לי תר\"ס. חדא\"ג מהרש\"א מכות שם ד\"ה תרי\"ג."],["51","51","להעיר מתוספתא (סנהדרין פ\"ז, ד) כל התורה ענין אחד. צפע\"נ מהד\"ת פא, א. צפע\"נ עה\"ת הפטרה פ' ואתחנן. ועוד."],["52","52","לקו\"ת שם יג, א ואילך. ובכ\"מ. 52*) ראה לעיל הערה 44*."],["53","53","ראה המשך תער\"ב ח\"ב ע' תתקכג: ובאמת בבחי' פנימיות ועצמות אוא\"ס הרי מושרשת הכוונה שיהי' המשכה וגילוי אוא\"ס ב\"ה כו', ומ\"ש כחשכה כאורה זהו בבחי' חיצוניות אוא\"ס ובזה אמרו מה איכפת לי' אם שוחט ואוכל או נוחר ואוכל כו' אבל בפנימיות הרי דוקא שוחט ואוכל כו' שיהי' עבודה וימשיכו בנ\"י גילוי אלקות כו' (ע\"ש בארוכה בסוף הע' ואילך). ובהמשך תרס\"ו ס\"ע תקכא ואילך: אבל בפנימיות איכפת לי' כביכול, שי\"ל הכוונה שבפנימיות איכפת לי' כביכול הענין דלצרף את הבריות, הזיכוך דישראל. וראה לעיל הערה 44*."],["54","54","להעיר ממשנ\"ת במק\"א (לקו\"ש חי\"ט ע' 157 ואילך) בביאור מרז\"ל אימתי הוא גדול כשהוא בעיר אלקינו, שאמיתית הגדולה נעשית ע\"י התלבשות אלקות בריבוי נבראים כו', עיי\"ש."],["55","55","ראה זח\"ג רכב, ב. לקו\"ת שלח נא, א. ועוד."],["56","56","ראה לקו\"ת שה\"ש יא, ד. ועוד."],["57","57","להעיר מבמדב\"ר שבהערה 38 (הובא באוה\"ת שם). אבל ע\"ש שממשיך: זה המשנה שהיא גדולה מן המקרא."],["58","58","אגה\"ק סי' כט (קנא, א)."]]],[1300171427,"און דעריבער איז אין תושב\"כ מבואר די השלמת הכוונה וואָס ה' חפץ למען צדקו ווי דאָס ווערט אויפגעטאָן אין תורה (שלמעלה) וואָס איז העכער פאַר ריבוי והתחלקות און די הגדלה אין תורה איז באיכות — יגדיל תורה ויאדיר\n[וואָס בפרטיות ווערט אין דעם מבואר די הגדלה סיי אין תורה, סיי אין מצות ווי זיי שטייען אין תורה, וואָס דאָס זיינען די צוויי לשונות יגדיל ויאדיר 59: יגדיל איז די מעלת התורה וואָס „תלמוד גדול שהתלמוד מביא לידי מעשה” 60, ויאדיר איז די מעלת התורה בעצמותה ווי זי איז העכער אינגאַנצן פאַר מצות וואָס דאָס איז דער ענין המלוכה שבתורה 61 — „בי מלכים ימלכו” 62].\nמשא\"כ אין תורה שבע\"פ קומט דאָס אַרויס בגילוי „הרבה להם תורה ומצות”, כנ\"ל 62*.\nיב. דערמיט איז אויך מובן פאַר־וואָס עס שטייט „יגדיל תורה ויאדיר” בלשון עתיד (און ניט „הגדיל תורה והאדירה”), וואָרום די הגדלה והאדרה אין תורה שבכתב אין שורש למעלה, ווערט דוקא דורך הרבה להם תומ\"צ, ווי זיי קומען דערנאָך אַראָפּ למטה און ווערן נתגלה דורך תושבע\"פ — די הגדלה אין תורה טוט זיך אויף בעתיד — „יגדיל תורה ויאדיר”\nנאָך אורייתא קומט אַרויס (פון דעם רמיזא באורייתא<sup data-n=\"63\">63</sup> — תושבע\"פ און איר לימוד איז מביא לידי מעשה.\nאון דאָס איז אויך מתאים מיטן פירוש הפשוט פון „יגדיל תורה ויאדיר” אַז דאָס וועט זיין לעתיד לבא 64, ווייל אמיתית הגילוי דערפון וועט זיין נאָך דעם ווי עס וועט זיך אויספירן דער ענין פון „לזכות את ישראל” דורך „הרבה להם תומ\"צ” בפועל ובשלימות — לעתיד לבא.\nיג. עפכהנ\"ל קען מען אויך מבאר זיין די שייכות פון דער משנה ר\"ח בן עקשיא אומר צו פרקי אבות (וועלכע מ'לערנט אַלס אַ הכנה צו מתן תורה בחג השבועות):\nדער ברטנורא 65 זאָגט אין אַנפאַנג אבות: לפי שמסכת זו אינה מיוסדת על פי מצוה ממצות התורה כשאר מסכתות שבמשנה אלא כולה מוסרים ומדות וחכמי אומות העולם ג\"כ חברו ספרים כמו שבדו מלבם בדרכי המוסר כיצד יתנהג האדם עם חבירו לפיכך התחיל התנא במסכת זו משה קבל תורה מסיני לומר לך שהמדות והמוסרים שבזו המסכת לא בדו אותם חכמי המשנה מלבם אלא אף אלו נאמרו בסיני.\nקען דאָך ווערן אַ שאלה: וויבאַלד אַז עס זיינען דאָ אַזעלכע מוסרים ומדות אין די ספרים פון חכמי אומות העולם,",[["59","59","ראה הל' ת\"ת לאדה\"ז פ\"ד ס\"ב וג', דב' מעלות בתורה לגבי מצות, עיי\"ש."],["60","60","קידושין מ, ב."],["61","61","ראה גיטין נו, ב: אין אדיר אלא מלך. ובמנחות (נג, סע\"א) יבוא אדיר כו'. הצ\"צ לתהלים (יהל אור) צג, ד."],["62","62","משלי ח, טו. ראה גיטין סב, סע\"א. 62*) וזהו גם הטעם לשינוי השם — „ה' חפץ”, רצה הקב\"ה: דבתושב\"כ שבה נרגש כפי שהוא בשרשו, למעלה מריבוי והתחלקות, נאמר שם הוי', שם העצם (פרדס ש\"ט. מו\"נ ח\"א פס\"א ואילך. ועוד), ושם המיוחד (סוטה לח, א. סנהדרין ס, א. וראה פרדס שם). משא\"כ בתושבע\"פ שבאה בהתגלות וריבוי כו' אומר „הקב\"ה” שקאי על בחי' ז\"א (תו\"א יב, ד. וראה לקו\"ת תזריע כב, ג. ובכ\"מ)."],["63","63","ראה תו\"א פח, רע\"ג. המשך תרס\"ו ע' שצג. ובכ\"מ. וראה אגה\"ק סו\"ס כט. וראה תענית ט, א שאפילו נ\"ך רמיזי באורייתא."],["64","64","ראה רד\"ק ישעי' שם."],["65","65","וראה מדרש שמואל שם."]]],[1300171428,"איז פאַרוואָס האָט מען אויף זיי גע־דאַרפט אָנזאָגן בסיני אַלס אַ טייל פון תורה דוקא ?\nווערט דאָס מבואר דורך דער משנה „רצה הקב\"ה לזכות את ישראל לפיכך הרבה להם תומ\"צ”, אַז דער ענין פון תומ\"צ איז בכדי צו מזכך זיין אַלע כחות (ומדות) פון מענטשן — ומהאי טעמא זיינען אויך די „מוסרים ומדות” הנ\"ל געזאָגט געוואָרן בסיני אַלס אַ חלק אין תורה, וואָרום די כוונה איז ניט נאָר צו מודיע זיין „כיצד יתנהג האדם עם חבירו”, נאָר בעיקר צו פועל זיין דעם בירור וזיכוך פון די מדות, וואָס דאָס קען זיין דוקא ווען זיי זיינען נכלל אין „הרבה להם תומ\"צ” 66, וואָס דוקא דעמאָלט האָבן זיי דעם כח צו מזכך זיין די מדות און כחות פרטיים אַז זיי זאָלן ווערן כלים צו אלקות 67.\nיד. און כדי צו נאָכמער מסביר זיין אַז ענינה פון תורה איז צו פועל זיין דעם זיכוך המדות והכחות פון אַ מענטשן —\nבשלמא ווען עס וואָלט זיך גערעדט וועגן די כחות הנשמה, קען מען עס פאַרשטיין, וואָרום דער שורש הנשמות איז העכער פון שורש התורה, ווי חז\"ל 68 זאָגן „מחשבתן של ישראל קדמה לכל דבר” (אויך צו תורה);\nדאָ רעדט זיך דאָך אָבער בעיקר — וויבאַלד המעשה עיקר 69 — וועגן דעם בירור וזיכוך פון די מדות טבעים פון נה\"ב, ביז צום זיכוך פון די אברי גוף הגשמי, וואָס בחיצוניות איז ער ניט אַנדערש ווי דער גוף פון אַן אינו יהודי 70, היינט ווי איז שייך אַז דער ענין און תכלית פון תורה במעלתה הכי נעלית איז צו מברר 71 זיין די כחות ומדות פון גוף ונה\"ב ?\nדעריבער איז מען מקדים די משנה „כל ישראל יש להם חלק לעוה\"ב”, וואָס עוה\"ב דאָ מיינט ניט ג\"ע נאָר עולם התחי', נשמות בגופים 71*, און דאָס זאָגט מען בנוגע צו יעדן אידן 72, ווייל אויך מצד גופו איז יעדער איד „נצר מטעי מעשה ידי להתפאר”, וכידוע 73 אַז בחירת הקב\"ה (וואָס אמיתית ענין הבחירה איז אין עצמות) איז בשייכות צום גוף פון אַ אידן. ובמילא איז מובן אַז ס'איז קיין תמי' ניט וואָס כל ענינה של התורה איז צוליב דער כוונה „לזכות את ישראל” 74, די מדות און גוף גשמי שלו 75,",[["66","66","שלכן נאמר במשפטים „לפניהם” ולא לפני עו\"כ ואפילו דנים אותו כדיני ישראל (גיטין פח, ב. שו\"ע חו\"מ רסכ\"ו)."],["67","67","ולהעיר מזרוע ימין להחיד\"א ריש מס' אבות."],["68","68","ב\"ר פ\"א, ד. וראה המשך תרס\"ו ד\"ה וידבר גו' במדבר סיני. ועוד."],["69","69","אבות פ\"א, מי\"ז."],["70","70","תניא פמ\"ט."],["71","71","להעיר מקונטרס ענינה של תורת החסידות סי\"ט בביאור מרז\"ל (קידושין ל, ב) בראתי יצה\"ר ובראתי לו תורה תבלין. 71*) וראה לעיל ע' 344 ואילך."],["72","72","ראה בארוכה תשובות וביאורים סי' ח'*, וש\"נ."],["73","73","תניא שם. ובארוכה ס' השיחות תורת שלום ע' 120 ואילך."],["74","74","ראה תורת שלום שם ע' 123. מפתגמי רבינו הזקן: מען האָט גאָר קיין השגה ניט, ווי עס איז טייער באַ השי\"ת דער גוף פון אַ אידן (היום יום ס\"ע צא)."],["75","75","ראה המשך באתי לגני ה'שי\"ת פ\"ד: והאדם הוא בציור רמ\"ח אברים ושס\"ה גידים שהם במספר תרי\"ג, דלכן כל המדרי' בהשתל' הם במספר הזה, ולכן הנה גם בהנשמה הרי יש ג\"כ תרי\"ג כחות, שבהם תלויים התרי\"ג מצות. *) אגרות קודש כ\"ק אדמו\"ר שליט\"א ח\"א ע' קמב ואילך. המו\"ל."]]],[1300171429,"און דוקא דורכדעם ווערט נמשך אין תורה אויך דער „חפץ ה'” וואָס אין עצמותו ית', עס ווערט יגדיל תורה ויאדיר.\n(משיחת ש\"פ אחו\"ק תשכ\"ד) ---"],[1300171430,"לערכופורו ששש ש 8 8 9 ש 8 שיחות ומכתבים"],[1300171431,"הוספות\nויקרא . . . . . . . . , . .\n:\n. . . . . . . . . . . , . . . . . . . . . . . . . . . .\n421 ' 422\nב' ניסן ........... .............. ..............\n423\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n426 ' . . ' 428 . . ' . 434\nחג הפסח . . . , . . . . , . . . . . . . . . . . . . , . . . . . . . , . . . . . .\n435 ניסן צו\n. . . . . . .\n, . , ,\n. . . . . . . . . . . . . .\nי\"א ניסן ...... ..............\n. . . . . ' ' ' ' ' ' . .״' . . ' '\n. . . .\n'\n. . .\nערב פסח . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n' ' . . '\nימי הספירה . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n. . . . . . .\nשמיני . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n468\n. . . . . . . . . , . . . . . . . . , . . . .\n469 . 469\n. , . . .\n470\n. . . . . . . . . . . . . . . . . . . . . . . . . .\n475 ' ' ,\nפהקי אבות -פ \" א\n. . . . . .\n,\nאייר . . . . . . , . . . . . , . . . . . . . . . . . . . .\n' ' . ' ' '\n. . . . . . . .\nתזריע . . ' , .״, . . . . . . . . . . . . . . . . . . . . . . . . . .\nמצורע\n. . . . . . . . , . . .\n, ' ' 466 . . . . . . .\nאחרי . . . . . . . . . . . . . . . . . . . . . . .\nקדושים . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n492 . 502 ' , ' ' ' ' ' , ' , 484\nאמור . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n. . . . . . . . .\n. . . . . . . . . . . . . . . . . . . . . . . . .\nל\"ג בעומר\n505\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n520 . 522 , , ' ' ,\nבהר . . . .\n,\nבחוקותי . . , . . . . . . . . . , . . . . , . . . . . . . . . . . . , . . . .\n- *- . '"],[1300171432,"<h3>ויקרא</h3>\n... והשי\"ת יצליחו לקיים מרז\"ל אין ושחט אלא ומשך, לקיים גם ברוחניות, היינו להמשיך את נה\"ב שלו וגם דסביבתו, לרשות היחיד יחידו של עולם, שתוכל להתהפך לדם ובשר כבשר האדם, אתם קרויים אדם, על שם אדמה לעליון אדם העליון שעל הכסא.\n(ממכתב ט\"ז תמוז תשי\"ג)\n... עס איז אַ גלייכע זאַך צו משלים זיין אומנות השחיטה אויך בנוגע שחיטה ובדיקה לדקות וגסות ... און ... ווי געזאָגט, איז נכון וטוב ביותר צו וויסען די אומנות השחיטה ובדיקה בשלימותה.\nבודאי ידוע לו המבואר בכמה מקומות ומהם מאדה\"ז והצ\"צ אשר שו\"ב צריך להיות ירא שמים ביותר וביותר גאָר כפשוטו אַ ירא שמים בשלשת הקוים דתורה עבודה וגמילות חסדים, ובפרט אלו שזכו לאור החסידות, צריכים להיות חדורים באור וחיות חסידותי. והשי\"ת יצליחו,\nובכדי להרבות הסייעתא דשמיא בזה, אחת הסגולות הוא ענין הפצת המעינות חוצה, ובכלל קירוב בני ישראל לאבינו שבשמים, וק\"ל.\n(ממכתב י\"ז ניסן תשי\"ז)\n... במ\"ש אשר ידיו רועדות, לפעמים במקצת ולפעמים יותר קצת ולכן אינו רוצה להתעסק בלימוד אומנות השו\"ב,\nהנה יתייעץ בזה עם השובי\"ם דאנ\"ש הנמצאים על אתר, שיבחנו את הרעידה הנ\"ל אם אינו רק דמיון בעלמא ...\n(ממכתב י\"ח אדר ב' תשי\"ד) ---"]]});
